-- Load safety messages from safety_messages_supabase.csv
-- Run this once in the Supabase SQL editor for project pecqbyttkqqtiindweeo.
-- It replaces any rows already in public.safety_messages.

begin;

truncate table public.safety_messages restart identity;

insert into public.safety_messages (
  id,
  slug,
  title,
  summary,
  body_markdown,
  category,
  tags,
  links,
  published_date,
  sent_at,
  is_published,
  source_email_subject,
  original_title,
  original_body,
  editor_notes
)
overriding system value
select
  (item->>'id')::bigint,
  item->>'slug',
  item->>'title',
  item->>'summary',
  item->>'body_markdown',
  item->>'category',
  coalesce((
    select array_agg(tag order by ord)
    from jsonb_array_elements_text(item->'tags') with ordinality as parsed(tag, ord)
  ), '{}'::text[]),
  coalesce(item->'links', '[]'::jsonb),
  (item->>'published_date')::date,
  (item->>'sent_at')::timestamptz,
  (item->>'is_published')::boolean,
  nullif(item->>'source_email_subject', ''),
  nullif(item->>'original_title', ''),
  nullif(item->>'original_body', ''),
  nullif(item->>'editor_notes', '')
from jsonb_array_elements($safety_import$[{"id":1,"slug":"plan-a-buffer-before-ect-or-curfew","title":"Plan a Buffer Before ECT or Curfew","summary":"Build a time buffer before ECT or curfew, use the latest-time-of-departure form, and be on the ground 30 minutes before ECT unless night-current.","body_markdown":"It's good practice to give yourself an appropriate buffer before either ECT or curfew, whichever is more restrictive. With flying, everything always takes longer than you expect.\n\nThat's why we build in additional margin. This is especially important on cross-country flights, where you may be delayed by other traffic.\n\nThe back of our XC sign-out sheet has a **latest time of departure** form. Use it to work out your latest departure time for each leg – for example, on a return flight to Foxpine.\n\nOur SOPs state you should be **on the ground 30 minutes before ECT unless you are night-current**. Landing after ECT or curfew is a breach of the law and must be reported accordingly.\n\nIf you're not sure, speak to one of the instructors before your next cross-country flight.","category":"Procedures & SOPs","tags":["ect","curfew","cross-country","flight-planning","sop"],"links":[],"published_date":"2024-05-31","sent_at":"2024-05-31T02:03:26+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 31st May 2024","original_title":null,"original_body":"It is good practice to give yourself an appropriate buffer to either ECT or curfew, whichever is the most restrictive. With flying, everything always takes longer than you expect.\n\nThis is why we give ourselves some additional margin. This is especially important on cross-country flights, where you may get delayed due to other traffic.\n\nOn the back of our XC Sign Out sheet we have the latest time of departure form. See below for an example filled out for a return flight to Foxpine.\n\nOur SOPs state you should be on the ground 30 minutes before ECT unless you are night-current. Landing beyond ECT/curfew is a breach of the law and must be filed accordingly.\n\nSpeak to one of the instructors before your next cross country flight if you're not sure.","editor_notes":"Removed image reference ('See below for an example'), reworded as how to use the form; light copy edit."},{"id":2,"slug":"use-the-correct-engine-oil","title":"Use the Correct Engine Oil","summary":"Always use the manufacturer-specified oil (15W50 for most of the fleet, 100 grade when running in), check the flight manual and record oil added in the register.","body_markdown":"Oil serves three main purposes in our engines: **lubricating, cooling and cleaning**.\n\nUsing the wrong oil grade can damage the engine because it won't properly lubricate the components. This leads to metal-on-metal contact, and the friction that follows quickly wears engine parts.\n\n**Always use the oil specified by the aircraft manufacturer.** The correct oil type is listed in the flight manual.\n\n- Most of our fleet uses **15W50** when engines are operating normally. This is kept by the cabinet in the hangar.\n- When an engine is being **run in**, we use **100 grade** oil. The correct oil must be used during running-in – the wrong oil will cause problems with the seals and can ruin the engine.\n\nAlways check the flight manual and confirm the oil you're adding matches. Once you've added oil, **fill out the oil register** so we can keep track of each aircraft's oil consumption. If there's no oil left, let an instructor know.","category":"Aircraft & Engine","tags":["oil","engine","preflight","running-in","oil-register"],"links":[],"published_date":"2024-06-07","sent_at":"2024-06-07T04:37:39+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 7th June 2024","original_title":null,"original_body":"Oil serves 3 main purposes in our engines: lubricating, cooling, and cleaning.\n\nUsing the wrong oil grade can cause engine damage because it does not properly lubricate its components. This will lead to metal-on-metal contact. Friction quickly follows, causing engine parts to wear.\n\nAlways use the oil specified by the aircraft manufacturer.\n\nThe oil type used can be found in the flight manual. Generally speaking, most of our fleet uses 15W50, when engines are operating normally. We keep this oil by the cabinet in the hangar. When one of our engines is 'running in' we use 100 grade oil. The correct oil must be used when running in an engine as failure to do so will cause issues in the seals and ruin the engine.\n\nAlways check the flight manual and confirm the oil you are putting in matches. Once you've put in the oil please fill out the oil register so we can keep track of the oil consumption of an aircraft. If there is no oil left - let an instructor know.","editor_notes":"Light copy edit; added list formatting."},{"id":3,"slug":"watch-for-ifr-traffic-on-the-rnp-16-approach","title":"Watch for IFR Traffic on the RNP 16 Approach","summary":"IFR aircraft fly the NZPP RNP RWY 16 approach entirely in uncontrolled airspace from NOKIX; know where to look and listen out for inbound IFR traffic.","body_markdown":"If you're flying around Paraparaumu and hear on the radio that an IFR Saab 340 is inbound to land at NZPP, do you know where to look for it?\n\nWe tend to give way to IFR aircraft because of their speed or size, or because they may still be in instrument meteorological conditions (IMC) and unable to look out for traffic. That's why it's important to have a good idea of where to look for possible conflicts, so we can avoid them.\n\n### The RNP RWY 16 approach\n\n- The **entire approach is in uncontrolled airspace** and inside the Paraparaumu MBZ.\n- IFR aircraft start the approach at **NOKIX, 12 NM north of NZPP at 3,550 ft**, and descend at **300 ft per NM**.\n\nNow imagine the cloud ceiling is 1,500 ft. The incoming aircraft won't be able to see traffic flying below the cloud until it is only **5 NM** from the aerodrome.\n\nSo if you're flying between the northern tip of Kāpiti Island and Peka Peka, you're likely very close to that approach path. Listen out, and if you hear IFR traffic inbound, start thinking about where it will be relative to you.\n\nThe approach chart is published in AIP New Zealand – take a look so you can picture the approach path.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Airspace & Radio","tags":["ifr","rnp","nzpp","lookout","mbz","traffic-awareness"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2024-06-14","sent_at":"2024-06-14T04:55:59+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 14th June 2024","original_title":null,"original_body":"If you're flying around Paraparaumu and you hear on the radio that an IFR Saab 340 is coming in to land at NZPP, do you know where to look for them?\n\nWe tend to give way to IFR aircraft due to their speed or size, or for when they may still be in Instrument Meteorological Conditions (IMC) and can't look out for traffic. For this reason it is important that we have a good idea of where to look for possible traffic conflicts in order to avoid them.\n\nFor example, this is what the RNP RWY 16 approach at NZPP looks like:\n\nOne of the key things to note about this approach is the fact that the ENTIRE approach is in uncontrolled airspace and inside the Paraparaumu MBZ. IFR aircraft start the approach at NOKIX, 12 NM north of NZPP at 3,550 feet and descends at 300 feet per NM.\n\nNow imagine the cloud ceiling is 1,500 feet. That means the incoming aircraft won't be able to see traffic flying below the cloud until they are only 5 NM from the airport.\n\nSo if you're flying between the northern tip of Kapiti Island and Peka Peka, you're likely very close to that approach path. This is why it is important to listen out and if you hear IFR traffic coming in, start to think about where they will be relative to you.","editor_notes":"Removed image reference ('this is what the approach looks like'); added pointer to the approach chart in AIP NZ; added macron to Kāpiti."},{"id":4,"slug":"prevent-fuel-exhaustion-starvation-and-contamination","title":"Prevent Fuel Exhaustion, Starvation and Contamination","summary":"Fuel exhaustion, starvation and contamination cause 40% of engine failures; dip the tanks, drain and check fuel, and carry KDAC reserves (45 min day, 1 h 15 min night).","body_markdown":"**40% of engine failures** are caused by fuel exhaustion, starvation or contamination.\n\n- **Starvation** – the fuel supply to the engine is interrupted even though there is adequate fuel on board. This is the most common of the three. Typical causes include a tank being inadvertently run dry, or mechanical issues.\n- **Exhaustion** – the aircraft is completely out of fuel. This can result from incorrectly dipping the fuel during the pre-flight, underestimating the fuel required for the flight, or a leak in the fuel system.\n- **Contamination** – a foreign substance such as water, dirt or fungi is in the fuel. Contaminants can hinder combustion and block fuel lines. The most common cause is an unsatisfactory pre-flight.\n\nBefore each flight, dip the aircraft's tanks and be confident you have sufficient fuel for the flight, accounting for unusable fuel and KDAC reserves.\n\n**The dipstick should only ever be in one of two places: in your hand or in the aircraft.**\n\nDrain fuel from each fuel drain and check it for contaminants, especially after refuelling.\n\n### KDAC fuel reserves\n\n- **Day:** 45 minutes\n- **Night:** 1 hour 15 minutes\n\nFor more on fuel management, read the CAA's Fuel management GAP booklet.\n\n**Further reading:**\n\n- [CAA GAP booklet: Fuel management (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf)\n- [CAA Vector: Dip 'n check](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dip-n-check/)","category":"Aircraft & Engine","tags":["fuel","fuel-management","preflight","reserves","engine-failure"],"links":[{"label":"CAA GAP booklet: Fuel management (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf"},{"label":"CAA Vector: Dip 'n check","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dip-n-check/"}],"published_date":"2024-06-27","sent_at":"2024-06-27T03:38:39+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 27th June 2024","original_title":null,"original_body":"40% of engine failures are caused by fuel exhaustion, starvation, or contamination.\n\nStarvation , where the fuel supply to the engine is interrupted although there is adequate fuel on board the aircraft, is the most common. The most common causes include a tank being inadvertently run dry or mechanical issues.\n\nExhaustion is when the aircraft is completely out of fuel. This can be because of incorrect dipping of fuel in the pre-flight, underestimating fuel required for a flight, or a leak in the fuel system.\n\nContamination is when there is a foreign substance in the fuel e.g. water, dirt, or fungi. These contaminants can hinder combustion and block fuel lines. The most common cause of this is an unsatisfactory pre-flight.\n\nBefore each flight, we need to dip our aircrafts tanks and be confident there is sufficient fuel for our flight, accounting for unusable fuel and KDAC reserves.\n\nThe dipstick should be one of two places: in your hand or in the aircraft.\n\nThe fuel needs to be drained from each fuel drain and checked for contaminants, especially after refueling.\n\nKDAC RESERVES\n\nDay - 45 minutes Night - 1 hour 15 minutes\n\nFor further reading on fuel management, read the Fuel Management GAP Booklet from the CAA by clicking here .","editor_notes":"Replaced 'click here' link with verified GAP booklet link; list formatting; spelling fixes (aircraft's, refuelling)."},{"id":5,"slug":"confirm-visually-c152-primer-vs-park-brake","title":"Confirm Visually: C152 Primer vs Park Brake","summary":"Use the checklist on every flight, don't rush, and visually confirm controls – in the C152 the park brake knob can be pulled by mistake when checking the primer is locked.","body_markdown":"Checklists standardise procedures, minimise human error and make sure nothing is overlooked. From pre-flight to shutdown, **using the checklist is not optional – it's a must**.\n\nAs keen aviators, we're eager to get the aircraft started and into the sky. Rushing can lead to poor checklist use, with items skipped or not checked properly.\n\n### A known trap in the C152\n\nA risk has been identified in the pre-landing checklist (BUMPFH) in the C152. When checking the **primer is locked**, if we don't also confirm visually, the **park brake knob can be pulled instead**. The park brake sits just above the primer and has a similar handle. The result is a landing with the park brake on.\n\n### Remember when using checklists\n\n1. **Consistency** – use the checklist on every flight.\n2. **Don't rush** – rushing can lead to missed items.\n3. **Confirm visually** – if an item requires you to move a control or switch, look to confirm you're selecting the right one.\n\nChecklists are not a formality – they are a vital tool for safe operation in aviation.","category":"Procedures & SOPs","tags":["checklist","c152","bumpfh","park-brake","primer"],"links":[],"published_date":"2024-07-05","sent_at":"2024-07-05T04:27:37+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 5th July 2024","original_title":null,"original_body":"Checklists are made to standardise procedures, minimising human error and ensuring that nothing is overlooked. From pre-flight to shut-down using our checklist is not a question, it is a must0\n\n.As keen aviators, we are eager to get the aircraft started and into the sky. Rushing can lead to improper checklist use with items being skipped or not checked correctly.\n\nAn area of risk within our pre-landing checklist (BUMPFH) flying the 152 has been identified. When checking that our engine primer is locked if we do not confirm visually as well, the park brake knob can be pulled instead of checking the primer is locked. This is due to its location being above the primer and the handle being similar to that of the primer. This will lead to a landing with the parking brake on.\n\nWhat we need to remember with our checklist use:\n\n1. Consistency : Always using our checklists, for every flight. 2. Not to rush : rushing through our checklist can lead to items being missed. 3. Confirm Visually : If there is an item that requires you to manipulate a control or switch, confirm that we are selecting the right one.Checklists are not a formality, they are a vital tool for safe operation in the aviation environment.","editor_notes":"Fixed garbled punctuation/typos ('a must0', '.As'); reformatted the run-on numbered list."},{"id":6,"slug":"apron-safety-bfrs-and-linton-airspace","title":"Apron Safety, BFRs and Linton Airspace","summary":"Treat propellers as live and escort passengers airside; use your BFR to genuinely sharpen skills; stay above 1,200 ft or well clear of Linton military airspace.","body_markdown":"### Safety on the apron\n\nStay vigilant whenever you're airside – **aircraft can start at any time**. Look for warning signs that someone may be about to start up, such as a person sitting in an aircraft or a flashing beacon.\n\n**Always treat propellers as live.** Approach aircraft from behind, cross behind other aircraft, and keep your distance.\n\n- No smoking or vaping on the apron.\n- Avoid distractions such as mobile phones.\n- **Passengers must be escorted at all times.**\n\nAs pilots we're familiar with the hazards airside, but your passengers might not know that a flashing beacon means the propeller is about to start turning. Brief passengers thoroughly before they step airside.\n\n### Biennial Flight Review (BFR)\n\nOnce you hold a licence, you need a Biennial Flight Review (BFR) every two years. During a BFR the instructor reviews your current knowledge and proficiency, giving you a chance to maintain and improve your skills. It's not a test where you have only one opportunity to pass – if you're not up to scratch, you'll get the chance to practise until you are. The requirements are set out on the CAA BFR form. The CAA has also asked instructors and examiners to assess the topics from its Work Together, Stay Apart campaign.\n\nA BFR is more than a box-ticking exercise – we want to keep you and others safe. How many flights it takes depends on the competency and currency of the licence holder. When did you last practise a forced landing? Or low flying? Real situations that need these manoeuvres can happen at any time, so they need to be practised regularly.\n\nThere's a difference between 'good' and 'good enough'. Ask yourself:\n\n- Wouldn't you want to be 100 percent comfortable carrying out a forced landing without power (FLWOP)?\n- Isn't an hour or two of practice worth it to be comfortable with your ability?\n- Would your next passenger be comfortable if they knew you hadn't practised a FLWOP for more than a year?\n\nManoeuvres in the BFR need to meet the standard of the applicable licence.\n\n### Linton Military Camp\n\nAvoid the Linton military airspace just south of NZPM. Make sure you're either **above 1,200 ft or well clear** of the area. Drones are often flown up to the limit of the airspace, so operating within it can be very dangerous.\n\n**Further reading:**\n\n- [CAA Vector: All about BFRs](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/all-about-bfrs/)\n- [CAA: Work Together, Stay Apart](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-initiatives/work-together-stay-apart/)\n- [CAA: Flight test standards guides](https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-test-standards-guides/)","category":"Ground Ops","tags":["apron","propeller","passengers","bfr","linton","military-airspace"],"links":[{"label":"CAA Vector: All about BFRs","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/all-about-bfrs/"},{"label":"CAA: Work Together, Stay Apart","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-initiatives/work-together-stay-apart/"},{"label":"CAA: Flight test standards guides","url":"https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-test-standards-guides/"}],"published_date":"2024-07-12","sent_at":"2024-07-12T04:55:23+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 12th July 2024","original_title":null,"original_body":"SAFETY ON THE APRON\n\nIt is important that we remain vigilant when we are airside. Aircraft can start at any time. We need to be looking for the warning signs someone may be about to start up: e.g. someone sitting in an aircraft or a flashing beacon.\n\nPropellers should always be treated as live. This means, we approach the aircraft from behind and cross behind other aircraft. Keep your distance.\n\nSmoking and vaping have no place on the apron. Distractions, such as cell phones, should be avoided as well. Passengers must be escorted at all times.\n\nAs pilots, we are familiar with the hazards of being airside, but your passenger might not know a flashing beacon means the propeller is about to start spinning. Passengers should be thoroughly briefed before stepping airside.\n\nBIENNIAL FLIGHT REVIEW (BFR)\n\nA Biennial Flight Review (BFR) is a flight review every two years, once you obtain your license. During a BFR, the instructor reviews your current level of knowledge and proficiency, giving you a chance to maintain and improve your skills. It is not a test where you have only one opportunity to pass. If you're not up to scratch, you'll get a chance to practice until you are. All the requirements of the test can be found in the CAA BFR form . Last week, the CAA sent out an email to instructors & examiners to assess the topics presented in their Work Together, Stay Apart campaign.\n\nThe BFR is more than just a box-ticking exercise - we want to keep you and others safe! How many flights a BFR takes depends on the competency and currency of the license holder. When did you last practice a forced landing? Or low flying? Real-life situations that require these maneuvers can happen at any time - they need to be practiced regularly.\n\nThere is a difference between 'good' and 'good enough'. Ask yourself the following questions :\n\nWould you not want to be 100 percent comfortable in carrying out a FLWOP?\n\nIs it not worth one or two hours of practice to be comfortable with your ability?\n\nWould your next passenger be comfortable if they knew you hadn’t practiced a FLWOP for more than a year?\n\nManouvers in the BFR need to meet the standard of the applicable licence. There is a really good article in Vector for some further reading.\n\nLINTON MILITARY CAMP\n\nA friendly reminder to avoid Linton Military airspace just south of NZPM. Ensure you are either above 1200ft or well clear of the area. They often fly drones up to the limit of the airspace, so operating within the airspace can be quite dangerous.","editor_notes":"Multi-topic flyer kept as one entry with subheadings; reworded 'Last week, the CAA sent out an email...' as timeless; spelling (licence, manoeuvre, practise); replaced 'really good article in Vector' with verified link."},{"id":7,"slug":"recognise-and-treat-carburettor-icing","title":"Recognise and Treat Carburettor Icing","summary":"Carb icing can occur from about -10°C to +25°C in humid conditions; check for it in SCADIE checks and apply full carb heat, expecting rough running until the ice clears.","body_markdown":"Weather in the Paraparaumu region is often conducive to carburettor icing, and members and instructors have reported it on multiple occasions. Here's a refresher on recognising, preventing and treating it.\n\n- Carburettor icing can occur across a wide temperature range – **approximately -10°C to +25°C** – especially when relative humidity is high.\n- Regular **SCADIE checks every 15 minutes**, which include cycling the carb heat, can tell us whether carb ice is forming.\n- **Symptoms:** decreasing RPM, rough running or complete engine failure.\n\nIf carb icing is suspected, **apply full carb heat**. Expect rough running to continue for a short time, as the ice won't melt immediately – and as it melts, the water is drawn into the engine, which also causes rough running.\n\n**Key point: carb heat is not an immediate fix.** It takes time for the ice to melt, and the engine will run rough until the ice is completely clear.\n\n**Further reading:**\n\n- [CAA Vector: Icing](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/)\n- [CAA safety message: Check the carb icing graph](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/)","category":"Aircraft & Engine","tags":["carb-icing","carburettor","carb-heat","scadie","engine"],"links":[{"label":"CAA Vector: Icing","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/"},{"label":"CAA safety message: Check the carb icing graph","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/"}],"published_date":"2024-07-19","sent_at":"2024-07-19T04:49:25+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 19th July 2024","original_title":null,"original_body":"Over the past week there have been multiple reports of carburettor icing from members and instructing staff. Weather conditions in the Paraparaumu region have been conducive to carburettor icing this past week.\n\nThis message is to help refresh ourselves on the procedures for recognition, mitigation and the remedy of carburettor icing.\n\nCarburettor icing can occur in both high and low temperatures, approximately From -10C to +25C. This is especially true in conditions of high relative humidity.\n\nRegular SCADIE checks every 15 minutes require the cycle of carb heat and can tell us if there is carb icing.\n\nDecreasing RPM, Rough running or complete engine failure are symptoms of carb icing.\n\nIf carb icing is suspected apply full carb heat. Expect rough running to continue for a brief period as the ice will not melt immediately. As the ice melts the water produced will be sucked into the engine causing rough running as well. The key point to remember is carb heat is not an immediate remedy, it takes time for the ice to melt and the engine will run rough  until the ice is completely clear.","editor_notes":"Removed time-bound references ('Over the past week', 'this past week'); list formatting; copy edit."},{"id":8,"slug":"surviving-a-forced-landing-in-the-bush","title":"Surviving a Forced Landing in the Bush","summary":"A Vector story about a pilot who flew into the wrong valley in deteriorating weather and survived a bush forced landing; read the full article for the lessons.","body_markdown":"*From CAA Vector:* after a forced landing in the bush, this pilot did three things that made the difference between survival and possible death.\n\nIt was the end of a successful winter hunting weekend in the Kaimanawa Forest Park. The pilot – whom Vector calls John – his dog, his sister and their hunting buddy boarded John's Cessna 172, bound for home.\n\nJohn (PPL, with around 600 hours at the time) had already flown some of their gear out. As they prepared for their final departure mid-afternoon, he noticed the weather deteriorating more quickly than expected. He decided they would head for Tūrangi rather than Taupō or Taihape.\n\n\"It was a routine flight, operating in an area I know well,\" John says.\n\n\"Coming out with the second load and my passengers, visibility seemed not too bad. I came through the trickiest part to navigate, but then there are two valleys with similar headings – and I flew into the wrong one.\"\n\nRead the full story in CAA Vector magazine to find out what happened next, and the three things that made the difference.\n\n**Further reading:**\n\n- [CAA Vector magazine archive](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-magazine-archive/)\n- [CAA GAP booklet: Survival (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf)","category":"Emergencies","tags":["forced-landing","survival","vector","weather","navigation"],"links":[{"label":"CAA Vector magazine archive","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-magazine-archive/"},{"label":"CAA GAP booklet: Survival (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf"}],"published_date":"2024-07-26","sent_at":"2024-07-26T05:34:00+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 27th July 2024","original_title":null,"original_body":"Vector Online - After a forced landing in the bush, this pilot did three things that made the difference between survival and possible death.\n\nIt was the end of a successful winter hunting weekend in the Kaimanawa Forest Park. The pilot – who we’re calling John – his dog, his sister, and their hunting buddy, boarded John’s Cessna 172, bound for home.\n\nJohn (PPL, with around 600 hours at the time) had already flown some of their gear out. As they prepared for their final departure mid-afternoon, he noticed the weather conditions deteriorating more quickly than expected. He decided they would head for Tūrangi rather than Taupō or Taihape.\n\n“It was a routine flight, operating in an area I know well,” John says.\n\n“Coming out with the second load and my passengers, visibility seemed not too bad. I came through the trickiest part to navigate, but then there are two valleys with similar headings – and I flew into the wrong one.”","editor_notes":"UNSURE/TRUNCATED: source is only the opening excerpt of a Vector article and ends before the 'three things' are described. Kept as a teaser with a link to the Vector archive (the story appears to be from Vector, Winter 2024 – please verify). Consider replacing with a summary of the full article."},{"id":9,"slug":"respect-the-starter-motor-duty-cycle","title":"Respect the Starter Motor Duty Cycle","summary":"Follow the starter duty cycle to avoid overheating and damage – e.g. in ELA: crank no more than 10 s, cool 20 s between attempts, and rest 30 min after six tries.","body_markdown":"Most starter problems happen because pilots don't fully understand the aircraft's starting system and the stress the starter is under when you turn the key.\n\nStick to the starter's **duty cycle** to maximise its life. The duty cycle determines how well the starter tolerates repeated starting attempts: each unsuccessful attempt should be followed by a specified cool-down interval. Ignoring this will overheat the starter and severely damage its internal components, leading to premature failure.\n\nViolating the duty cycle just a couple of times can do irreparable damage. In extreme cases the starter can become inoperable – and then you're stuck. Excessive cranking can also overheat the electrical supply system, accelerate wear on the contactor and increase corrosion of connections in the circuit.\n\nOur maintenance team has seen damage to starter motors from excessive cranking, so always follow the guidelines for your aircraft. For example, in **ELA (one of our C152s)**:\n\n- Don't crank the starter for **more than 10 seconds**.\n- Allow **20 seconds to cool** between attempts.\n- Repeat up to **6 times**, then allow the starter to **cool for 30 minutes**.","category":"Aircraft & Engine","tags":["starter","duty-cycle","engine-start","c152","maintenance"],"links":[],"published_date":"2024-08-03","sent_at":"2024-08-03T23:21:20+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 4th August 2024","original_title":null,"original_body":"Save your Starter\n\nThe main cause of most starter problems is that pilots don’t really understand the aircraft’s starting system and the stresses the starter experiences when you turn the key.\n\nIt is important to adhere to the 'Duty Cycle' of an aircraft starter and follow the cycle's guidelines. Doing this will maximise the starter's life,\n\nThe starter’s duty cycle determines how well the starter can tolerate repeated starting attempts. Each unsuccessful attempt is meant to be followed by a specified starter cool down interval. Failure to follow these guidelines will cause the starter to overheat and severely damage the starter’s internal components, leading to premature starter failure.\n\nViolating the duty cycle just a couple of times will do irreparable damage to the starter. In extreme cases, it can render the starter inoperable—then you’re stuck. Excessive cranking can also overheat the electrical supply system and cause accelerated wear to the contactor and elevated corrosion rates for connections in the circuit.\n\nRecently it has been noted in maintenance that there has been an increase in damage to the starter motors. Always follow the guidelines for your starter motor. Here is an example from ELA, one of our C152s: do not crank the starter for more than 10 seconds. Allow 20s to cool down between attempts . Repeat up to 6 times and then allow the starter to cool for 30 mins.","editor_notes":"Reworded 'Recently it has been noted in maintenance' as timeless; list formatting; copy edit."},{"id":10,"slug":"report-laser-strikes","title":"Report Laser Strikes","summary":"If hit by a laser, look away, don't rub your eyes and tell ATC; then report it to the CAA (rules 12.55 and 12.57) via 0508 4 SAFETY and the CAA800 form.","body_markdown":"Laser strikes on aircraft – usually green, sometimes blue – are an ongoing problem. There's not a lot you can do to prevent them, but there's a bit you can do to mitigate their effects – and **the most important thing is to report them**.\n\nDirect eye exposure to a laser beam can cause momentary flash 'blindness', where visual interference persists after the beam has gone. There can also be 'after-images' left in your visual field after the light moves away.\n\n### If you're hit by a laser\n\n- **Try not to look at the light.** It's natural to want to find where it's coming from, but to limit the effects, train yourself to glance away.\n- **Don't rub your eyes.** It's another natural response, but it can cause further irritation or injury.\n- **Report the strike immediately to ATC.** Other aircraft need to know what they may be up against, and the police get a chance to follow it up.\n- **Turn up the cockpit lighting** – it may help you get over the laser's effects.\n\n### Report it formally after landing\n\nIt's tempting not to bother after a long day, but reporting helps CAA analysts identify peaks in laser strikes at certain places, times of day or times of year – which helps other pilots be prepared. **Civil Aviation Rules 12.55 and 12.57 require you to report a laser strike** to the CAA, because it's \"an immediate hazard to the safety of an aircraft operation\".\n\nReporting is straightforward:\n\n1. Call **0508 4 SAFETY (0508 472 338)**.\n2. Follow up by completing the **CAA800 Laser Beam Exposure Questionnaire** – mainly a checklist, and quick to fill out.\n3. Email the completed form to **isi@caa.govt.nz**.\n\n**Further reading:**\n\n- [CAA: Aviation related concerns (incl. laser strikes)](https://www.aviation.govt.nz/safety/notify-us/aviation-concerns/)\n- [CAA800 Laser Beam Exposure Questionnaire (PDF)](https://www.aviation.govt.nz/assets/forms/CAA800.pdf)\n- [Civil Aviation Rules Part 12: Accidents, Incidents, and Statistics](https://www.aviation.govt.nz/rules/rule-part/part-12/)","category":"Emergencies","tags":["laser","reporting","caa","night","rule-12"],"links":[{"label":"CAA: Aviation related concerns (incl. laser strikes)","url":"https://www.aviation.govt.nz/safety/notify-us/aviation-concerns/"},{"label":"CAA800 Laser Beam Exposure Questionnaire (PDF)","url":"https://www.aviation.govt.nz/assets/forms/CAA800.pdf"},{"label":"Civil Aviation Rules Part 12: Accidents, Incidents, and Statistics","url":"https://www.aviation.govt.nz/rules/rule-part/part-12/"}],"published_date":"2024-08-09","sent_at":"2024-08-09T05:42:15+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 9th August 2024","original_title":null,"original_body":"REPORTING LASER STRIKES\n\nThe incidence of aircraft being targeted by the menacing green (or blue) light is on the increase. There’s not a lot you can do to prevent them, but there’s a bit you can do to mitigate their effects, but the most important thing is to report them.\n\nDirect eye exposure to a laser beam can result in momentary flash ‘blindness’, where visual interference persists after the laser beam is removed. There can be ‘after-images’ left in the visual field after the light is moved away.\n\nAdvice to pilots mostly surrounds what to do in the aftermath of a laser strike:\n\nTry not to look at the light. It’s a natural reaction to want to do so, and you want to be able to identify where the laser beam is coming from. But to limit the effects, try to make your automatic reaction to glance away.\n\nDon’t rub your eyes, although that’s another natural response. It can cause further irritation or injury.\n\nReport the strike immediately to air traffic control. Other aircraft need to know what they may be up against, and the police will get an opportunity to chase it up.\n\nTurning up the cockpit lighting may help get over the laser’s effects.\n\nTake the time to formally report it after you land. There’s a temptation not to bother because you’ve had a long day, and now you have to do the paperwork.\n\nReporting will help the CAA analysts identify if there are peaks of laser strikes in certain places, or times of the day or year. That at least will help other pilots to be prepared. Civil Aviation Rules 12.55 and 12.57 actually mandate the reporting of a laser strike to the CAA, because it’s “an immediate hazard to the safety of an aircraft operation”.\n\nIt’s relatively straightforward to report:\n\nJust call 0508 4 SAFETY (0508 472 338) which is staffed 24 hours. That can be followed up by completing the CAA800 form Laser Beam Exposure Questionnaire, which again, is fairly simple and quick to fill out, being mainly a checklist. Email the completed form to isi@caa.govt.nz","editor_notes":"Reworded 'on the increase' as timeless; removed the claim that 0508 4 SAFETY is 'staffed 24 hours' (CAA pages currently describe the line inconsistently – verify); list formatting. Note: CAA advisory material says CAA800 is being phased out in favour of online/CA005 reporting – consider updating."},{"id":11,"slug":"secure-or-remove-loose-items-in-the-cockpit","title":"Secure or Remove Loose Items in the Cockpit","summary":"Loose items can jam controls or injure occupants – check for and remove loose or unnecessary items in every pre-flight, and strip the cockpit for aerobatics.","body_markdown":"The cockpit of a general aviation aircraft is a small space, and it can quickly become cluttered with charts, headsets, flight plans, kneeboards, pens and more. **Loose items can and do cause serious accidents.**\n\nA couple of close calls:\n\n- **Aerobatic 'lockup' in an Airtourer.** Lockup happens when the aircraft is set up incorrectly for a manoeuvre and ends up vertical with no airflow acting on any of its surfaces. The pilot must neutralise the controls and wait to see whether the aircraft falls backwards or forwards. In this case, the aircraft slapped forward so violently that the axe was pulled from its secured mounting and struck the pilot in the back of the head.\n- **Airbus A330 pitch-down.** In February 2014, an A330 flying from RAF Brize Norton to Camp Bastion in Afghanistan suddenly pitched nose-down while cruising at 33,000 ft. It continued for 33 seconds, losing 4,400 ft, before the aircraft's self-protection measures initiated a recovery. Several passengers and crew were injured. A British Military Aviation Authority inquiry found that a digital SLR camera had been placed between the sidestick and the captain's left armrest. When the captain's seat was moved forward, the camera jammed against the base of the sidestick, commanding the dive.\n\nDuring your pre-flight, **check the aircraft for loose and unnecessary items and remove them** before flight.\n\nFor aerobatic flights, remove everything from the aircraft except the flight manual and a couple of sick bags.\n\n**Further reading:**\n\n- [CAA Vector: Clutter in the cockpit (PDF)](https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-3-clutter-in-the-cockpit.pdf)\n- [CAA Vector: FOD in the cockpit](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/)","category":"Airmanship","tags":["loose-items","fod","preflight","cockpit","aerobatics"],"links":[{"label":"CAA Vector: Clutter in the cockpit (PDF)","url":"https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-3-clutter-in-the-cockpit.pdf"},{"label":"CAA Vector: FOD in the cockpit","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/"}],"published_date":"2024-08-16","sent_at":"2024-08-16T01:46:44+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 16th August 2024","original_title":null,"original_body":"The cockpit in our general aviation aircraft is a small space. It can quickly become cluttered with charts, headsets, flight plans, kneeboards, pens, and more. Loose items can and do cause serious accidents.\n\nTo name a few close calls:\n\nA pilot was conducting aerobatics in an Air Tourer when 'lockup’ occurred. That’s where the aircraft has been set up wrongly for the particular manoeuvre, and the aeroplane ends up in a vertical position where no air movement is reacting on any surfaces of the aircraft. The pilot must neutralise the controls and wait to see if the aircraft will fall backwards or forwards. This particular aircraft did such a violent slap forward that it pulled the axe out of its secured moorings and struck the pilot in the back of the head.\n\nIn February 2014 when an Airbus A330 was flying from RAF Brize Norton to Camp Bastion in Afghanistan. The aircraft was cruising at 33,000 ft when it suddenly pitched its nose down. The aircraft continued like this for 33 seconds, losing 4400 ft in height, before the aircraft’s self-protection measures initiated a recovery. Several passengers and crew were injured during the dive. A British Military Aviation Authority inquiry established that the pitch-down command resulted from a digital SLR camera being placed directly behind the sidestick in the space between the sidestick and the captain’s left armrest. When the captain’s seat was moved forward, the camera became jammed between the front of the armrest and the rear base of the sidestick causing the aircraft to dive.\n\nDuring your pre-flight, it is important to check the aircraft for loose and unnecessary items. These need to be removed before flight.\n\nFor aerobatic flights, everything should be removed from the aircraft bar the flight manual and a couple of sick bags.","editor_notes":"Copy edit; restructured the two case studies as a list."},{"id":12,"slug":"picket-your-aircraft-against-wind-damage","title":"Picket Your Aircraft Against Wind Damage","summary":"Protect parked aircraft from wind: use a hangar or fixed tie-downs where possible, otherwise carry a crossover picket kit and picket in front of the wing.","body_markdown":"Every year aircraft are needlessly damaged by wind gusts because of inattention to forecasts, negligence or inadequate tie-downs. Before the windier months – and whenever strong winds are forecast – it pays to brush up on picketing techniques and other precautions against wind damage to parked aircraft.\n\nIdeally, secure the aircraft in a storm-proof hangar or other suitable shelter. If hangarage isn't available, the remaining option is to tie the aircraft down securely in a suitable location. Many New Zealand aerodromes have only a limited number of fixed tie-down points, and these may be reserved for local aircraft. If a fixed tie-down isn't available, find a sheltered spot to park.\n\n### Carry a picket kit\n\nThis may mean using your own pickets. It's a good idea to carry a set in case you're stuck at a remote aerodrome with no other way to secure the aircraft. A picket set should include:\n\n- six steel stakes\n- three crossover tubes\n- three ropes of appropriate length\n- a mallet or hammer\n\nall stowed in a bag. **Include the pickets in your weight and balance calculations**, and stow them securely so they don't become a problem in turbulence.\n\n### Choosing where and how to picket\n\n- Pickets can pull out under strain if the ground is soft or becomes wet.\n- Coiled pickets are difficult to get into stony ground and more likely to pull out of soft ground.\n- **Crossover pickets are the most suitable**, as they're more likely to stay put even if the ground gets wet.\n- Lead the underwing ropes to points **outboard and forward** of the underwing attachment points.\n- Hammer pickets all the way into the ground, **always in front of the wing**.\n\nFor more detail, see the CAA's Secure your aircraft GAP booklet.\n\n**Further reading:**\n\n- [CAA GAP booklet: Secure your aircraft (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/secure-your-aircraft.pdf)","category":"Ground Ops","tags":["picketing","tie-downs","wind","parking","away-landings"],"links":[{"label":"CAA GAP booklet: Secure your aircraft (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/secure-your-aircraft.pdf"}],"published_date":"2024-08-30","sent_at":"2024-08-30T07:00:11+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 30th August 2024","original_title":null,"original_body":"Each year aircraft are needlessly damaged by wind gusts because of inattention to weather forecasts, negligence or inadequate tiedown measures. With the ‘windy season’ approaching, it is a good time to brush up on recommended picketing techniques and other precautions against wind damage to parked aircraft.\n\nIdeally, we want to secure our aircraft in a storm-proof hangar or other suitable shelter. If appropriate hangarage isn’t available, the remaining option is to tie down your aircraft securely in a suitable location. Many aerodromes around New Zealand, however, only have a limited number of places available for securing aircraft to fixed tie-down points and these may be reserved for local aircraft. If a fixed tiedown point isn’t available, find a sheltered place to park your aircraft.\n\nThis may mean you’ll need to use your own set of pickets. It’s a good idea to carry a set of pickets with you, in case you are stuck at a remote aerodrome with no other way to secure your aircraft. Your picket set should include six steel stakes, three crossover tubes, and three ropes of appropriate length –all stowed in a bag. You’ll also need a mallet or hammer. Remember to include the pickets in your weight and balance calculations, and ensure they’re well-secured in the aircraft before flight. Stow them carefully so they don’t become a problem during turbulence.\n\nTake care when choosing where you’ll picket your aircraft. Pickets can pull out under strain if the ground is soft, or becomes wet. The coiled type is difficult to get into stony ground and may be more likely to pull out in soft ground. The cross-over type of pickets are the most suitable, as they’re more likely to stay in the ground, even if it becomes wet. The underwing ropes should be led to points outboard and forward of the underwing attachment point. Hammer pickets all the way into the ground, always in front of the wing.For further reading refer to the CAA Secure Your Aircraft GAP Booklet .\n\n(I have a spare set of coiled type pickets, if anyone wants them - Rudi)","editor_notes":"Replaced 'With the windy season approaching' with timeless phrasing; removed personal offer of spare pickets (Rudi); list formatting."},{"id":13,"slug":"always-check-notams-before-flight","title":"Always Check NOTAMs Before Flight","summary":"Never assume everything is open – check NOTAMs and AIP Supplements before every flight and assess their impact, as runway closures have caught pilots out.","body_markdown":"NOTAMs are notices about the establishment, condition or change of any aeronautical facility, service, procedure or hazard – information that's essential to know in good time for anyone involved in flight operations. Generally, NOTAMs are urgent or temporary in nature.\n\nFailing to check NOTAMs and AIP Supplements keeps CAA safety investigators busy examining potentially deadly occurrences. At Omaka, an aircraft flipped after attempting to land on a runway closed for regrassing. The NOTAM issued at the time read:\n\n> A0470/08 FROM: 09 MAR 2008 19:08 TO: 09 JUN 2008 19:00 GRASS RWY 01/19 AND GRASS RWY 07/25 CLSD DUE REGRASSING\n\n**Never assume everything is open and operational.** NZPP itself has had NOTAMs such as:\n\n> RWY 16/34 CLSD DUE SFC FLOODING\n\nImagine the possible outcome for a pilot coming in to land unaware of that NOTAM.\n\n**Check the NOTAMs before every flight**, and take the time to assess what impact each one will have on the safety of your flight and on the flight itself.\n\n**Further reading:**\n\n- [CAA Vector: So you don't think you need a NOTAM?](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/so-you-dont-think-you-need-a-notam/)\n- [CAA Vector: Don't be that pilot](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dont-be-that-pilot/)\n- [Airways IFIS – NOTAMs and flight plans](https://www.ifis.airways.co.nz/)\n- [PreFlight – aviation weather and briefing](https://gopreflight.co.nz/)","category":"Procedures & SOPs","tags":["notams","aip-supplements","flight-planning","runway-closure"],"links":[{"label":"CAA Vector: So you don't think you need a NOTAM?","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/so-you-dont-think-you-need-a-notam/"},{"label":"CAA Vector: Don't be that pilot","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dont-be-that-pilot/"},{"label":"Airways IFIS – NOTAMs and flight plans","url":"https://www.ifis.airways.co.nz/"},{"label":"PreFlight – aviation weather and briefing","url":"https://gopreflight.co.nz/"}],"published_date":"2024-09-06","sent_at":"2024-09-06T20:31:31+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 7th September 2024","original_title":null,"original_body":"NOTAMs are notices containing information concerning the establishment, condition or change in any aeronautical facility, service, procedure or hazard, the timely knowledge of which is essential to personnel concerned with flight operations. Generally speaking, NOTAMs are urgent or temporary in nature. The failure to consult NOTAMs and AIP Supplements is keeping CAA safety investigators busy examining potentially deadly occurrences. At Omaka, an aircraft flipped after attempting to land on a RWY closed for regrassing. The NOTAM issued at the time read: A0470/08 FROM: 09 MAR 2008 19:08 TO: 09 JUN 2008 19:00 GRASS RWY 01/19 AND GRASS RWY 07/25 CLSD DUE REGRASSING. We can never assume everything is open and operational at any given time. On Tuesday this week, there was a NOTAM for NZPP that read: RWY 16/34 CLSD DUE SFC FLOODING Imagine what the outcome could have been for a pilot coming into land not aware of the NOTAM. It is vital that we check the NOTAMs prior to flight and take the time to accurately assess what impact this NOTAM will have on the safety of the flight and the flight itself. Further reading can be found in this vector article.","editor_notes":"Replaced 'On Tuesday this week, there was a NOTAM for NZPP' with timeless phrasing; split run-on paragraph; formatted NOTAM text as quotes; replaced 'this vector article' with verified links."},{"id":14,"slug":"know-the-civil-aviation-act-2023","title":"Know the Civil Aviation Act 2023","summary":"The Civil Aviation Act 2023 came into effect on 5 April 2025, replacing the 1990 Act; check the CAA's implementation pages to see how it affects your flying.","body_markdown":"The **Civil Aviation Act 2023** came into effect on **5 April 2025**, replacing the Civil Aviation Act 1990.\n\nTake some time to look through the changes and understand how they affect your flying. The CAA's implementation pages summarise what has changed and list the rules made under the 2023 Act.\n\n**Further reading:**\n\n- [CAA: Civil Aviation Act 2023 implementation](https://www.aviation.govt.nz/about-us/what-we-do/civil-aviation-act-2023-implementation/)\n- [CAA: Rules under the 2023 Act](https://www.aviation.govt.nz/about-us/what-we-do/civil-aviation-act-2023-implementation/rules/)","category":"Procedures & SOPs","tags":["civil-aviation-act","rules","caa","legislation"],"links":[{"label":"CAA: Civil Aviation Act 2023 implementation","url":"https://www.aviation.govt.nz/about-us/what-we-do/civil-aviation-act-2023-implementation/"},{"label":"CAA: Rules under the 2023 Act","url":"https://www.aviation.govt.nz/about-us/what-we-do/civil-aviation-act-2023-implementation/rules/"}],"published_date":"2024-09-14","sent_at":"2024-09-14T01:26:45+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 14th September 2024","original_title":null,"original_body":"The New Zealand Civil Aviation Act 2023 comes into effect on 5 April 2025. Now is a good time to have a look through the proposed changes to see how it will affect your flying.\n\nHave a look here for what the changes are: https://aviation.govt.nz/about-us/what-we-do/civil-aviation-act-2023-implementation/draft-rules/","editor_notes":"Original was forward-looking ('comes into effect on 5 April 2025... proposed changes'); rewritten in past tense. Original 'draft-rules' URL now redirects to the CAA 'Rules under the 2023 Act' page. Added that it replaced the 1990 Act (stated on the CAA website)."},{"id":15,"slug":"build-crosswind-proficiency-and-personal-limits","title":"Build Crosswind Proficiency and Personal Limits","summary":"Crosswind skills fade without practice: set personal limits, watch for changing winds, use rudder and aileron correctly, and go around or use RWY 30 if needed.","body_markdown":"At NZPP, spring often brings 'crosswind season' – the time of year everyone with a BFR due looks forward to!\n\nEveryone needs to be comfortable and proficient in crosswinds. Just because you were good at them a few months ago doesn't mean you're still proficient now. All skills deteriorate without practice, so recognise your limitations well before you're up in the air.\n\nWatch for significant weather changes during your flight. You may take off from NZPP in calm winds and return to find the crosswind has increased beyond your personal limits. One of our instructors once took off in a 4 kt easterly and, returning just 20 minutes later, found a 25 kt south-westerly on the ground!\n\n**Set personal limits**, and don't hesitate to book a dual flight with an instructor to practise crosswind circuits and build your confidence.\n\n### Crosswind technique\n\n1. **Rudder** to keep the nose straight in relation to the runway.\n2. **Aileron** to maintain the centreline (land on the into-wind main wheel first).\n3. Once all three wheels are on the ground, **ailerons into wind**.\n\n**You can always go around and try again.** At NZPP we also have crosswind **RWY 30**, which can be used for imperative landings. If you genuinely can't land on RWY 34, try RWY 30 to reduce the crosswind component.","category":"Airmanship","tags":["crosswind","landing","personal-limits","runway-30","nzpp"],"links":[],"published_date":"2024-09-20","sent_at":"2024-09-20T03:16:59+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 20th September 2024","original_title":null,"original_body":"Spring has sprung and it's officially the time of year everyone with a due BFR is looking forward to - crosswind season!\n\nEveryone needs to be comfortable and proficient in crosswinds. Remember just because you were good a few months ago does not mean you still are proficient now. All skills deteriorate with a lack of practice, so it is important to recognise our limitations well before we are stuck up in the air.\n\nIt is very important to look out for any significant weather changes during your flight. You may take off from NZPP with calm winds and by the time you get back the crosswind may have increased outside your personal limits. Just Tuesday I took off the and wind was a four-knot easterly. By the time I returned 20 minutes later, the wind was a 25kt south westerly on the ground!\n\nRemember to set personal limits for yourself and don't hesitate to book a dual flight with an instructor to practice crosswind circuits and build your confidence. The crosswind technique is as follows:\n\nRudder to keep the nose straight in relation to the runway\n\nAileron to maintain centreline (land on into wind mainwheel first)\n\nOnce touched down on all three wheels, ailerons into wind\n\nRemember you can always go around and try again. At NZPP we have also have crosswind RWY 30 which can be used for imperative landings. If you genuinely can't land on RWY 34, try RWY 30 to reduce the crosswind component.","editor_notes":"Replaced 'Spring has sprung...' and 'Just Tuesday I took off...' with timeless phrasing (anecdote kept); numbered technique list; copy edit."},{"id":16,"slug":"push-and-pull-aircraft-the-right-way","title":"Push and Pull Aircraft the Right Way","summary":"Push on the inner propeller near the hub (never the spinner), use both hands on the towbar, and always disconnect the towbar when it isn't in your hand.","body_markdown":"There are procedures to follow when moving aircraft around the apron.\n\n- **Pushing:** push on the **inner section of the propeller**, near the hub, where it is strongest. **Don't push on the nose cone (spinner)** – this can damage it, and you could hurt yourself if you slip.\n- **Pulling with the towbar:** use **both hands** to minimise the risk of injury and damage if you drop the towbar.\n- **Always disconnect the towbar** from the aircraft whenever it isn't in your hand. Leaving it attached can cause some very expensive damage!\n\nIf you're unsure of the correct technique, ask an instructor to show you.","category":"Ground Ops","tags":["towing","towbar","apron","propeller","ground-handling"],"links":[],"published_date":"2024-09-27","sent_at":"2024-09-27T04:07:03+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 27th September 2024","original_title":null,"original_body":"When towing aircraft around the apron, there are procedures that must be followed. When you are pushing aircraft you must push on the inner section of the propeller, where the propeller is strongest. Do not push on the nose cone, this can cause damage to the nose itself and potentially yourself if you slip.\n\nWhen pulling the aircraft, you should use both hands to minimise the risk of injury and damage if you were to drop the tow bar. Remember to always disconnect the towbar from the aeroplane when you're not holding it in your hand. Failure to do so can cause some very expensive damage!\n\nPictured below is our instructor Will demonstrating the correct method of pushing and pulling an aircraft. Be like Will!\n\nAbove: Will demonstrating how to push an aircraft\n\nAbove: Will demonstrating how to pull an aircraft","editor_notes":"Removed photo captions and references to an instructor demonstrating in pictures ('Pictured below... Be like Will!'); added suggestion to ask an instructor for a demonstration."},{"id":17,"slug":"keep-up-with-vector-magazine","title":"Keep Up With Vector Magazine","summary":"The CAA's Vector magazine is published each season and is a great safety read; past issues and Vector Online articles are free on the CAA website.","body_markdown":"The CAA's **Vector** magazine is published each season and is always a good read – a reminder of the many things that affect aviation safety.\n\nYou can read the latest issue online, browse past issues in the Vector archive, and find more articles from the Vector team on Vector Online.\n\n**Further reading:**\n\n- [CAA Vector: latest issue](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/latest-issue-of-vector/)\n- [CAA Vector Online](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/)\n- [CAA Vector magazine archive](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-magazine-archive/)","category":"Airmanship","tags":["vector","caa","safety-education","reading"],"links":[{"label":"CAA Vector: latest issue","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/latest-issue-of-vector/"},{"label":"CAA Vector Online","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/"},{"label":"CAA Vector magazine archive","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-magazine-archive/"}],"published_date":"2024-10-04","sent_at":"2024-10-04T06:17:56+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 4th October 2024","original_title":null,"original_body":"The Spring 2024 issue of Vector Magazine is out. Vector is always a good read and reminder of various things that have an impact on aviation safety.\n\nRead the latest issue here.","editor_notes":"Original announced the Spring 2024 issue; rewritten as a general recommendation; replaced 'Read the latest issue here' with verified links."},{"id":18,"slug":"stay-clear-of-an-occupied-runway-strip","title":"Stay Clear of an Occupied Runway Strip","summary":"Don't enter the runway strip while the runway is in use – hold abeam the holding point signs – and don't land until the strip is clear; go around if it isn't.","body_markdown":"The **runway strip** is defined as:\n\n> a defined area including the runway, and stopway (if a stopway is provided), that is intended— (1) to reduce the risk of damage to an aircraft running off the runway; and (2) to provide obstacle protection for aircraft flying over the runway strip during take-off or landing operations.\n\n**Do not enter the runway strip while the runway is occupied** by an aircraft taking off or landing. Hold outside the strip at the designated holding points (e.g. C, E, A1) until the runway is clear – that means **holding abeam the signs, not past them**.\n\nThe same applies when landing: **the runway strip must be unoccupied when you land**. Wait for the preceding aircraft to clear onto Alpha, and go around if it doesn't.\n\nThe runway strip boundary is shown by the **dashed line** on the Paraparaumu aerodrome ground chart in AIP New Zealand.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)","category":"Aerodrome & Circuit","tags":["runway-strip","holding-point","nzpp","runway-incursion","landing"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"}],"published_date":"2024-10-11","sent_at":"2024-10-11T03:29:34+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 11th October 2024","original_title":null,"original_body":"The runway strip is defined as:\n\na defined area including the runway, and stop way (if a stop way is provided), that is intended— (1) to reduce the risk of damage to an aircraft running off the runway; and (2) to provide obstacle protection for aircraft flying over the runway strip during take-off or landing operations.\n\nIt is very important we do not enter the runway strip while the runway is occupied (either by aircraft taking off or landing). We should hold outside the runway strip at the designated holding pts e.g. C,E,A1 until the runway is clear. This means holding abeam the signs and not past them.\n\nThe same applies when we are coming in to land. The runway strip must be unoccupied when we land. This means waiting for aircraft to clear onto alpha and going around if this doesn't occur. Below is a picture of the Paraparaumu ground plate where you can see the strip indicated by the dashed line.","editor_notes":"Removed picture reference ('Below is a picture of the Paraparaumu ground plate'); pointed to the ground chart in AIP NZ."},{"id":19,"slug":"close-the-oil-cap-finger-tight-only","title":"Close the Oil Cap Finger-Tight Only","summary":"After checking the oil, close the oil cap finger-tight only – over-tightening damages the cap and makes it hard to open; ask an instructor if it's stuck.","body_markdown":"Checking the oil quality and quantity is an essential part of every pre-flight. Afterwards, **close the oil cap finger-tight – no tighter**. Over-tightening can damage the cap and make it hard for the next pilot to open once the engine has heated up and cooled down.\n\nIf you can't get the cap undone during your pre-flight, grab an instructor to help.","category":"Aircraft & Engine","tags":["oil","oil-cap","preflight","engine"],"links":[],"published_date":"2024-10-17","sent_at":"2024-10-17T23:38:06+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 18th October 2024","original_title":null,"original_body":"An essential part of every pre-flight includes checking the oil quality and quantity of an aircraft. It is important that after we do this, we close the oil cap to just finger tight and no tighter. Over-tightening the cap can cause damage and make it difficult for the next pilot to open it after the engine has heated and cooled down.\n\nIf you are pre-flighting and are unable to get it unscrewed please grab an instructor who will assist you","editor_notes":"Light copy edit."},{"id":20,"slug":"fly-the-standard-overhead-join-correctly","title":"Fly the Standard Overhead Join Correctly","summary":"Call 5–10 NM out, keep the aerodrome on your left overhead, descend on the non-traffic side and cross the upwind threshold to join left- or right-hand circuits.","body_markdown":"One of the best ways to enhance aviation safety is by sticking to standard procedures – and the standard overhead join (SOHJ) is a well-used example. Make sure you're comfortable with it.\n\nThe left-hand and right-hand patterns start the same way:\n\n1. Make a radio call **5–10 NM** from the aerodrome, advising that you're joining overhead.\n2. Position the aerodrome so it is **out to your left**. This gives you, in the left-hand seat, a clear view of the aerodrome.\n\nOnce overhead, your options are **orbiting (left-hand), joining, or vacating** (if required).\n\n**Left-hand circuit:** on the non-traffic side, descend to circuit height and, using left-hand turns, join the circuit by crossing the upwind threshold.\n\n**Right-hand circuit:** on the non-traffic side, make a 45° turn to the left and begin descending to circuit height. Once spacing is sufficient, turn right to cross the upwind threshold and join the right-hand circuit.\n\nThis procedure is an aviator's bread and butter, and it's crucial to fly it correctly. If you have any doubts, ask an instructor to go over it with you.\n\n**Further reading:**\n\n- [CAA: Standard overhead join](https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/fixed-wing-flight-training-safety-strategy/standard-overhead-join/)\n- [CAA poster: Standard overhead join (PDF)](https://www.aviation.govt.nz/assets/publications/posters/standard-overhead-join.pdf)","category":"Aerodrome & Circuit","tags":["overhead-join","sohj","circuit","unattended-aerodrome","radio"],"links":[{"label":"CAA: Standard overhead join","url":"https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/fixed-wing-flight-training-safety-strategy/standard-overhead-join/"},{"label":"CAA poster: Standard overhead join (PDF)","url":"https://www.aviation.govt.nz/assets/publications/posters/standard-overhead-join.pdf"}],"published_date":"2024-10-25","sent_at":"2024-10-25T03:49:06+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 25th October 2024","original_title":null,"original_body":"One of the greatest ways to enhance aviation safety is by conforming to standard procedures. An example of this is the standard overhead join. It's important to be comfortable with this well-used manoeuver.\n\nThe left hand and right hand pattern for a SOHJ start in the same way.\n\n1. Make a radio call 5-10nm away from the airfield, advising that you are joining overhead 2. Position the airfield so it's out to your left. This allows you, sitting in the left-hand seat, a clear view of the airfield\n\nOnce in the overhead, you have a couple of options:\n\nOrbiting (left hand), Joining or Vacating (if required)\n\nIn a left-hand procedure:\n\nOn the non-traffic side, descend to circuit height and using LH turns, join into the circuit by crossing the upwind threshold.\n\nIn a right-hand procedure:\n\nOn the non-traffic side, initiate a 45 degree turn to the left. Begin descent to circuit height. Once spacing is sufficient, turn right to cross the upwind threshold and join into the right hand circuit.\n\nThis procedure is an aviator's bread and butter, and it is crucial that you perform it correctly. If you have any doubts, feel free to ask an instructor to go over it.\n\nLeft Hand Pattern Right Hand Pattern","editor_notes":"Removed diagram captions ('Left Hand Pattern Right Hand Pattern'); linked CAA SOHJ guidance instead; numbered steps."},{"id":21,"slug":"drain-and-check-fuel-before-every-flight","title":"Drain and Check Fuel Before Every Flight","summary":"Drain fuel from all points before every flight, let fuel settle after refuelling (15 min per 30 cm for avgas), and get an engineer's check if contamination persists after three drains.","body_markdown":"40% of engine failures are caused by fuel exhaustion, starvation or contamination. This message focuses on **contamination**.\n\nFuel contamination is a foreign substance such as water, dirt or fungi in the fuel. It can stop the engine by inhibiting combustion, blocking fuel lines or damaging fuel system components.\n\nTo mitigate it:\n\n- **Drain fuel from all available points during the pre-flight** – before every flight, not just the first flight of the day.\n- This is especially important **after refuelling** or if the aircraft has been **left outside overnight**.\n- After refuelling, let the fuel settle for as long as possible. A minimum of **15 minutes per 30 cm depth of fuel** is recommended for avgas. On a cross-country, it may pay to refuel first, before doing other tasks.\n- Discard drained fuel into one of our **jerry cans**.\n\nIf contaminants are present, consult an instructor. **If contaminants are still present after three drains**, the aircraft may need to be examined by the engineers.\n\n**Further reading:**\n\n- [CAA GAP booklet: Fuel management (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf)","category":"Aircraft & Engine","tags":["fuel","contamination","fuel-drain","preflight","refuelling"],"links":[{"label":"CAA GAP booklet: Fuel management (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf"}],"published_date":"2024-11-01","sent_at":"2024-11-01T03:34:05+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 1st November 2024","original_title":null,"original_body":"Fuel Contamination\n\n40% of engine failures are caused by fuel exhaustion, starvation or contamination. Today we will be focusing on contamination.\n\nFuel contamination is where there’s a foreign substance such as water, dirt or fungi in the fuel. The contaminant may cause the engine to stop because it has inhibited combustion or blocked the fuel lines or damaged the fuel system components.\n\nTo mitigate this, fuel should be strained from all available points during the pre-flight. This should occur before every flight, not just the first flight of the day. This is especially important after refuelling or if the aircraft has been left outside overnight.\n\nAfter fuelling, allow the fuel to settle for as long as possible. A minimum of 15 minutes per 30 cm depth of fuel for avgas is recommended. If on a cross country, it may pay to refuel first before carrying out other tasks. Once drained, fuel should be discarded into one of our jerry cans.\n\nBelow is a picture of TDL's tanks after one strain...If contaminants are present, consult with an instructor. If contaminants are still present after 3x drains, the aircraft may need to be examined by the engineers.","editor_notes":"Replaced 'Today we will be focusing on contamination' with timeless phrasing; removed photo reference (TDL's tanks after one drain); 'strained' changed to 'drained'."},{"id":22,"slug":"check-your-radio-and-know-nordo-procedures","title":"Check Your Radio and Know NORDO Procedures","summary":"NZPP is an MBZ with 10-minute reports and a listening watch; if the radio seems quiet, run a radio check, and if it has failed, squawk 7600 and follow NORDO procedures.","body_markdown":"NZPP is within a **mandatory broadcast zone (MBZ)**. This means we're legally required to make radio calls/position reports at the programmed interval – **every 10 minutes** in our case – and to **maintain a listening watch** on frequency.\n\nIf you know there's other traffic around but you haven't heard any radio calls for a while, double-check your radio:\n\n- Test the volume by pushing/pulling the volume knob.\n- Ask Flight Service for a radio check: *\"Flight Service, JEN, radio check.\"* They'll respond with a number from 1 to 5 (1 is the worst, 5 the best).\n- If there's no response, try turning the radio off and on, and make sure both headset plugs are fully in and secure.\n\n### NORDO procedures\n\nIf you're not receiving radio calls, or you're unsure whether you're transmitting, commence NORDO procedures:\n\n- **Squawk 7600.**\n- **In the circuit:** complete a full-stop landing.\n- **In the training area:**\n  - Be predictable – follow standard arrival procedures.\n  - Try contacting Flight Service (04 297 1170) or the aero club by phone to advise your intentions.\n  - Make sure your lookout is thorough.\n\n**Further reading:**\n\n- [CAA GAP booklet: Plane talking (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-plane-talking.pdf)","category":"Airspace & Radio","tags":["radio","mbz","nordo","radio-failure","flight-service"],"links":[{"label":"CAA GAP booklet: Plane talking (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-plane-talking.pdf"}],"published_date":"2024-11-08","sent_at":"2024-11-08T04:26:00+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 8th November 2024","original_title":null,"original_body":"Radio Use\n\nHere at NZPP we operate in a mandatory broadcast zone. This means we legally have to make radio calls/position reports at the programmed interval - in our case 10 minutes. We must also maintain a listening watch on frequency.\n\nIf you know there is other traffic around and you haven't heard any radio calls recently, it may pay to double check the radio:\n\n- Test the volume by pushing/pulling the volume knob\n\n- Initiate a radio check with flight service: \"Flight Service, JEN radio check\" They will respond with a number 1-5, 1 being the worst, 5 being the best\n\n- If no response, try turning the radio on and off, and ensuring both headphone plugs are in and secure.\n\nIf you are not receiving radio calls / are unsure if you are transmitting, commence NORDO procedures:\n\n- Squawk 7600\n\nIn the circuit:\n\n- Complete a full stop\n\nIn the training area:\n\n- Be predictable - follow standard arrival procedures\n\n- Try contacting flight service (04 297 1170) or the aeroclub to advise intentions\n\n- Ensure lookouts are sufficient","editor_notes":"Restructured into lists; clarified that contacting Flight Service/the aero club is by phone."},{"id":23,"slug":"manage-bird-hazards-at-a-coastal-aerodrome","title":"Manage Bird Hazards at a Coastal Aerodrome","summary":"NZPP's coastal location means more birds: assess the risk before every flight, tell Flight Service about birds on the runway, report strikes on MIFIS and know local breeding seasons.","body_markdown":"**One strike and you're out!** Don't ignore the threat of birds.\n\nKāpiti Aero Club is on the sunny Kāpiti Coast. As a coastal aerodrome, we're predisposed to a larger bird population than inland aerodromes – reported bird strikes here have been known to double in a single year.\n\nBefore every flight, assess the risk birds pose and take steps to mitigate it. Don't get yourself out needlessly – **if there are birds before the wicket, tell the umpire (Flight Service)**. They can fire the bird-scaring cannons located at each runway threshold. We can also make sure the runway is clear and, on take-off, follow a straight, predictable path.\n\nIt's easy to get caught up in the excitement of a flight you've been looking forward to all week. Don't let that eagerness get in the way of good threat and error management.\n\nSometimes we take all these steps and still have a strike or a near miss. **These must be reported on MIFIS**, including:\n\n- species\n- number of birds\n- where it occurred (e.g. abeam A3)\n- whether evasive action was required\n\n### Know the local birds\n\nIn spring and the warmer months, new growth of grass and greenery brings increased wildlife activity, so be aware of the habits and behaviours of the local birds:\n\n- **Plovers / masked lapwings** – lay eggs June–November and are incredibly protective of their chicks. If a plover is sizing you up in the middle of the runway, its chick probably isn't far away.\n- **Pūkeko** – much prefer running to flying when disturbed. Their breeding system varies, with a peak in the North Island from August to November. They're territorial.\n- **Shelducks** – pair up to breed, often for long periods. Both parents guard the chicks; breeding runs August–February.\n- **Canada geese** – the biggest birds we regularly see at NZPP. They also pair up, with the female sitting on the eggs and the gander defending the nest. Breeding season is September–January.\n\n**Further reading:**\n\n- [CAA GAP booklet: Bird hazards (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/Bird_Hazards.pdf)\n- [CAA: Reporting bird incidents](https://www.aviation.govt.nz/safety/notify-us/reporting-bird-incidents/)","category":"Aerodrome & Circuit","tags":["birds","birdstrike","nzpp","reporting","mifis","tem"],"links":[{"label":"CAA GAP booklet: Bird hazards (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/Bird_Hazards.pdf"},{"label":"CAA: Reporting bird incidents","url":"https://www.aviation.govt.nz/safety/notify-us/reporting-bird-incidents/"}],"published_date":"2024-11-15","sent_at":"2024-11-15T00:44:38+00:00","is_published":true,"source_email_subject":"Weekly Flyer 15th November 2024","original_title":null,"original_body":"One strike - you're out! Don't ignore the threat of birds this spring.\n\nKapiti Aero Club is located on the sunny Kapiti Coast. Being a coastal aerodrome, we are predisposed to having a larger bird population than those located inland. In fact, over the past year, we have seen reported bird strikes double.\n\nIt is important prior to every flight, you assess the risk birds pose and take steps to mitigate them. Don’t get yourself out needlessly – if birds before wicket tell the umpire (Flight Service). They have the option to fire the cannons located at each runway threshold. Alongside this, we can ensure the runway is clear and when we do take-off, we follow a straight predictable path. It is easy to get caught up in the excitement of the flight you've been looking forward to all week. Don't let this eagerness get in the way of proper threat and error management.\n\nSometimes we can take all these steps and still have a strike or a near miss - these need to be reported on MIFIS. The reports should include: species type, number of birds, where it occurred (e.g. abeam A3) and whether or not evasive action was required.\n\nAs we head into the warmer months, it is important for us to remember that with the new growth of grass and greenery, comes the additional risk of increased wildlife activity. We need to be aware of the habits and behaviours of the local birds.\n\nPlovers / Masked Lapwings - Lay eggs June-November and are incredibly protective of their chicks. If you see a Plover sizing you up in the middle of the runway their chick probably isn't far away.\n\nPukeko - much prefers to run than fly when disturbed. Their breeding system is variable, with a peak in the North Island from Aug-Nov. They are territorial.\n\nShell Duck - Bond for breeding in pairs, often for long periods of time. Both parents guard the chicks, with a breeding period from Aug-Feb.\n\nCanadian Goose - the biggest bird we see regularly at NZPP. They also mate in pairs, with the mother sitting on the eggs and the gander defending the nest. Breeding season Sep-Jan.","editor_notes":"Removed 'this spring', 'over the past year' and 'As we head into the warmer months' wording; corrected bird names (pūkeko, shelducks, Canada geese); list formatting."},{"id":24,"slug":"point-your-prop-wash-away-during-run-ups","title":"Point Your Prop Wash Away During Run-Ups","summary":"During run-ups on Taxiway Charlie, point the prop wash at the grass, use only half the taxiway, and move to the Western apron if there isn't room.","body_markdown":"When the engine is running, the propeller generates **prop wash** – air pushed behind the aircraft at high speed, especially at high power.\n\nWhen doing run-ups on **Taxiway Charlie**:\n\n- Point the prop wash **towards the grass**, away from taxiways and other aircraft.\n- Position the aircraft so you only occupy **one half of the taxiway**, leaving room for another aircraft to use the other side.\n\nAnything behind you can be affected by your prop wash, which can be extremely hazardous. If there isn't enough room to set up safely on Charlie, **use the Western apron**.\n\nRemember: as a pilot, you're legally responsible for your aircraft, your passengers and any hazard your aircraft poses to anyone else.","category":"Ground Ops","tags":["run-up","prop-wash","taxiway-charlie","nzpp","apron"],"links":[],"published_date":"2024-11-21","sent_at":"2024-11-21T23:23:48+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 22nd November 2024","original_title":null,"original_body":"When our engine is running, our propellers are spinning and generating prop wash which is air being pushed behind the aircraft at a great rate, especially during high power operations.\n\nMake sure when doing run-up checks on taxiway charlie that you are pointing the prop wash towards the grass, away from taxiways and aircraft. Position your aircraft so you are only occupying one-half of the taxiway to allow enough room for another aircraft to use the other side.\n\nAnything behind you can be affected by your prop wash, which can be extremely hazardous. If there is not enough room for you to set up safely on Charlie, please use the Western apron. Remember as a pilot you are legally responsible for your aircraft, your passengers and any hazard your aircraft poses to anyone else.","editor_notes":"Light copy edit; list formatting."},{"id":25,"slug":"plan-for-busy-summer-skies-on-cross-countries","title":"Plan for Busy Summer Skies on Cross-Countries","summary":"Summer brings more traffic and air events: check AIP Supplements, NOTAMs on the day and the CAA's Summer traffic busy spots page before a cross-country.","body_markdown":"Planning a cross-country in summer? Expect more aircraft in the sky, thanks to better weather and increased traffic over the holiday period.\n\nDon't inadvertently fly into an aviation event:\n\n- Check **AIP Supplements** for planned events.\n- Check **NOTAMs** on the day.\n\nEach summer the CAA also publishes a *Summer traffic busy spots* page on Vector Online, showing traffic hot spots and major flying events for the season – well worth a look before you head away.\n\n**Further reading:**\n\n- [CAA Vector: Summer traffic busy spots](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/summer-traffic-busy-spots/)\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [Airways IFIS – NOTAMs and flight plans](https://www.ifis.airways.co.nz/)","category":"Airspace & Radio","tags":["cross-country","summer","aip-supplements","notams","air-events"],"links":[{"label":"CAA Vector: Summer traffic busy spots","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/summer-traffic-busy-spots/"},{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"Airways IFIS – NOTAMs and flight plans","url":"https://www.ifis.airways.co.nz/"}],"published_date":"2024-11-28","sent_at":"2024-11-28T22:40:39+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 29th November 2024","original_title":null,"original_body":"Planning on going on a Cross-Country this summer? Be prepared for there to be more aircraft in the skies due to nice weather and increased traffic during the holiday period.\n\nDon’t inadvertently fly into an aviation event – check AIP Supplements for planned events, and check NOTAMs on the day.\n\nAlso be sure to check out this page produced by the CAA which shows Summer traffic busy hot spots and major flying events, between mid-December 2024 and March 2025.\n\nSummer traffic busy spots 2024-25","editor_notes":"Removed the specific season dates (mid-December 2024 to March 2025) and dated link text ('Summer traffic busy spots 2024-25'); replaced with verified link."},{"id":26,"slug":"manage-distractions-and-interruptions","title":"Manage Distractions and Interruptions","summary":"Distraction and interruption are classic accident factors: finish tasks before responding, mark your place, or go back at least three checklist steps.","body_markdown":"Distraction greatly affects our ability to make good decisions. It has always been one of the **'Dirty Dozen'** – the most common conditions contributing to accidents and incidents. We need to take proactive steps to reduce the risk of distraction, including from things like mobile phones.\n\nClosely related to distraction is **interruption**. While a distraction is usually unplanned, like a loud noise, an interruption is intentional. How often have you lost your train of thought when a friend interrupted you? Or think about flying: what happens to your pre-flight flow when someone interrupts to ask a question?\n\nIn 1987–88, the US National Transportation Safety Board (NTSB) investigated the crash of a Northwest Airlines McDonnell Douglas DC-9-82 shortly after take-off from a Detroit airport. The NTSB found that constant interruptions – and a change in runway assignment while preparing for take-off – ultimately led to the crash. The crew failed to recognise that the flaps had not been set to the take-off position, and didn't complete the checklist that would have alerted them. Only 12 months later, an almost identical accident occurred when the crew of a Boeing 727 crashed after an interrupted checklist.\n\n### Handling interruptions\n\n- **Finish the task** before responding to an interruption, where possible.\n- If that's not possible, **clearly mark where you were** so you know where to pick up again.\n- Or **go back at least three steps** on your checklist and retrace your work.\n\n**Further reading:**\n\n- [CAA Vector: Go back three steps](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/go-back-three-steps/)\n- [CAA human factors: Decision-making](https://www.aviation.govt.nz/safety/safety-education-and-advice/human-factors/non-technical-skills/decision-making/)","category":"Human Factors","tags":["distraction","interruption","dirty-dozen","checklist","human-factors"],"links":[{"label":"CAA Vector: Go back three steps","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/go-back-three-steps/"},{"label":"CAA human factors: Decision-making","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/human-factors/non-technical-skills/decision-making/"}],"published_date":"2024-12-06","sent_at":"2024-12-06T00:18:20+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 6th December 2024","original_title":null,"original_body":"Distraction greatly affects our ability to make good decisions. It has always been one of the ‘Dirty Dozen’, the most common conditions contributing to accidents or incidents. We must take proactive steps to mitigate the risk of distraction through things like our mobile phones. Closely related to distraction is interruption. While distraction is usually something unplanned, like a loud noise, interruption is intentional. How often have you forgotten your train of thought when your friend interrupted you? Or consider a flying an example - what happens to your pre-flight flow when someone interrupts you to ask a question? In 1987–88, the National Transportation Safety Board (NTSB) investigated the crash of a Northwest Airlines McDonnell Douglas DC‑9‑82 shortly after take‑off from a Detroit airport. The NTSB found that constant interruptions – and a change in runway assignment during preparation for take‑off – ultimately led to the crash. It found the crew failed to recognise the flaps had not been set to take‑off position, and didn’t complete the checklist alerting them to the flap position. Only 12 months later, an almost identical accident occurred when the crew of a Boeing 727 crashed due to an interrupted checklist process It’s best to finish a task before responding to an interruption. If that’s not possible, clearly mark the project to remind you where to take it up again. Or go back at least three steps on your checklist, so the work can be retraced.","editor_notes":"Split a single long paragraph into sections; added a short list of techniques; copy edit."},{"id":27,"slug":"lookout-and-radio-calls-in-uncontrolled-airspace","title":"Lookout and Radio Calls in Uncontrolled Airspace","summary":"In uncontrolled airspace separation is up to you: scan slowly (about 20° every 2 s), make accurate position reports, and actively arrange separation with nearby traffic.","body_markdown":"In uncontrolled airspace, **responsibility for separation from other aircraft rests entirely with the pilot**. To maintain situational awareness we use several tools – mainly lookout and radio calls.\n\n**Lookout** – make it slow and thorough. The ideal scan rate is roughly **20 degrees every 2 seconds**. Make an effort to check around the aircraft's blind spots.\n\n**Radio calls** – position reports must be accurate and on the correct frequency. Include:\n\n- who you're talking to\n- your callsign\n- your current position\n- altitude\n- intentions\n\nFor example: *\"Otaki Traffic, EKM, overhead Peka Peka Ponds, 1500 ft, tracking north along the coast.\"*\n\nBe mindful of where frequencies change – for example, from Tararua Traffic 118.3 to Manawatu Traffic 122.6 (always confirm current frequencies on your chart). There may be transiting aircraft in the area that haven't made a radio call yet.\n\nWhen you hear radio calls, think about how that traffic affects you now and in the future. **Making a position report doesn't absolve you from maintaining separation.** If you're heading to the training area and know there's traffic nearby, talk to them to arrange separation – for example, one stays landside and one stays seaward, or use vertical separation.\n\n**Further reading:**\n\n- [CAA GAP booklet: Plane talking (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-plane-talking.pdf)\n- [CAA: Work Together, Stay Apart](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-initiatives/work-together-stay-apart/)","category":"Airspace & Radio","tags":["lookout","radio","position-report","uncontrolled-airspace","separation"],"links":[{"label":"CAA GAP booklet: Plane talking (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-plane-talking.pdf"},{"label":"CAA: Work Together, Stay Apart","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-initiatives/work-together-stay-apart/"}],"published_date":"2024-12-13","sent_at":"2024-12-13T01:13:39+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 13th December 2024","original_title":null,"original_body":"In uncontrolled airspace, the responsibility of separation from other aircraft falls entirely on the pilot . To maintain situational awareness, we utilise several tools, predominantly the look-out and radio calls.\n\nLookouts - these need to be sufficiently slow and thorough. The ideal scan rate is approximately 20 degrees every 2 seconds. An effort needs to be made to check around the aircraft's blind spots.\n\nRadio calls - when giving a position report, these need to be accurate and on the correct frequency. The contents should include who you are talking to, your callsign, your current position, altitude, and intentions. E.g.\"Otaki Traffic EKM overhead Peka Peka Ponds 1500ft tracking North along the coast\"\n\nBe mindful of where frequencies change, e.g. from Tararua Traffic 118.3 to Manawatu Traffic 122.6. Be aware there may be transiting aircraft in the area that haven't made a radio call yet.\n\nWhen we hear radio calls we need to think about how the traffic affects us now, and in future. Just making a position report doesn't absolve you from maintaining separation. If you are heading to the training area and know there is traffic nearby, communicate with them to ensure separation e.g. one stays landside and one stays seaward, or vertical separation.","editor_notes":"List formatting; added reminder to confirm frequencies on the current chart; copy edit."},{"id":28,"slug":"carb-ice-forms-even-on-warm-days","title":"Carb Ice Forms Even on Warm Days","summary":"Carb icing is a year-round threat because the carburettor is much colder than outside air; use carb heat below the green arc and check for icing in SCADIE checks.","body_markdown":"It's easy to be lulled into a false sense of security in the warmer months, but the threat of carburettor icing is constant. Carb icing is a build-up of ice in the carburettor that causes a restriction. This results in an overly rich mixture going into the cylinders, causing rough running and loss of power.\n\nCarb icing can form in conditions from **-10°C up to +25°C**. It's much colder inside the carburettor than outside because of the **venturi effect** (accelerating air drops in temperature) and **fuel evaporation** (which absorbs latent heat). So even if it's warm outside, it may not be so warm in the carburettor!\n\n**Symptoms:** rough running and loss of RPM. **Treatment:** apply carb heat, which takes warm air from around the exhaust instead of cool outside air. This melts the ice, which will temporarily make the symptoms worse as water runs through the engine.\n\nTake steps to avoid carb icing where possible, and be aware of the conditions that favour it:\n\n- Use **carb heat outside the green range** (below 1900 RPM in the C152).\n- **Check carb heat on the ground** before departure.\n- **Check for carb icing frequently** during SCADIE checks.\n\nIt is most likely to form **between 10°C and 15°C with relative humidity above 40%**.\n\n**Further reading:**\n\n- [CAA Vector: Icing](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/)\n- [CAA safety message: Check the carb icing graph](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/)","category":"Aircraft & Engine","tags":["carb-icing","carburettor","carb-heat","scadie","c152"],"links":[{"label":"CAA Vector: Icing","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/"},{"label":"CAA safety message: Check the carb icing graph","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/"}],"published_date":"2024-12-20","sent_at":"2024-12-20T01:59:01+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 20th December 2024","original_title":null,"original_body":"Icing - not just a winter problem...\n\nIt is easy to be lulled into a false sense of security during the warmer months but the threat of carburettor icing remains constant. Carb icing occurs when there is a build-up of ice in the carburettor which causes a restriction. This results in an overly rich fuel mixture going into the cylinders which causes rough running and loss of power.\n\nCarb icing can form in conditions ranging from -10C up to +25C. It should be noted that is a lot colder in the carburettor than ambient, due to the venturi effect (air accelerating resulting in a drop in temperature) and evaporation taking place (requiring latent heat). This means, that even though it may be warm outside, it may not be so warm in the carburettor!\n\nThe symptoms, as mentioned before, are rough running and loss of RPM. The treatment is to apply carb heat, which takes warm air from exhaust instead of the cool outside air. This melts the ice, which will temporarily cause the symptoms to worsen as water runs through the engine.\n\nWe should take steps to avoid carb icing where possible and be aware of the conditions conducive to icing. We do this by using carb heat outside the green range (below 1900 RPM in C152), checking carb heat on the ground before departure, and checking for carb icing frequently during SCADIE checks. It is most likely to form between 10-15C with a relative humidity above 40%.","editor_notes":"Title derived from the source heading 'Icing - not just a winter problem...'; 'during the warmer months' kept as a general (timeless) statement; list formatting."},{"id":29,"slug":"prepare-for-engine-failure-and-ditching-test-copy","title":"Prepare for Engine Failure and Ditching (Test Copy)","summary":"Practise forced landings regularly and know your aircraft's ditching procedure – the C152 flight manual procedure is listed step by step.","body_markdown":"Your engine doesn't know when you're at 3,000 ft and into wind – **an engine failure can happen at any time**. Be proficient in the forced landing without power (FLWOP) procedure and practise it outside of your BFR – at different altitudes, in different locations and in different weather conditions.\n\nEngine failures can also happen over water, so be familiar with your aircraft's **ditching procedure**. Here is the C152 ditching procedure from the flight manual:\n\n**DITCHING (C152)**\n\n1. **Radio** – TRANSMIT MAYDAY on 121.5 MHz, giving location and intentions.\n2. **Heavy objects** (in baggage area) – SECURE OR JETTISON.\n3. **Approach** – High winds, heavy seas: INTO THE WIND. Light winds, heavy swells: PARALLEL TO SWELLS.\n4. **Wing flaps** – 30°.\n5. **Power** – ESTABLISH 300 FT/MIN DESCENT AT 55 KIAS.\n6. **Cabin doors** – UNLATCH.\n7. **Touchdown** – LEVEL ATTITUDE AT 300 FT/MIN DESCENT.\n8. **Face** – CUSHION at touchdown with folded coat.\n9. **Airplane** – EVACUATE through cabin doors. If necessary, open windows and flood cabin to equalise pressure so doors can be opened.\n\nAlways refer to the flight manual for the aircraft you're flying.\n\n**Further reading:**\n\n- [CAA GAP booklet: Survival (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf)\n- [CAA Vector: It's called a 'life' jacket for a reason](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/)","category":"Emergencies","tags":["engine-failure","flwop","ditching","c152","over-water","mayday"],"links":[{"label":"CAA GAP booklet: Survival (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf"},{"label":"CAA Vector: It's called a 'life' jacket for a reason","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/"}],"published_date":"2024-12-26","sent_at":"2024-12-26T21:39:48+00:00","is_published":false,"source_email_subject":"[Test] Weekly Flyer - 27th December 2024","original_title":null,"original_body":"Your engine doesn't know when you're 3000ft and into wind - an engine failure can occur at any time. It's important that you are proficient in the FLWOP procedure and practice it outside of your BFR. This includes practising it at different altitudes, locations, and weather conditions. Engine failures also occur over water. You should be familiar with your aircraft's ditching procedure. Below are the C152s ditching procedure, which can be located in the flight manual. DITCHING 1. Radio – TRANSMIT MAYDAY on 121.5 MHz, giving location and intentions. 2. Heavy Objects (in baggage area) – SECURE OR JETTISON. 3. Approach – High Winds, Heavy Seas – INTO THE WIND. Light Winds, Heavy Swells – PARALLEL TO SWELLS. 4. Wing Flaps – 30°. 5. Power – ESTABLISH 300 FT/MIN DESCENT AT 55 KIAS. 6. Cabin Doors – UNLATCH. 7. Touchdown – LEVEL ATTITUDE AT 300 FT/MIN DESCENT. 8. Face – CUSHION at touchdown with folded coat. 9. Airplane – EVACUATE through cabin doors. If necessary, open windows and flood cabin to equalise pressure so doors can be opened.","editor_notes":"DUPLICATE – unpublished: test send ('[Test] Weekly Flyer - 27th December 2024') with identical text to #30, sent about a minute earlier. Body mirrors the edited #30. Also: removed 'Below are...' reference; formatted checklist as a numbered list."},{"id":30,"slug":"prepare-for-engine-failure-and-ditching","title":"Prepare for Engine Failure and Ditching","summary":"Practise forced landings regularly and know your aircraft's ditching procedure – the C152 flight manual procedure is listed step by step.","body_markdown":"Your engine doesn't know when you're at 3,000 ft and into wind – **an engine failure can happen at any time**. Be proficient in the forced landing without power (FLWOP) procedure and practise it outside of your BFR – at different altitudes, in different locations and in different weather conditions.\n\nEngine failures can also happen over water, so be familiar with your aircraft's **ditching procedure**. Here is the C152 ditching procedure from the flight manual:\n\n**DITCHING (C152)**\n\n1. **Radio** – TRANSMIT MAYDAY on 121.5 MHz, giving location and intentions.\n2. **Heavy objects** (in baggage area) – SECURE OR JETTISON.\n3. **Approach** – High winds, heavy seas: INTO THE WIND. Light winds, heavy swells: PARALLEL TO SWELLS.\n4. **Wing flaps** – 30°.\n5. **Power** – ESTABLISH 300 FT/MIN DESCENT AT 55 KIAS.\n6. **Cabin doors** – UNLATCH.\n7. **Touchdown** – LEVEL ATTITUDE AT 300 FT/MIN DESCENT.\n8. **Face** – CUSHION at touchdown with folded coat.\n9. **Airplane** – EVACUATE through cabin doors. If necessary, open windows and flood cabin to equalise pressure so doors can be opened.\n\nAlways refer to the flight manual for the aircraft you're flying.\n\n**Further reading:**\n\n- [CAA GAP booklet: Survival (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf)\n- [CAA Vector: It's called a 'life' jacket for a reason](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/)","category":"Emergencies","tags":["engine-failure","flwop","ditching","c152","over-water","mayday"],"links":[{"label":"CAA GAP booklet: Survival (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf"},{"label":"CAA Vector: It's called a 'life' jacket for a reason","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/"}],"published_date":"2024-12-26","sent_at":"2024-12-26T21:40:52+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 27th December 2024","original_title":null,"original_body":"Your engine doesn't know when you're 3000ft and into wind - an engine failure can occur at any time. It's important that you are proficient in the FLWOP procedure and practice it outside of your BFR. This includes practising it at different altitudes, locations, and weather conditions. Engine failures also occur over water. You should be familiar with your aircraft's ditching procedure. Below are the C152s ditching procedure, which can be located in the flight manual. DITCHING 1. Radio – TRANSMIT MAYDAY on 121.5 MHz, giving location and intentions. 2. Heavy Objects (in baggage area) – SECURE OR JETTISON. 3. Approach – High Winds, Heavy Seas – INTO THE WIND. Light Winds, Heavy Swells – PARALLEL TO SWELLS. 4. Wing Flaps – 30°. 5. Power – ESTABLISH 300 FT/MIN DESCENT AT 55 KIAS. 6. Cabin Doors – UNLATCH. 7. Touchdown – LEVEL ATTITUDE AT 300 FT/MIN DESCENT. 8. Face – CUSHION at touchdown with folded coat. 9. Airplane – EVACUATE through cabin doors. If necessary, open windows and flood cabin to equalise pressure so doors can be opened.","editor_notes":"Removed 'Below are...' reference; formatted the ditching checklist as a numbered list; added 'refer to the flight manual' line. #29 is a test-copy duplicate of this message."},{"id":31,"slug":"keep-aircraft-clean-and-free-of-fod","title":"Keep Aircraft Clean and Free of FOD","summary":"Inspect the aircraft after every flight, remove rubbish and loose items, and leave it clean and secure for the next pilot.","body_markdown":"**Don't let FOD bring you down!** Looking after our aircraft includes keeping them clean and tidy – even a quick clean-up of the fleet can turn up a surprising collection of loose items.\n\n**Always inspect your aircraft after your flight** and make sure it's clean and secure. Leave the aircraft the way you'd like to find it!\n\nTake the time to read the CAA Vector article on clutter in the cockpit.\n\n**Further reading:**\n\n- [CAA Vector: Clutter in the cockpit (PDF)](https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-3-clutter-in-the-cockpit.pdf)","category":"Ground Ops","tags":["fod","post-flight","cockpit","cleanliness","loose-items"],"links":[{"label":"CAA Vector: Clutter in the cockpit (PDF)","url":"https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-3-clutter-in-the-cockpit.pdf"}],"published_date":"2025-01-03","sent_at":"2025-01-03T04:26:52+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 3rd January 2025","original_title":null,"original_body":"Don't let FOD bring you down! It is important that we take good care of our aircraft, this includes keeping them clean and tidy. This week from a quick clean up through our fleet, look what was found! Always inspect your aircraft after your flight and make sure the aircraft is clean and secure. Leave the aircraft how you would like find it! Please take the time to read the linked vector article about clutter in the cockpit.","editor_notes":"Removed 'This week' and image reference ('look what was found!'); replaced 'linked vector article' with verified link."},{"id":32,"slug":"dont-hesitate-to-go-around","title":"Don't Hesitate to Go Around","summary":"If you're not happy at any point on the approach, go around: power up, pitch up, clean up, then make the radio call once climbing away.","body_markdown":"Bumpy, gusty conditions are a good prompt to refresh both the importance and the procedure of a go-around.\n\nA go-around may be necessary for many reasons. You may have misjudged something – simple pilot error – or it could be the result of someone or something else. Whatever the reason, **if you're not happy at any time during the approach, don't hesitate to go around**. If you're ever unsure, it's always safer to power up and try again.\n\n**Keep it simple** during a go-around – don't try to do multiple things at once. Remember the order:\n\n1. **Power up**\n2. **Pitch up**\n3. **Clean up**\n4. **Radio call** – once the aircraft is climbing away and everything is in order.\n\nAlways: **Aviate, Navigate, Communicate.**","category":"Aerodrome & Circuit","tags":["go-around","landing","gusty-conditions","aviate-navigate-communicate"],"links":[],"published_date":"2025-01-11","sent_at":"2025-01-11T02:52:59+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 11th January 2025","original_title":null,"original_body":"This summer has certainly come with bumpy southerlies and gusty conditions!\n\nThis weeks safety message is a reminder of both the importance and procedure of conducting a go around. There are many times a go around may be necessary. You may have misjudged something with simple pilot error, or it could be a result of someone or something else. Whatever the reason may be, if you are not happy at any time during the approach, do not hesitate to go around. If you are ever unsure, it is always the safer move to power up and try again next time\n\nKeep it simple when you are conducting a go around, do not try to do multiple things at once. Remember the order: power up, pitch up, clean up, then make the radio call once the plane is climbing away and everything is in order. Always Aviate, Navigate, Communicate.","editor_notes":"Removed 'This summer has certainly come with bumpy southerlies' and 'This week's safety message'; numbered the go-around sequence. #109 is a forwarded duplicate of this message."},{"id":33,"slug":"protect-yourself-from-sun-and-heat","title":"Protect Yourself From Sun and Heat","summary":"On sunny days wear sunscreen, carry water on cross-countries, follow IMSAFE on hot days, and put the sunshade up when packing the aircraft away.","body_markdown":"On sunny days, be aware of the harmful UV rays that shine through the windows into the cockpit.\n\n- On longer cross-countries, **make sunscreen a checklist item** before you take off.\n- **Take water with you** on warm, sunny cross-countries – it's a must.\n- Follow the **IMSAFE** checklist, including drinking plenty of water on hot days.\n\nWhen packing the aircraft away after your flight, **put the sunshade up on the dash** so the aircraft doesn't turn into a sauna for the next pilot.","category":"Human Factors","tags":["sun","hydration","imsafe","sunshade","cross-country"],"links":[],"published_date":"2025-01-17","sent_at":"2025-01-17T20:45:18+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 17th January 2025","original_title":null,"original_body":"As we start to see more sunny days for flying we need to be aware of the harmful sun rays that shine through the windows into our cockpits. On longer cross countries please make sure that sunscreen becomes a checklist item before you take off. Taking water along with you on the sunny warm cross countries is a must as well.\n\nWhen packing the aircraft away after your flight please ensure that the sunshade is put up on the dash to avoid the aircraft turning into a sauna for the next pilots.\n\nPlease ensure that you are adhering to the IMSAFE checklist including plenty of water intake on hot days.","editor_notes":"Replaced 'As we start to see more sunny days' with timeless phrasing; list formatting."},{"id":34,"slug":"comply-with-published-circuit-procedures","title":"Comply With Published Circuit Procedures","summary":"At uncontrolled or unattended aerodromes you must fly the circuit direction and procedures published in the AIP – announcing a 'non-standard' join is not acceptable.","body_markdown":"Pilots operating at an uncontrolled or unattended aerodrome **must comply with the published circuit directions and procedures** in AIP New Zealand Volume 4 for that aerodrome. These procedures are designed to give pilots the greatest possible safety when joining or vacating.\n\n**Announcing on the radio that you're joining or vacating 'non-standard' is not acceptable** and does not absolve you from complying with the published circuit direction. This applies to all types of operation, although some agricultural and helicopter operations may be exempt under certain conditions.\n\nFollowing the rules, combined with standard radiotelephony procedures and a good lookout scan, is essential for flight safety. **Never assume you're the only aircraft in the vicinity of the aerodrome**, even if you haven't heard any other radio calls.\n\nNon-conformance with circuit procedures at uncontrolled or unattended aerodromes can be fatal.\n\n**Further reading:**\n\n- [CAA safety message: Non-conformance with aerodrome circuit procedures](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/non-conformance-with-aerodrome-circuit-procedures/)\n- [CAA: Right hand circuits](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/right-hand-circuits/)\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Aerodrome & Circuit","tags":["circuit","uncontrolled-aerodrome","aip","non-standard-join","radio"],"links":[{"label":"CAA safety message: Non-conformance with aerodrome circuit procedures","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/non-conformance-with-aerodrome-circuit-procedures/"},{"label":"CAA: Right hand circuits","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/right-hand-circuits/"},{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2025-01-25","sent_at":"2025-01-25T02:55:57+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 25th January 2025","original_title":null,"original_body":"Non-conformance with uncontrolled or unattended aerodrome circuit procedures can be fatal\n\nPilots operating at an uncontrolled or unattended aerodrome must comply with the published circuit directions and procedures in the NZAIP Volume 4 for that aerodrome. These procedures are established to ensure the greatest possible safety for pilots when they are joining or vacating an uncontrolled or unattended aerodrome. Advising local traffic via a radio call that you are joining or vacating ‘non-standard’ is not acceptable and does not absolve the pilot from complying with the published circuit direction. This applies to operations of all types, however, some agricultural and helicopter operations may be exempt under certain conditions. Adherence to the rules, coupled with the use of standard radiotelephony procedures and a good lookout scan, is essential to ensure flight safety. Never assume that you are the only aircraft in the vicinity of the aerodrome, even if no other radio communications from aircraft have been heard.\n\nRead more here.","editor_notes":"Text is drawn from a CAA safety message; replaced 'Read more here' with a verified link to that message; paragraph breaks."},{"id":35,"slug":"know-the-rules-for-marine-mammals-near-kaikoura","title":"Know the Rules for Marine Mammals Near Kaikōura","summary":"Before flying to view marine mammals near Kaikōura, read the NZKI MBZ pages in AIP New Zealand and the Marine Mammals Protection Regulations.","body_markdown":"It's easy to be delighted by a sighting of marine mammals and want to get a closer look! But do you know the procedures that apply?\n\nOperators at Kaikōura have asked us to remind our staff and members about the **unique rules of Kaikōura airspace** and the rules that protect marine life.\n\nBefore flying in the area, read the **Kaikōura (NZKI) MBZ pages in AIP New Zealand** and follow the published procedures. Aircraft operating near marine mammals must also comply with the Marine Mammals Protection Regulations 1992.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [Marine Mammals Protection Regulations 1992](https://www.legislation.govt.nz/secondary-legislation/pco-drafted/1992/322/en/latest/)","category":"Airspace & Radio","tags":["kaikoura","marine-mammals","mbz","nzki","aip"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"Marine Mammals Protection Regulations 1992","url":"https://www.legislation.govt.nz/secondary-legislation/pco-drafted/1992/322/en/latest/"}],"published_date":"2025-01-30","sent_at":"2025-01-30T23:38:49+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 31st January 2025","original_title":null,"original_body":"MARINE LIFE SPOTTING\n\nIt is easy to be delighted at the sighting of marine mammals and flock to get a closer look! But do you know the procedures that apply?\n\nOperators in Kaikoura have contacted us to remind our staff and membership about the unique rules of Kaikoura airspace and the rules that apply for our lovely marine life.\n\nPlease see below NZKI MBZ AIP Page","editor_notes":"UNSURE/INCOMPLETE SOURCE: the original relied on an embedded AIP page image ('Please see below NZKI MBZ AIP Page'), so the actual rules were not in the text. Replaced with a pointer to the AIP NZKI MBZ pages and the Marine Mammals Protection Regulations 1992. Consider adding the key heights/distances after checking the AIP."},{"id":36,"slug":"report-aircraft-damage-straight-away","title":"Report Aircraft Damage Straight Away","summary":"Report any damage or defect to an instructor immediately and complete the MIFIS form – unreported issues, like a cracked window, can get worse.","body_markdown":"**Report any aircraft damage or defect to an instructor immediately**, whether you notice it during or after your flight. For example, a cracked window was once found on one of our aircraft (MWM) that hadn't been reported.\n\nPrompt reporting means problems can be dealt with quickly, preventing further damage or complications. If you notice anything unusual, tell an instructor and **complete the necessary form on MIFIS**.","category":"Aircraft & Engine","tags":["defects","damage","reporting","mifis"],"links":[],"published_date":"2025-02-06","sent_at":"2025-02-06T22:09:21+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 7th February 2025","original_title":null,"original_body":"Aircraft Damage\n\nIt was recently observed that MWM had a cracked window, which had not been previously reported. As a reminder, it is crucial to report any issues, whether during or after your flights, to an instructor immediately. Prompt reporting allows for quick action to resolve any problems, preventing further damage or complications. If you notice anything unusual, please ensure you report it to an instructor and complete the necessary form on MIFIS.","editor_notes":"Reworded 'It was recently observed that MWM had a cracked window' as a timeless example."},{"id":37,"slug":"stick-to-the-clubs-vfr-weather-minimums","title":"Stick to the Club's VFR Weather Minimums","summary":"The club's VFR met minimums sit above the legal minimums – on cross-countries and Cook Strait crossings, check you can see the other side and have an exit plan.","body_markdown":"When flying VFR in New Zealand, sticking to meteorological minimums is crucial for safe flight. The minimums are outlined in your flight manuals, which are a reliable reference if you're ever unsure.\n\n**Our aero club has its own meteorological minimums, set above the legal requirements**, to give all pilots an extra margin of safety. Always stick to these minimums.\n\nOn any cross-country, or when crossing Cook Strait, pay close attention to the conditions and ask yourself:\n\n- Can you see the other side?\n- How low is the cloud?\n- What's your exit plan if conditions change?\n\nIf you can't meet the minimums, reassess your plans and consider alternatives. Always fly within **both the legal and the club's meteorological minimums**, and never hesitate to check your flight manual for specific guidance.\n\nStay vigilant, plan carefully and fly safely.\n\n**Further reading:**\n\n- [CAA GAP booklet: VFR MET (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/vfr-met-web.pdf)\n- [Civil Aviation Rules Part 91: General Operating and Flight Rules](https://www.aviation.govt.nz/rules/rule-part/part-91/)","category":"Weather","tags":["vfr","met-minima","weather","cook-strait","club-minimums"],"links":[{"label":"CAA GAP booklet: VFR MET (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/vfr-met-web.pdf"},{"label":"Civil Aviation Rules Part 91: General Operating and Flight Rules","url":"https://www.aviation.govt.nz/rules/rule-part/part-91/"}],"published_date":"2025-02-14","sent_at":"2025-02-14T02:24:30+00:00","is_published":true,"source_email_subject":"Weekly Flyer","original_title":null,"original_body":"Safety Reminder: Meteorological Minimums for VFR Flight\n\nWhen flying VFR (Visual Flight Rules) in New Zealand, adhering to meteorological minimums is crucial for safe flight. These minimums are outlined in your flight manuals, and should you ever be unsure, they are a reliable reference.\n\nIt’s important to note that our aeroclub has established its own meteorological minimums, which are set above the legal requirements. These club-specific minimums are in place to ensure an extra margin of safety for all pilots. Please make sure to always adhere to these minimums during your flights.\n\nWhen on any cross country or when crossing the Cook Strait, pay close attention to conditions and ask yourself:\n\nCan you see the other side?\n\nHow low is the cloud cover?\n\nWhat is your exit plan if conditions change?\n\nIf you are unable to meet these minimums, it's essential to reassess your flight plans and consider alternate options. Always ensure that you’re flying within both the legal and our aeroclub’s meteorological minimums to maintain safety. Never hesitate to refer to your flight manual for specific guidelines. Stay vigilant, plan carefully, and fly safely.","editor_notes":"Removed 'Safety Reminder:' heading prefix; list formatting; light copy edit."},{"id":38,"slug":"joining-the-circuit-and-give-way-rules","title":"Joining the Circuit and Give-Way Rules","summary":"Broadcast your intentions, use the published NZPP joining procedures (not the SOHJ), and give way to aircraft already established in the circuit.","body_markdown":"When joining the circuit, safety and communication are critical. The circuit is flown in a standard pattern to avoid conflicts between aircraft, and following the give-way rules keeps traffic flowing safely and predictably.\n\n### Joining the circuit\n\n- Always make your intentions clear by **broadcasting your position and intentions** on the appropriate frequency.\n- At uncontrolled aerodromes, use the **standard overhead join** before joining the circuit at a standard position.\n- **At NZPP we don't use the SOHJ** – follow the joining procedures published in the AIP.\n- Be aware of other aircraft in the vicinity, paying close attention to inbound and outbound traffic information from Flight Service.\n\n### Give-way rules\n\n**Aircraft established in the circuit have right of way over aircraft joining.** If there's traffic in the circuit at NZPP, orbit and wait for a gap in a location that won't conflict with circuit traffic.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [CAA: Vacating and joining at aerodromes](https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/vacating-and-joining-at-aerodromes/)\n- [CAA: Standard overhead join](https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/fixed-wing-flight-training-safety-strategy/standard-overhead-join/)","category":"Aerodrome & Circuit","tags":["circuit-join","give-way","nzpp","sohj","aip"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"CAA: Vacating and joining at aerodromes","url":"https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/vacating-and-joining-at-aerodromes/"},{"label":"CAA: Standard overhead join","url":"https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/fixed-wing-flight-training-safety-strategy/standard-overhead-join/"}],"published_date":"2025-02-21","sent_at":"2025-02-21T00:33:38+00:00","is_published":true,"source_email_subject":"Weekly Flyer","original_title":null,"original_body":"Safety Message: Joining the Aerodrome Circuit and Give-Way Rules\n\nWhen joining the circuit at an aerodrome, safety and communication are critical for a smooth and safe operation. The circuit is typically flown in a standardised pattern to avoid conflicts between aircraft, and adhering to the give-way rules ensures a safe and predictable flow of traffic.\n\nJoining the Circuit:\n\nAlways make your intentions clear by broadcasting your position and intentions on the appropriate frequency. When at uncontrolled aerodromes use the Standard Overhead Join Procedure before joining the circuit at a standard position.\n\nHere in NZPP we don't use the SOHJ so follow the Joining procedures found in the AIP.  Ensure you are aware of other aircraft in the vicinity, paying close attention to both inbound and outbound traffic which can be received from Flight Service.\n\nGive way rules\n\nThose established in the circuit have right of way over those who are joining the circuit. If there is Traffic in the circuit at NZPP orbit and wait for a spacing in a location that will not conflict with the Circuit traffic.","editor_notes":"Kept original title; subheadings and list formatting; light copy edit."},{"id":39,"slug":"start-up-in-a-safe-position-and-direction","title":"Start Up in a Safe Position and Direction","summary":"Before start-up, check the aircraft is positioned and pointed so its exhaust won't blow into hangars, other aircraft or other sensitive areas.","body_markdown":"As part of your pre-start checks – and as outlined in each aircraft's checklist – make sure the aircraft is in the **correct location and pointing in the correct direction** before start-up.\n\nAlways check the aircraft is positioned so it **won't blow exhaust gases into hangars, other aircraft or any other sensitive areas**. This keeps people and equipment safe and reduces the risk of damage or hazardous situations.","category":"Ground Ops","tags":["engine-start","apron","exhaust","pre-start","checklist"],"links":[],"published_date":"2025-02-27","sent_at":"2025-02-27T23:00:51+00:00","is_published":true,"source_email_subject":"Weekly Flyer","original_title":null,"original_body":"Safety Reminder: Aircraft Startup Location and Direction\n\nAs part of our pre-start checks, and as outlined in the checklists for each aircraft, it is essential to ensure the correct location and direction when starting up. Always verify that the aircraft is positioned to avoid blowing exhaust gases into hangars, other aircraft, or any other sensitive areas. This helps to maintain the safety of personnel and equipment and reduces the risk of damage or hazardous situations.","editor_notes":"Removed 'Safety Reminder:' heading prefix; light copy edit."},{"id":40,"slug":"plan-your-ground-movements-on-busy-days","title":"Plan Your Ground Movements on Busy Days","summary":"NZPP gets busy at weekends – brief your ground movements, enter and vacate the runway promptly, and consider vacating via Hotel or Foxtrot and taxiing on Golf.","body_markdown":"NZPP can get busy – especially at weekends, when pilots from around the country and from our club take to the skies. That means more ground traffic too.\n\nThink about how you taxi, and how you can enter and vacate the runway promptly during busy circuit times. A thorough brief of your ground movements will help you use the aerodrome layout to its full potential.\n\n**Have you considered vacating via Hotel or Foxtrot and taxiing on Golf instead of Alpha on a busy day?**","category":"Aerodrome & Circuit","tags":["taxiing","ground-traffic","nzpp","runway-vacating","busy-days"],"links":[],"published_date":"2025-03-08","sent_at":"2025-03-08T02:44:06+00:00","is_published":true,"source_email_subject":"Weekly Flyer","original_title":null,"original_body":"Weekend Traffic Jams (Ground)\n\nNZPP can become a busy aerodrome especially on weekends as pilots from around the country and from our club take to the skies. This increases the volume of ground traffic at NZPP. Considerations need to take place about how we taxi around and enter/vacate the runway in a prompt fashion during those busy circuit times. A thorough brief of the ground movements will ensure you are using the aerodrome layout to its full capability. Have you ever considered vacating via hotel or foxtrot and using golf to taxi instead of Alpha on a busy day?","editor_notes":"Light copy edit."},{"id":41,"slug":"dont-enter-the-runway-ahead-of-short-final-traffic","title":"Don't Enter the Runway Ahead of Short-Final Traffic","summary":"Aircraft entering the runway with traffic on short final have forced go-arounds: look out thoroughly before entering, and go around whenever the approach isn't right.","body_markdown":"Aircraft entering the runway while another aircraft is on short final have caused multiple go-arounds at our aerodrome. It highlights the need for vigilance – and for a timely go-around when conditions aren't right.\n\nWhether it's due to pilot error, misjudgement or an external factor, **if at any point during your approach you're not satisfied, go around**. It's always safer to power up and try again than to continue in uncertain circumstances.\n\n**Before entering the runway**, do a thorough lookout and be fully aware of the traffic in the circuit. Check especially for aircraft on final approach or going around, and confirm the positions of nearby aircraft before you proceed. Situational awareness is key to preventing dangerous incidents on the ground and in the air.\n\n### Go-around sequence\n\n1. **Power up** – apply full power.\n2. **Pitch up** – set the appropriate climb attitude.\n3. **Clean up** – retract flaps or adjust as necessary.\n4. **Communicate** – once safely climbing, make your radio call.\n\nAlways remember the fundamental order: **Aviate, Navigate, Communicate.**\n\n**Further reading:**\n\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)","category":"Aerodrome & Circuit","tags":["go-around","runway-entry","lookout","short-final","situational-awareness"],"links":[{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"}],"published_date":"2025-03-14","sent_at":"2025-03-14T18:53:51+00:00","is_published":true,"source_email_subject":"Weekly Flyer","original_title":null,"original_body":"Go-Around Procedures and Safety Awareness\n\nThere have been multiple incidents recently where aircraft have entered the runway while other aircraft were on short final for landing, resulting in go-arounds. This highlights the critical need for vigilance and the timely execution of a go-around when conditions are not optimal. Whether it's due to pilot error, misjudgment, or an external factor, if at any point during your approach you are not satisfied with the situation, do not hesitate to initiate a go-around. It is always safer to power up and try again than to continue under uncertain circumstances.\n\nAdditionally, when entering the runway, it is essential to conduct a thorough lookout and be fully aware of the traffic in the circuit. Always check for other aircraft in the vicinity, especially those on final approach or performing go-arounds. Confirm the positions of any nearby aircraft before you proceed to ensure there is no conflict. Situational awareness is key to preventing dangerous incidents on the ground and in the air.\n\nPower up – Apply full power.\n\nPitch up – Set the appropriate climb attitude.\n\nClean up – Retract flaps or adjust as necessary.\n\nCommunicate – Once safely climbing, make your radio call.\n\nAlways prioritize safety by remembering the fundamental order: Aviate, Navigate, Communicate.","editor_notes":"Reworded 'There have been multiple incidents recently' as timeless; numbered the go-around sequence."},{"id":42,"slug":"report-defects-however-minor","title":"Report Defects, However Minor","summary":"Even minor damage such as a broken wheel spat must be reported to an instructor and logged on MIFIS straight away.","body_markdown":"It's crucial to **report any issue to an instructor immediately**, whether you notice it during or after your flight. For example, a broken wheel spat was once found on MWM that hadn't been reported.\n\nPrompt reporting means problems can be dealt with quickly, preventing further damage or complications. If you notice anything unusual, tell an instructor and **complete the necessary form on MIFIS**.","category":"Aircraft & Engine","tags":["defects","wheel-spats","reporting","mifis"],"links":[],"published_date":"2025-03-21","sent_at":"2025-03-21T21:31:52+00:00","is_published":true,"source_email_subject":"Weekly Flyer","original_title":null,"original_body":"It was recently observed that MWM had a broken wheel spat, which had not been previously reported. As a reminder, it is crucial to report any issues, whether during or after your flights, to an instructor immediately. Prompt reporting allows for quick action to resolve any problems, preventing further damage or complications. If you notice anything unusual, please ensure you report it to an instructor and complete the necessary form on MIFIS.","editor_notes":"Same template as #36; reworded 'It was recently observed that MWM had a broken wheel spat' as a timeless example."},{"id":43,"slug":"walk-around-the-aircraft-after-every-flight","title":"Walk Around the Aircraft After Every Flight","summary":"Do a quick post-flight walkaround and report anything unusual through MIFIS, even if you don't think you caused it.","body_markdown":"After every flight, take a moment to **walk around the aircraft and check for damage or irregularities**. Even if you don't think you caused it, **report anything unusual through MIFIS** and have a chat with an instructor.\n\nIf small issues go unreported, we may miss more serious ones. A quick check at the end of your flight helps keep our aircraft in top condition and stops minor damage from becoming a bigger problem.","category":"Aircraft & Engine","tags":["post-flight","walkaround","defects","mifis"],"links":[],"published_date":"2025-03-28","sent_at":"2025-03-28T04:03:24+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 28th March 2025","original_title":null,"original_body":"Post-Flight Walkaround & Reporting\n\nAfter every flight, take a moment to walk around the aircraft and check for any damage or irregularities. Even if you don’t think you caused it, report anything unusual through MIFIS and chat to an instructor. If small issues go unreported, we may miss more serious ones. A quick check at the end of your flight helps keep our aircraft in top condition and prevents minor damage from becoming bigger problems.","editor_notes":"Light copy edit."},{"id":44,"slug":"dont-orbit-in-the-circuit","title":"Don't Orbit in the Circuit","summary":"Orbiting in the NZPP circuit is not permitted except in an emergency; if separation is lost, climb to 1,500 ft and vacate the circuit safely.","body_markdown":"Here's some clarification on best practice around orbiting in the circuit at Paraparaumu.\n\nThe standard procedure for orbiting in the circuit is a **360° medium turn in the opposite direction to the circuit**. It's commonly used at controlled aerodromes to create extra spacing between aircraft – but when orbiting, it's crucial to be aware of other traffic, particularly any aircraft following or nearby.\n\nAlthough CAA guidance and the AIP don't specifically mention avoiding orbits at uncontrolled aerodromes, **the practice is strongly discouraged**. An orbiting aircraft will at some point be flying in the opposite direction to the circuit at the same altitude, which can easily lead to a dangerous situation.\n\n**The Kāpiti Airport Noise Management Plan states: aircraft are not permitted to orbit within the aerodrome circuit, except in an emergency.**\n\nIf you need to leave the circuit because separation has been lost, the preferred method is to **climb to 1,500 ft and then vacate**, making sure you maintain safe separation from other traffic. Continuing in the circuit without adequate separation, or where there's potential for conflict, is not acceptable.","category":"Aerodrome & Circuit","tags":["orbit","circuit","separation","noise-management","nzpp"],"links":[],"published_date":"2025-04-03","sent_at":"2025-04-03T23:57:38+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 4th April","original_title":null,"original_body":"Orbiting in the Circuit\n\nWe’ve had a few recent instances of aircraft orbiting in the circuit at Paraparaumu, and we’d like to take this opportunity to clarify best practices.\n\nThe standard procedure for orbiting in the circuit is to perform a 360° medium turn in the opposite direction to the circuit. This manoeuvre is commonly used at controlled aerodromes to help create additional spacing between aircraft. However, when orbiting, it’s crucial to be aware of other traffic, particularly any aircraft following or nearby.\n\nAlthough the CAA guidance and AIP don’t specifically mention the avoidance of orbits at uncontrolled aerodromes, this practice is still strongly discouraged. Orbiting creates the risk of conflicting traffic, as the aircraft performing the orbit will be flying in the opposite direction to the circuit at the same altitude at some point. This can easily lead to a dangerous situation.\n\nThe Kāpiti Airport Noise Management Plan states: Aircraft are not permitted to orbit within the aerodrome circuit, except in an emergency.\n\nIf you do need to vacate the circuit becasue there has been a loss of seperation, a preferred method is to climb to 1500' and then vacate, ensuring you maintain safe separation from any other traffic. Continuing to fly in the circuit without adequate separation or where there is a potential for conflict is not acceptable.","editor_notes":"Reworded 'We've had a few recent instances of aircraft orbiting' as timeless; typo fixes (becasue, seperation)."},{"id":45,"slug":"make-sure-airside-gates-latch-shut","title":"Make Sure Airside Gates Latch Shut","summary":"Check airside gates fully close and latch behind you – re-enter the PIN if needed – to keep the apron secure from unauthorised access.","body_markdown":"Whenever you enter or leave the apron, **check the airside access gate has fully closed and latched behind you**. Gates left partially open compromise airfield security and can allow unauthorised access to the apron.\n\nTake a moment to look back and confirm the gate has completely latched before you continue on your way. You may need to re-enter the PIN code to get the gate to latch properly.","category":"Ground Ops","tags":["security","airside-gate","apron","access"],"links":[],"published_date":"2025-04-10","sent_at":"2025-04-10T22:14:38+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 11th April 2025","original_title":null,"original_body":"Airside Gates\n\nPlease remember to check the airside access gates fully close behind you whenever entering or exiting the apron area. We've recently noticed gates are being left partially open after use. It's really important we make sure these gates are fully locked to maintain airfield security and prevent unauthorised access to the apron.\n\nTake a moment to look back and confirm the gate has completely latched shut before continuing on your way. You may need to re-enter the pin code to get the gate to latch properly.","editor_notes":"Reworded 'We've recently noticed gates are being left partially open' as timeless."},{"id":46,"slug":"avoid-runway-incursions-at-paraparaumu","title":"Avoid Runway Incursions at Paraparaumu","summary":"Look out and broadcast before entering the runway strip, never create parallel operations, give landing aircraft right of way, and leave at least a runway length of spacing.","body_markdown":"Runway incursions typically involve **inadequate spacing** between aircraft during take-off and landing, or aircraft **entering the runway strip without making the appropriate radio calls**.\n\nMake sure you've completed a lookout and clearly broadcast your intentions **before entering the runway strip**. The boundaries of the runway strip are shown on the aerodrome chart by dashed lines. If you manoeuvre into this area, you are legally on the runway, and there's a risk of simultaneous parallel operations.\n\nA parallel operation is one where two parallel runways are used at the same time. **This is strictly prohibited at Paraparaumu.** We must follow the right-of-way rules:\n\n**Aircraft landing have right of way over aircraft taking off.**\n\nWhen preparing to line up, always assess spacing carefully. A good rule of thumb is to **wait until the preceding aircraft is at least a full runway length away**. If the aircraft ahead is using the grass runway, allow even more space, as it will turn crosswind through your upwind path shortly after take-off.\n\n**Further reading:**\n\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Aerodrome & Circuit","tags":["runway-incursion","runway-strip","parallel-operations","spacing","right-of-way"],"links":[{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"},{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2025-04-18","sent_at":"2025-04-18T01:50:15+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 18th April 2025","original_title":null,"original_body":"Runway Incursions\n\nThere has been an increase in runway incursions over the past month or two. These incidents have typically involved inadequate spacing between aircraft during take-off and landing, or aircraft entering the runway strip without making the appropriate radio calls.\n\nEnsure you’ve completed a lookout, and have clearly broadcast your intentions before entering the runway strip. The boundaries of the runway strip are depicted on the aerodrome plate using dashed lines. If you manoeuvre into this area, you are legally on the runway and there is a risk of simultaneous parallel operations occurring.\n\nA parallel operation is one where two parallel runways are used at the same time. This is strictly prohibited at Paraparaumu. We must abide by the right of way rules:\n\nAircraft landing have right of way over aircraft taking off.\n\nWhen preparing to line-up, always assess spacing carefully. A good rule of thumb is to wait until the preceding aircraft is at least a full runway length away. If an aircraft ahead is using the grass runway, allow even more space, as they will turn crosswind through your upwind path shortly after take-off.","editor_notes":"Removed 'There has been an increase in runway incursions over the past month or two'; light copy edit."},{"id":47,"slug":"allow-for-shorter-days-on-cross-countries","title":"Allow for Shorter Days on Cross-Countries","summary":"In shorter winter days the final 1700 booking slot is close to ECT – build a buffer and be on the ground 30 minutes before ECT unless night-current.","body_markdown":"In the shorter days of autumn and winter, the final booking slot (ending at **1700**) is much closer to ECT. Keep this in mind, especially when planning cross-country flights.\n\nIt's good practice to give yourself an appropriate buffer before ECT or curfew, whichever is more restrictive. With flying, everything always takes longer than you expect.\n\nOur SOPs state you should be **on the ground 30 minutes before ECT unless you are night-current**.\n\nIf you're not sure, speak to one of the instructors before your next cross-country flight.","category":"Procedures & SOPs","tags":["ect","winter","cross-country","booking","sop"],"links":[],"published_date":"2025-05-09","sent_at":"2025-05-09T04:21:55+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 9th May 2025","original_title":null,"original_body":"Cross Country Flying in Shorter Days\n\nShorter days means the final booking slot, which ends at 1700 is a lot closer to ECT. This is especially important when planning for cross country flights.\n\nIt's good practice to give yourself an appropriate buffer to either ECT or curfew, whichever is the most restrictive. With flying, everything always takes longer than you expect.\n\nOur SOPs state you should be on the ground 30 minutes before ECT unless you are night-current.\n\nSpeak to one of the instructors before your next cross country flight if you're not sure.","editor_notes":"Replaced 'Shorter days means' (seasonal notice) with 'In the shorter days of autumn and winter'; expanded version of #1."},{"id":48,"slug":"apron-habits-that-keep-everyone-safe","title":"Apron Habits That Keep Everyone Safe","summary":"Walk behind aircraft, never push one in front of a running aircraft, start up pointing somewhere safe with the beacon on, keep passengers close and pick up loose items.","body_markdown":"A few unsafe habits can creep in on the apron – like pushing aircraft directly in front of others that are running, or passengers wandering ahead unsupervised.\n\n- **Walk behind aircraft, not in front**, where possible – especially if an engine is running or about to start.\n- **Never push an aircraft in front of one that is starting or already running.**\n- Before start-up, make sure your aircraft is **pointed in a safe direction, with the beacon on**.\n- When escorting passengers across the apron, **keep them close at all times**. Make sure they know to stay with you and, if they drop something on the apron, not to run back for it.\n- If you spot loose items lying around, **pick them up**. Once it's in the bin by the airside gate, log it in MIFIS.","category":"Ground Ops","tags":["apron","passengers","propeller","beacon","fod"],"links":[],"published_date":"2025-05-16","sent_at":"2025-05-16T02:44:31+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 16th May 2025","original_title":null,"original_body":"Apron Safety\n\nLately we’ve noticed a few unsafe habits creeping in on the apron —  like pushing aircraft directly in front of others that are running, or passengers wandering ahead unsupervised.\n\nWhere possible, walk behind aircraft, not in front — especially if an engine is running or about to start. If you’re moving a plane, do not push it in front of one that’s starting or already running.\n\nBefore startup, make sure your aircraft is pointed in a safe direction, with the beacon light on.\n\nIf you’re escorting passengers across the apron, keep them nearby at all times. Make sure they know to stay with you, and if they drop something on the apron, not to run back for it.\n\nAnd finally, if you spot any loose items lying around, pick them up. Once it’s in the bin by the airside gate, log it in MIFIS.","editor_notes":"Reworded 'Lately we've noticed a few unsafe habits creeping in' as timeless; converted to a list."},{"id":49,"slug":"look-after-the-propeller","title":"Look After the Propeller","summary":"Feel prop leading edges for nicks in the pre-flight, keep the area in front clear, taxi carefully on gravel, avoid rough-ground run-ups and stay off the northern grass where possible.","body_markdown":"The propeller is one of the most under-appreciated components in general aviation. We're taught early on how to stay safe around it, but not nearly as much about how to look after it.\n\nThat care starts with your pre-flight:\n\n- **Run your fingers along the leading edge** of each blade, feeling for nicks, dents or scratches – any of these can become a starting point for corrosion and fatigue.\n- Before start-up, make sure the area **in front of and below the propeller is clear**. At low RPM, it can draw in debris from up to **two metres** away.\n\nWhen taxiing:\n\n- On unsealed surfaces, **taxi with the yoke held aft** to help lift the nose and protect the blades from loose gravel.\n- **Avoid run-ups on gravel or rough ground.**\n- Cross between different surfaces at a **45° angle** wherever possible.\n\nTo help reduce wear and tear, please **avoid taxiing on the grass north of the aero club** unless absolutely necessary. If you need to access the northern grass area, taxi via the gap between the white tyres on Taxiway E to avoid rough patches.","category":"Aircraft & Engine","tags":["propeller","preflight","taxiing","gravel","prop-care"],"links":[],"published_date":"2025-05-23","sent_at":"2025-05-23T22:23:37+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 24th May 2025","original_title":null,"original_body":"The propeller is one of the most under appreciated components in general aviation. We’re taught early on how to stay safe around it, but not nearly as much about how to take care of it. That care starts with your pre-flight. Run your fingers along the leading edge of each blade, feeling for nicks, dents, or scratches — any of which can become a starting point for corrosion and fatigue. Before startup, ensure the area in front of and below the prop is clear. At low RPM, it can draw in debris from up to two metres away. On unsealed surfaces, taxi with the yoke held aft to help lift the nose and protect the blades from loose gravel. Avoid run-ups on gravel or rough ground, and remember to cross between different surfaces at a 45° angle wherever possible. To help reduce wear and tear, please avoid taxiing on the grass north of the Aero Club unless absolutely necessary. If you need to access the northern grass area, taxi via the gap between the white tyres on Taxiway E to avoid rough patches.","editor_notes":"Broke single paragraph into lists; light copy edit."},{"id":50,"slug":"engine-fire-during-start-prevent-and-respond","title":"Engine Fire During Start: Prevent and Respond","summary":"Avoid over-priming, which commonly causes start-up fires, and know your aircraft's engine-fire-during-start procedure – the C152 example is outlined.","body_markdown":"Engine fires during start-up are rare, but they are a risk – especially in cold conditions, when the engine is more likely to be over-primed. All pilots should know how to respond.\n\n**Prevention is the most important step:** follow the correct priming procedure for your aircraft and **avoid over-priming**, a common cause of engine fires during start.\n\nMake sure you know the **engine fire during start** procedure in your aircraft's flight manual or Pilot's Operating Handbook (POH). For example, the Cessna 152 checklist includes:\n\n1. **Cranking** – CONTINUE.\n2. **If the engine starts:**\n   - Power – 1700 RPM for a few minutes.\n   - Engine – SHUT DOWN.\n3. **If the engine fails to start:**\n   - Cranking – CONTINUE.\n   - Fire extinguisher – use if needed.\n   - Engine – SECURE: master switch OFF, ignition switch OFF, fuel shutoff valve OFF.\n   - Fire – EXTINGUISH.\n   - Inspect for damage and report.\n\nProcedures vary between aircraft – make sure you know the emergency procedures for the aircraft you're flying, and always use the current POH checklist.","category":"Emergencies","tags":["engine-fire","engine-start","priming","c152","emergency-procedures"],"links":[],"published_date":"2025-06-01","sent_at":"2025-06-01T04:50:52+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 1 June 2025","original_title":null,"original_body":"Engine Fire During Start\n\nWhile rare, engine fires during start-up are a risk—especially in cold conditions where the engine is more likely to be over-primed. It's important that all pilots know how to respond accordingly.\n\nThe most important step is prevention: Follow the correct priming procedure for your aircraft. Avoid over-priming, which is a common cause of engine fires during start.\n\nMake sure  you know the engine fire on start procedure outlined in your Flight Manual or Pilot Operating Handbook (POH).\n\nFor example, the checklist for the Cessna 152 states:\n\nIf engine starts:\n\nContinue cranking If engine starts:\n\nSet power to 1700 RPM for a few minutes\n\nThen SHUT DOWN the engine\n\nIf engine fails to start:\n\nContinue cranking\n\nUse fire extinguisher if needed\n\nEngine secure:\n\nMaster switch – OFF\n\nIgnition switch – OFF\n\nFuel shutoff valve – OFF\n\nExtinguish fire\n\nInspect for damage and report\n\nProcedures may vary between aircraft—ensure you know the emergency procedures for the aircraft you’re flying.","editor_notes":"UNSURE/GARBLED SOURCE: the C152 checklist in the source was garbled (duplicated 'If engine starts:' heading, no initial 'continue cranking' step). Restructured using only the items in the source. The source omits some POH items (e.g. throttle/mixture settings if the engine fails to start) – recommend an instructor checks this against the current C152 POH before publishing."},{"id":51,"slug":"dont-skip-the-checklist","title":"Don't Skip the Checklist","summary":"Slow down and use the checklist every time; in winter, wait for the oil temperature to reach the green before run-ups, even if it takes 5–10 minutes.","body_markdown":"Checklists help us standardise procedures, reduce human error and make sure nothing important is missed.\n\nAs keen aviators, we're naturally eager to get airborne – but rushing the process can lead to missed or incomplete checklist items. Taking a moment to slow down and follow the steps properly is always worth it.\n\nIn winter, it's especially important to make sure the engine is **sufficiently warmed up** before putting it under any stress. **Check the oil temperature is in the green range before starting your run-ups** as part of your checklist. If that means waiting 5–10 minutes, that's perfectly fine – it prevents unnecessary strain on the engine.\n\nKey things to keep in mind when using checklists:\n\n- **Consistency** – use the checklist on every flight, no exceptions.\n- **Don't rush** – going too fast increases the risk of missing items.\n- **Confirm visually** – if the checklist requires you to select or move something, look and double-check it's the correct control.","category":"Procedures & SOPs","tags":["checklist","warm-up","oil-temperature","run-up","winter"],"links":[],"published_date":"2025-06-06","sent_at":"2025-06-06T05:21:39+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 6th June 2025","original_title":null,"original_body":"Don’t Skip the Checklist\n\nChecklists help us standardise procedures, reduce human error, and make sure nothing important is missed.\n\nAs keen aviators, we’re naturally eager to get airborne — but rushing the process can lead to missed or incomplete checklist items. Taking a moment to slow down and follow the steps properly is always worth it.\n\nWith winter setting in, it’s especially important to make sure the engine is sufficiently warmed up before putting it under any stress . You should always check that the oil temperature is in the green range before starting run-ups as part of your checklist.\n\nIf it means waiting 5–10 minutes, that’s perfectly fine — it prevents unnecessary strain on the engine.\n\nA few key things to keep in mind when using checklists:\n\nConsistency – Use the checklist for every flight, no exceptions.\n\nDon’t rush – Going too fast increases the risk of missing items.\n\nConfirm visually – If the checklist requires you to select or manipulate something, look and double-check that it’s the correct control.","editor_notes":"Kept original title; replaced 'With winter setting in' with 'In winter'; list formatting."},{"id":52,"slug":"stay-ahead-of-the-weather-on-winter-cross-countries","title":"Stay Ahead of the Weather on Winter Cross-Countries","summary":"Winter brings low cloud and fog: check all weather sources for the right times, re-check before heading home, and decide early to turn back or divert.","body_markdown":"Winter can be a great time to fly, but it also brings extra weather challenges: low cloud, fog, and those sneaky conditions that never showed up in the forecast.\n\nIf you're heading out on a cross-country, **check the right weather for the right time**. Check validity periods and use everything available: TAFs, METARs, GRAFORs, webcams – even a quick call to someone on the ground at your destination can help.\n\nJust as important, **check the weather again before you head home**. Things can change while you're on the ground having that cuppa.\n\nForecasts are sometimes wrong – what matters is how you respond. If things start to look questionable, **make the decision early**. Don't wait until you're committed.\n\n\"Get-home-itis\" has caught out plenty of good pilots. **Turning back or diverting early is always safer** than pushing on and hoping it'll improve.\n\n**Further reading:**\n\n- [PreFlight – aviation weather and briefing](https://gopreflight.co.nz/)\n- [CAA GAP booklet: VFR MET (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/vfr-met-web.pdf)\n- [CAA Vector: Stuck in the middle with you](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/stuck-in-the-middle-with-you/)","category":"Weather","tags":["weather","cross-country","winter","get-home-itis","diversion","forecasts"],"links":[{"label":"PreFlight – aviation weather and briefing","url":"https://gopreflight.co.nz/"},{"label":"CAA GAP booklet: VFR MET (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/vfr-met-web.pdf"},{"label":"CAA Vector: Stuck in the middle with you","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/stuck-in-the-middle-with-you/"}],"published_date":"2025-06-13","sent_at":"2025-06-13T00:07:28+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 13th June 2025","original_title":null,"original_body":"Flying Cross-Country in Winter: Stay Ahead of the Weather\n\nWinter can be a great time to fly, but it also brings extra weather challenges: low cloud, fog, and those sneaky conditions that never showed up in the forecast.\n\nIf you're heading out on a cross-country, make sure you're checking the right weather for the right time. That means checking the validity periods and using everything available: TAFs, METARs, GRAFORS, webcams, even a quick call to someone on the ground at your destination can be helpful.\n\nJust as important, make sure you check the weather again before you head home. Things can change while you’re on the ground having that cuppa.\n\nAs we know, sometimes forecasts are wrong. What matters is how you respond. If things start to look questionable, make the decision early . Don’t wait until you’re committed.\n\n“Get-home-itis” has caught out plenty of good pilots.\n\nTurning back or diverting early is always safer than pushing on and hoping it’ll improve.","editor_notes":"Title adapted from the original heading; 'Winter can be a great time to fly' kept as a general (timeless) statement; light copy edit."},{"id":53,"slug":"dont-skip-the-interior-check","title":"Don't Skip the Interior Check","summary":"A member once found scissors under the pilot's seat before an aerobatic flight – always check and secure the interior as part of the pre-flight.","body_markdown":"The interior check is one of those steps that's easy to skip when your focus is on the walk-around – but it matters.\n\nDuring the pre-flight for an aerobatic flight, one of our members once found **a large pair of scissors tucked under the pilot's seat**. It was exactly the kind of overlooked item that could have had serious consequences in the air – a sharp reminder (pun intended) of why thorough interior checks are so important.\n\nA pre-flight inspection covers three areas: **documents, exterior and interior**. Taking a few extra minutes to secure everything inside the cockpit – including pens, checklists, tools and personal items – can prevent serious distractions or hazards in flight.\n\n**Further reading:**\n\n- [CAA Vector: FOD in the cockpit](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/)","category":"Airmanship","tags":["preflight","interior-check","loose-items","aerobatics","cockpit"],"links":[{"label":"CAA Vector: FOD in the cockpit","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/"}],"published_date":"2025-06-20","sent_at":"2025-06-20T00:44:43+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 20th June 2025","original_title":null,"original_body":"Don’t Skip the Interior Check\n\nRecently, we shared a safety message about making sure you check the interior of the aircraft as part of the preflight inspection. It’s one of those steps that’s easy to skip when your focus is on the walk-around.\n\nLast weekend, one of our members had a very good example of why the interior check is so important!\n\nDuring the preflight for an aerobatic flight, they found a large pair of scissors tucked under the pilot’s seat. It was the kind of overlooked item that could have had serious consequences in the air. It’s a sharp reminder (pun intended) of why thorough interior checks are so important before we go flying.\n\nA preflight inspection covers three areas: the documents, the exterior, and the interior . Taking a few extra minutes to secure everything inside the cockpit, including pens, checklists, tools, and personal items, can prevent serious distractions or hazards during flight.","editor_notes":"Kept original title; removed 'Recently, we shared a safety message...' and 'Last weekend, one of our members...' time references."},{"id":54,"slug":"check-the-undercarriage-on-every-pre-flight","title":"Check the Undercarriage on Every Pre-Flight","summary":"In the pre-flight, check wheel hubs for orange or pink brake fluid, feel tyres for flat spots, and make sure the wheel fairings are secure and undamaged.","body_markdown":"We often focus on fuel, oil and control surfaces during a pre-flight, but the undercarriage deserves attention too – there are several key things to check.\n\n- **Brake fluid leaks:** check around the wheel hubs. The fluid is usually orange or pink and can be easy to miss, especially on dark tarmac.\n- **Tyres:** look closely at the tread and run your hand over the surface to feel for **flat spots**. These can develop from hard braking and aren't always easy to spot.\n- **Wheel fairings:** check they're secure and free from damage.\n\nAs always, let one of the instructing team know if you notice anything unusual.","category":"Aircraft & Engine","tags":["preflight","undercarriage","tyres","brakes","wheel-fairings"],"links":[],"published_date":"2025-06-27","sent_at":"2025-06-27T04:02:04+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 27th June 2025","original_title":null,"original_body":"Preflight Undercarriage Check\n\nWe often focus on fuel, oil, and control surfaces during a preflight, but it’s also important to pay attention to the undercarriage because there are a number of key things you should be checking.\n\nWhen you're doing your walk-around, take a moment to check around the wheel hubs for any signs of brake fluid leaks. The fluid is usually orange or pink and can be easy to miss, especially on dark tarmac.\n\nAs you’re checking the wheels, take a close look at the tyre tread and run your hand over the surface to feel for any flat spots. These can develop from hard braking and aren’t always easy to spot right away. Finally, check the wheel fairings are secure and free from any damage.\n\nAs always, make sure you let one of the instructing team know if you notice anything unusual.","editor_notes":"List formatting; light copy edit."},{"id":55,"slug":"use-the-preferred-vfr-arrival-and-departure-routes","title":"Use the Preferred VFR Arrival and Departure Routes","summary":"Follow NZPP's preferred VFR arrival and departure routes; northbound departures off RWY 16 should cross the threshold at 1,000 ft or preferably higher.","body_markdown":"NZPP has **preferred VFR arrival and departure routes** to support the safe and orderly flow of traffic in and out of the aerodrome.\n\nThese procedures reduce the chance of conflicts, especially at busy times when circuit, training and transiting aircraft are all operating at once. For everyone's safety, **follow the preferred routes whenever practicable**.\n\n### Northbound departures off Runway 16\n\nDepart via the downwind leg and cross overhead the Runway 16 threshold at **no lower than 1,000 ft**. Climbing **above 1,000 ft is strongly encouraged**, as aircraft going around from Runway 16 may also be climbing through that altitude, which could result in a loss of separation.\n\nReview the NZPP VFR procedures in AIP New Zealand before your next flight.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Aerodrome & Circuit","tags":["vfr-routes","departures","arrivals","nzpp","runway-16","go-around"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2025-07-04","sent_at":"2025-07-04T03:08:02+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 4th July 2025","original_title":null,"original_body":"Preferred VFR Arrival/ Departure Procedures\n\nNZPP has preferred VFR arrival and departure routes to support the safe and orderly flow of traffic in and out of the aerodrome.\n\nThese procedures help reduce the chance of conflicts, especially during busy times when circuit, training, and transiting aircraft are all operating simultaneously.\n\nFor everyone’s safety, pilots are encouraged to follow the preferred routes whenever possible.\n\n🛫 Important note for northbound departures off Runway 16:\n\nPilots should depart via the downwind leg and cross overhead the Runway 16 threshold at no less than 1000 feet. However, climbing above 1000 feet is strongly encouraged, as aircraft conducting a go-around from Runway 16 may also be climbing through that altitude, which could result in a loss of separation.\n\nTake a moment to review the attached VFR procedures chart and keep them in mind before your next flight.","editor_notes":"Removed emoji and 'attached VFR procedures chart' reference; pointed to AIP NZ."},{"id":56,"slug":"take-in-the-whole-aircraft-before-the-walkaround","title":"Take In the Whole Aircraft Before the Walkaround","summary":"Start the pre-flight from a few steps back: check the wings are level, look for puddles, marks or anything hanging off, and spot flat tyres hidden by spats.","body_markdown":"The pre-flight inspection is one of the most critical steps before any flight. Unlike a car, an aircraft can't simply pull over if something goes wrong mid-air.\n\nMost of us are pretty good at checking that every rivet is secure and all the control surfaces move freely. That attention to detail is essential, but it can also narrow our focus.\n\n**The pre-flight should begin the moment you walk up to the aircraft.** Take a few steps back and ask:\n\n- Are the wings level and symmetrical?\n- Are there any puddles under the aircraft, or marks on the fuselage that weren't there before?\n- Is anything hanging off the aircraft that shouldn't be?\n\nIf the aircraft has spats, a flat or worn tyre can easily hide underneath. A quick look from a few metres away often gives a better sense of tyre condition than inspecting it up close.\n\nSo on your next pre-flight, do more than check the parts – **take in the whole aircraft**.","category":"Airmanship","tags":["preflight","walkaround","tyres","situational-awareness"],"links":[],"published_date":"2025-07-11","sent_at":"2025-07-11T00:22:54+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 11th July 2025","original_title":null,"original_body":"Before the Walkaround Begins\n\nThe pre-flight inspection is one of the most critical steps before any flight. Unlike a car, an aircraft cannot simply pull over if something goes wrong mid-air.\n\nMost of us are pretty good when it comes to checking that every rivet is secure and all control surfaces move freely. That attention to detail is essential, but it can also narrow our focus.\n\nThe pre-flight should begin from the moment you walk up to the aircraft. Take a few steps back. Are the wings level and symmetrical? Are there any puddles under the plane or marks on the fuselage that weren’t there before? Is anything hanging off the aircraft that should not be?\n\nIf the plane has spats, keep in mind that a flat or worn tyre can easily hide underneath. A quick glance from a few metres away often gives a better sense of tyre condition than inspecting it up close.\n\nSo on your next pre-flight, do more than just check the parts. Take in the whole aircraft.","editor_notes":"Light copy edit; converted questions to a list."},{"id":57,"slug":"wear-your-life-jacket-from-start-up-to-shutdown","title":"Wear Your Life Jacket From Start-Up to Shutdown","summary":"Wear your life jacket for the whole flight over water with the inflation tag visible – a local pilot who ditched survived an hour in the sea thanks to his.","body_markdown":"Most GA cockpits are too cramped to safely reach and put on a life jacket in an emergency. Trying to unbuckle and put one on after an engine failure or during a forced landing is, in most cases, unrealistic. **Wearing it from start-up to shutdown** means you're always ready to pull the inflation tag without delay or fumbling.\n\n**Never tuck the yellow inflation tag inside the vest.** In cold, rough water, struggling to find it could be the difference between staying afloat and going under. Keep it visible and easy to reach at all times.\n\n### A local pilot's experience\n\nA local pilot who ditched off the top of the South Island after an engine failure survived nearly an hour in the water, largely thanks to his life jacket. He wore it correctly, with **crotch straps, a water-activated strobe light and a spray hood**. The hood helped shield his face from the waves and had high-visibility reflectors that played a key role in helping rescuers find him.\n\nEven with that level of preparation, he later reflected on what he would do differently:\n\n> \"I had three other life jackets in the plane, but two were in the baggage compartment. If mine had failed, I would have been in serious trouble. Next time, I'd keep the spares in the back seat or within arm's reach. That small change could save someone else's life.\"\n\nHe also recommended carrying a **waterproof marine VHF radio** and a visual marker such as a **diving safety sausage** to improve your visibility in the water.\n\nRead his full story in the CAA Vector article *Out of the blue*.\n\n**Further reading:**\n\n- [CAA Vector: Out of the blue](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/out-of-the-blue/)\n- [CAA Vector: It's called a 'life' jacket for a reason](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/)\n- [CAA GAP booklet: Survival (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf)","category":"Emergencies","tags":["life-jacket","over-water","ditching","survival","vector"],"links":[{"label":"CAA Vector: Out of the blue","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/out-of-the-blue/"},{"label":"CAA Vector: It's called a 'life' jacket for a reason","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/"},{"label":"CAA GAP booklet: Survival (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf"}],"published_date":"2025-07-18","sent_at":"2025-07-18T01:34:58+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 18th July 2025","original_title":null,"original_body":"Flights Over Water Safety\n\nMost GA cockpits are too cramped to safely access a life jacket in an emergency. Trying to unbuckle and put one on after an engine failure or during a forced landing is, in most cases, unrealistic. Wearing it from startup to shutdown ensures you are always ready to pull the inflation tag without delay or fumbling.\n\nNever tuck the yellow inflation tag inside the vest. In cold, rough water, struggling to find it could be the difference between staying afloat and going under. Keep it visible and easy to reach at all times.\n\nThis was highlighted last year when a local pilot ditched off the top of the South Island following an engine failure. He survived nearly an hour in the water, largely thanks to his life jacket, which he wore correctly with crotch straps, a water-activated strobe light, and a spray hood. The hood helped shield his face from waves and included high-visibility reflectors that played a key role in helping rescuers find him.\n\nEven with that level of preparation, he later reflected on what he would do differently.\n\n“I had three other life jackets in the plane, but two were in the baggage compartment. If mine had failed, I would have been in serious trouble. Next time, I’d keep the spares in the back seat or within arm’s reach. That small change could save someone else's life.”\n\nHe also recommended carrying a waterproof marine VHF radio and a visual marker like a diving safety sausage to improve visibility in the water.\n\nTo learn more about this pilot’s story and what helped him survive, check out the full article in the latest issue of CAA Vector magazine.","editor_notes":"Replaced 'This was highlighted last year' and 'the latest issue of CAA Vector magazine' with timeless wording and a verified link to the matching Vector Online article ('Out of the blue')."},{"id":58,"slug":"keep-the-baggage-compartment-tidy","title":"Keep the Baggage Compartment Tidy","summary":"Return covers and gear to their proper place after every flight – a messy baggage compartment causes wear, safety risks, lost items and costs for the club.","body_markdown":"Keeping the baggage compartment tidy isn't just good practice – it's also an important part of your pre-flight inspection. Loose or incorrectly stored gear can cause unnecessary wear, create safety risks or go missing.\n\nAfter each flight, **return everything to its proper place**. If you're not sure where something belongs, ask an instructor.\n\nFor example, MWM's baggage compartment was once left in an unacceptable condition: the aircraft cover hadn't been packed into its bag, and the engine and pitot covers were left loose rather than stored in their usual spots. It might seem minor, but misplaced or damaged items can lead to costly replacements for the club and affect other members' experience.","category":"Ground Ops","tags":["baggage","tidiness","covers","post-flight","preflight"],"links":[],"published_date":"2025-07-25","sent_at":"2025-07-25T02:18:02+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 25th July 2025","original_title":null,"original_body":"Safety Reminder: Aircraft Tidiness\n\nKeeping the baggage compartment tidy is not just good practice, it is also an important part of your preflight inspection. Loose gear or items stored incorrectly can create unnecessary wear, pose safety risks, or end up going missing. After each flight, please take a moment to return everything to its proper place. If you are not sure where something belongs, ask an instructor.\n\nThe image below shows the baggage compartment of MWM left in an unacceptable condition. The aircraft cover was not packed into its bag, and the engine and pitot covers were left loose rather than stored in their usual spots. While it might seem minor, misplaced or damaged items can lead to costly replacements for the club, and impact the experience for other members.","editor_notes":"Removed 'Safety Reminder:' prefix and image reference ('The image below shows...'); kept the MWM example as text."},{"id":59,"slug":"hang-up-tie-downs-when-not-in-use","title":"Hang Up Tie-Downs When Not in Use","summary":"Don't leave tie-downs on the ground – they're a trip hazard and can damage aircraft or vehicles; hang them on the fence beside the flight line.","body_markdown":"Don't leave tie-downs lying on the ground when they're not in use. They're a **trip hazard** and can damage aircraft or vehicles that pass over them.\n\nWhen tie-downs aren't in use, **hang them neatly on the fence beside the flight line**. It keeps the area safe and tidy.\n\nIf you're ever unsure, have a chat to an instructor.","category":"Ground Ops","tags":["tie-downs","apron","trip-hazard","tidiness"],"links":[],"published_date":"2025-08-01","sent_at":"2025-08-01T03:17:36+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 1st August 2025","original_title":null,"original_body":"Aircraft Tie-downs\n\nA reminder not to leave tie-downs lying on the ground when they’re not in use. They can be a tripping hazard and may damage aircraft or vehicles that pass over them.\n\nWhenever tie-downs aren’t in use, please hang them neatly on the fence beside the flight line. It keeps the area safe, tidy.\n\nIf you're ever unsure, have a chat to an instructor.","editor_notes":"Light copy edit."},{"id":60,"slug":"best-practice-for-managing-fuel-contamination","title":"Best Practice for Managing Fuel Contamination","summary":"Drain fuel after refuelling and at every pre-flight, let it settle, check it's blue and clean, and discard drained fuel into the club jerry cans.","body_markdown":"Around **40% of engine failures** are caused by fuel exhaustion, starvation or contamination.\n\n**What is fuel contamination?** It happens when foreign substances such as water, dirt or even bits of metal get into the fuel system. This can cause engine failure by blocking fuel lines, damaging components or interfering with combustion.\n\n### Best practice\n\n- **Always drain the fuel after refuelling.**\n- **Drain from all available points** during your pre-flight.\n- After refuelling, **allow the fuel time to settle**.\n- If the aircraft has been parked outside or recently refuelled, a fuel drain is especially important.\n- Check the fuel is the **correct colour (blue for avgas)**, with no water, dirt or other visible contamination.\n\nIf you find contamination, speak with an instructor. **If contamination is still present after three drains**, the aircraft may need to be checked by engineering.\n\n**Discard all drained fuel into one of the club's jerry cans** near the fuel trailers – not onto the ground.\n\n**Further reading:**\n\n- [CAA GAP booklet: Fuel management (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf)","category":"Aircraft & Engine","tags":["fuel","contamination","fuel-drain","avgas","preflight"],"links":[{"label":"CAA GAP booklet: Fuel management (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf"}],"published_date":"2025-08-08","sent_at":"2025-08-08T06:03:06+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 1st August 2025","original_title":null,"original_body":"Fuel Contamination\n\nAround 40% of engine failures are caused by fuel exhaustion, starvation, or contamination.\n\nWhat is fuel contamination? Fuel contamination occurs when foreign substances like water, dirt, or even bits of metal make their way into the fuel system. This can lead to engine failure by blocking fuel lines, damaging components, or interfering with combustion.\n\nBest Practise for managing fuel contamination:\n\nAlways drain the fuel after refuelling.\n\nDrain from all available points during your pre-flight.\n\nAfter refuelling, allow the fuel time to settle.\n\nIf the aircraft has been parked outside or recently refuelled, a fuel drain is especially important.\n\nCheck that the fuel is the correct colour (blue for Avgas), and ensure there is no water, dirt, or any visible contamination.\n\nIf you do find contamination, speak with an instructor. If contamination is still present after three drains, the aircraft may need to be checked by engineering.\n\nAll drained fuel should be discarded into one of the club’s jerry cans located near the fuel trailers, not onto the ground.","editor_notes":"List formatting; 'Best Practise' corrected to 'Best practice'."},{"id":61,"slug":"hold-clear-if-unsure-near-the-circuit","title":"Hold Clear If Unsure Near the Circuit","summary":"If unsure overhead, vacate to at least 2 NM, sort yourself out and return; brief passengers to stay quiet in critical phases and to point out traffic.","body_markdown":"Operating safely in or near the circuit requires good judgement and situational awareness at all times. If you arrive overhead and feel unsure, or need to rethink your approach, **don't hesitate to vacate the overhead**. Fly at least **2 NM** away from the aerodrome, hold clear, get yourself sorted, and return when ready.\n\nIf you have passengers on board, brief them clearly before flight:\n\n- Ask them **not to talk during critical phases** of flight.\n- Agree on a **hand signal that means \"stop talking\"**.\n- Ask them to **point out any aircraft** they see, and explain how you'll acknowledge it.","category":"Aerodrome & Circuit","tags":["circuit","overhead","passengers","sterile-cockpit","situational-awareness"],"links":[],"published_date":"2025-08-15","sent_at":"2025-08-15T08:08:18+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 15th August 2025","original_title":null,"original_body":"Safety in the vicinity of the Circuit\n\nOperating in or near the circuit safely requires good judgment, and maintaining situational awareness at all times. If you arrive overhead and feel unsure or need to rethink your approach, don’t hesitate to vacate the overhead. Fly at least 2 nm away from the airfield, hold clear, get yourself sorted, and return when ready.\n\nIf you have passengers on board, ensure you have briefed them clearly before flight. Ask them not to engage in conversation during critical phases, and agree on a hand signal that means “stop talking.” Include in the brief that if they see another aircraft, they should point it out and how you’ll acknowledge it.","editor_notes":"List formatting; light copy edit."},{"id":62,"slug":"changing-runways-reverse-direction-safely","title":"Changing Runways: Reverse Direction Safely","summary":"To change runways, extend downwind, turn 180° opposite to the circuit direction and rejoin downwind – only when sure of traffic positions and after clear radio calls.","body_markdown":"Joining an aerodrome doesn't mean you have to land there – it's an assessment of whether the conditions are acceptable. Even if you do attempt a landing, **going around once or even twice** because of an unstable approach is always the right decision. After that, it's time to consider a different runway or **diverting** to a more suitable aerodrome.\n\nIf you need to change runways, there's a safe, standard way to do it:\n\n1. **Extend downwind.**\n2. Make a **180° turn in the opposite direction** to the circuit you were flying.\n3. **Rejoin downwind** for the new runway.\n\nThis reverses your direction and positions you correctly for the new circuit. Only carry out this manoeuvre when you're **certain of other aircraft positions**, and always communicate clearly with circuit traffic so everyone is aware of your intentions.","category":"Aerodrome & Circuit","tags":["circuit","runway-change","go-around","diversion","radio"],"links":[],"published_date":"2025-08-22","sent_at":"2025-08-22T07:40:56+00:00","is_published":true,"source_email_subject":"Weekly Flyer 22nd August 2025","original_title":null,"original_body":"Change of Circuit Direction\n\nJoining an airfield doesn’t mean you have to land there. It’s an assessment that the conditions are acceptable. Even if you do attempt a landing, going around once or even twice due to an unstable approach is always the right decision. After that, it’s time to consider a different runway or diverting to a more suitable airfield.\n\nIf you need to change runways, there is a safe and standard way to do this: extend downwind, then make a 180° turn in the opposite direction to the circuit you were flying, and rejoin downwind for the new runway.\n\nThis procedure ensures you reverse direction and position yourself correctly for the new circuit. Only carry out this manoeuvre when you are certain of other aircraft positions, and always communicate clearly with traffic in the circuit so that everyone is aware of your intentions.","editor_notes":"Numbered procedure; light copy edit."},{"id":63,"slug":"look-both-ways-before-entering-a-runway","title":"Look Both Ways Before Entering a Runway","summary":"Before lining up or crossing any runway, turn the aircraft if needed to look properly both ways, and ask AFIS at NZPP for traffic positions if unsure.","body_markdown":"Before entering or crossing any runway, carry out a **thorough lookout in both directions**. This applies both when lining up to depart and when crossing a runway to get somewhere else on the aerodrome.\n\nA safe lookout takes more than just turning your head. **Manoeuvre the aircraft as necessary** so you can see clearly in both directions – physically turning the aircraft is often the only way to achieve this.\n\nAt NZPP, if you're unsure about traffic in the circuit, don't hesitate to **ask AFIS for an update** on aircraft positions to help your situational awareness.\n\n**Further reading:**\n\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)","category":"Aerodrome & Circuit","tags":["lookout","runway-entry","runway-crossing","afis","taxiing"],"links":[{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"}],"published_date":"2025-08-29","sent_at":"2025-08-29T01:02:48+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 29th August 2025","original_title":null,"original_body":"Lookout before entering a runway\n\nBefore entering or crossing any runway, it’s important to carry out a thorough lookout in both directions. This applies for both lining up to depart, and also when crossing  a runway to get somewhere else on the aerodrome.\n\nA safe lookout requires more than just turning your head. You should manoeuvre the aircraft as necessary so you can position yourself to see clearly in both directions. Physically turning the plane is often the only way to achieve this.\n\nIf at NZPP and you’re unsure about traffic in the circuit, don’t hesitate to ask AFIS for an update on aircraft positions to help with your situational awareness.","editor_notes":"Light copy edit."},{"id":64,"slug":"current-isnt-always-proficient-in-crosswinds","title":"Current Isn't Always Proficient in Crosswinds","summary":"Being current isn't the same as being proficient in strong, variable crosswinds – book a practice flight, consider diverting if beyond your comfort level, and students keep to 8 kt.","body_markdown":"Unsettled weather and changeable winds mean it's crosswind season at NZPP!\n\nMany of us may not have dealt with strong, variable crosswinds for some time. Remember that **being current doesn't always mean being proficient**, especially when it comes to consistent crosswind landings.\n\nTake the opportunity to book a quick flight with an instructor and sharpen your skills.\n\nIf you encounter crosswinds on the main runway that are beyond your comfort level, **don't hesitate to consider diverting**.\n\n**Student pilots: remember the 8 kt crosswind limitation.**","category":"Airmanship","tags":["crosswind","proficiency","currency","student-pilots","diversion"],"links":[],"published_date":"2025-09-05","sent_at":"2025-09-05T05:31:55+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 5th September 2025","original_title":null,"original_body":"Crosswind Season\n\nAutumn brings unstable weather and changeable winds, and we’ve already had our share this month. Here at NZPP, that  of course means it is crosswind season!\n\nMany of us haven’t dealt with strong, variable crosswinds for some time. Remember that being current does not always mean being proficient, especially when it comes to consistent crosswind landings.\n\nTake this opportunity to book a quick flight with an instructor, sharpen your skills, and make the most of the September special.\n\nIf you encounter crosswinds on the main runway that are beyond your comfort level, do not hesitate to consider diverting.\n\nAnd for our student pilots, please remember the 8 kt crosswind limitation.","editor_notes":"Removed seasonal reference (source said 'Autumn brings...' in a September message – in NZ that is spring) and 'this month'; removed promotional reference to the 'September special'."},{"id":65,"slug":"tie-down-techniques-for-windy-conditions","title":"Tie-Down Techniques for Windy Conditions","summary":"Before windy weather, review how to secure parked aircraft: hangar or fixed tie-downs first, otherwise a crossover picket kit hammered in front of the wing.","body_markdown":"Every year aircraft are needlessly damaged by wind gusts because of inattention to forecasts, negligence or inadequate tie-downs. Before the windier months – and whenever strong winds are forecast – it pays to brush up on picketing techniques and other precautions against wind damage to parked aircraft.\n\nIdeally, secure the aircraft in a storm-proof hangar or other suitable shelter. If hangarage isn't available, the remaining option is to tie the aircraft down securely in a suitable location. Many New Zealand aerodromes have only a limited number of fixed tie-down points, and these may be reserved for local aircraft. If a fixed tie-down isn't available, find a sheltered spot to park.\n\n### Carry a picket kit\n\nThis may mean using your own pickets. It's a good idea to carry a set in case you're stuck at a remote aerodrome with no other way to secure the aircraft. A picket set should include:\n\n- six steel stakes\n- three crossover tubes\n- three ropes of appropriate length\n- a mallet or hammer\n\nall stowed in a bag. **Include the pickets in your weight and balance calculations**, and stow them securely so they don't become a problem in turbulence.\n\n### Choosing where and how to picket\n\n- Pickets can pull out under strain if the ground is soft or becomes wet.\n- Coiled pickets are difficult to get into stony ground and more likely to pull out of soft ground.\n- **Crossover pickets are the most suitable**, as they're more likely to stay put even if the ground gets wet.\n- Lead the underwing ropes to points **outboard and forward** of the underwing attachment points.\n- Hammer pickets all the way into the ground, **always in front of the wing**.\n\nFor more detail, see the CAA's Secure your aircraft GAP booklet.\n\n**Further reading:**\n\n- [CAA GAP booklet: Secure your aircraft (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/secure-your-aircraft.pdf)","category":"Ground Ops","tags":["picketing","tie-downs","wind","parking","gap-booklet"],"links":[{"label":"CAA GAP booklet: Secure your aircraft (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/secure-your-aircraft.pdf"}],"published_date":"2025-09-12","sent_at":"2025-09-12T05:19:03+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 12th September 2025","original_title":null,"original_body":"Each year aircraft are damaged by wind gusts because of inattention to weather forecasts, negligence or inadequate tiedown measures. Now that ‘windy season’ is here, it 's a good time to brush up on recommended picketing techniques and other precautions against wind damage to parked aircraft.\n\nIdeally, we want to secure our aircraft in a storm-proof hangar or other suitable shelter. If appropriate hangarage isn’t available, the remaining option is to tie down your aircraft securely in a suitable location. Many aerodromes around New Zealand, however, only have a limited number of places available for securing aircraft to fixed tie-down points and these may be reserved for local aircraft. If a fixed tiedown point isn’t available, find a sheltered place to park your aircraft.\n\nThis may mean you’ll need to use your own set of pickets. It’s a good idea to carry a set of pickets with you, in case you are stuck at a remote aerodrome with no other way to secure your aircraft. Your picket set should include six steel stakes, three crossover tubes, and three ropes of appropriate length –all stowed in a bag. You’ll also need a mallet or hammer. Remember to include the pickets in your weight and balance calculations, and ensure they’re well-secured in the aircraft before flight. Stow them carefully so they don’t become a problem during turbulence.\n\nTake care when choosing where you’ll picket your aircraft. Pickets can pull out under strain if the ground is soft, or becomes wet. The coiled type is difficult to get into stony ground and may be more likely to pull out in soft ground. The cross-over type of pickets are the most suitable, as they’re more likely to stay in the ground, even if it becomes wet. The underwing ropes should be led to points outboard and forward of the underwing attachment point. Hammer pickets all the way into the ground, always in front of the wing.","editor_notes":"Near-identical repost of #12. Replaced 'Now that windy season is here' with timeless phrasing; body aligned with the edited #12."},{"id":66,"slug":"return-equipment-and-keep-the-apron-clear","title":"Return Equipment and Keep the Apron Clear","summary":"Apron safety is shared – look out for anything out of place and return towbars, tie-downs and other equipment as soon as you've finished with them.","body_markdown":"Safety in the operational areas of an aerodrome is a shared responsibility. Every pilot should always be **on the lookout for things that are out of place** or could affect the safe operation of any aircraft.\n\nFor example, a towbar was once left in the grass near the northern hangar – an area often used for taxiing and parking aircraft. Imagine what would happen to a propeller if someone accidentally taxied over it.\n\n**Return towbars, tie-downs and any other equipment** that doesn't belong on the apron to its proper place as soon as you've finished with it.","category":"Ground Ops","tags":["apron","fod","towbar","equipment","shared-responsibility"],"links":[],"published_date":"2025-09-19","sent_at":"2025-09-19T05:07:12+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 19th September 2025","original_title":null,"original_body":"Safety on the apron\n\nSafety in the operational areas of an airfield is a shared responsibility. This means each and every pilot should always be in the lookout for things that are out of place or could impact the safe operation of any aircraft.\n\nA towbar was left near the northern hangar in the grass. This is an area that is often used to taxi and parking of aircraft. You can imagine what would happen to a prop should anyone accidentally had taxied over it. Please ensure you return towbars, tiedowns, or any other equipment that doesn't belong on the apron to its appropriate place as soon as you are finished with it.","editor_notes":"Reworded the specific towbar incident as a timeless example; grammar fixes ('in the lookout', 'had taxied')."},{"id":67,"slug":"convert-utc-correctly-when-daylight-saving-changes","title":"Convert UTC Correctly When Daylight Saving Changes","summary":"During daylight saving (NZDT) add 13 hours to UTC when reading TAFs, METARs and briefings; during NZST add 12 hours.","body_markdown":"When daylight saving begins, New Zealand switches to **NZDT**, so you'll need to **add 13 hours to UTC** when reading TAFs, METARs or any briefing published in UTC.\n\nWhen daylight saving ends and we return to **NZST**, add **12 hours** to UTC instead.\n\nDouble-check your time conversions whenever the clocks change.","category":"Weather","tags":["daylight-saving","utc","nzdt","taf","metar"],"links":[],"published_date":"2025-09-26","sent_at":"2025-09-26T05:29:58+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 26th September 2025","original_title":null,"original_body":"Not so much a safety message this week, but still an important reminder:\n\nDaylight savings begins this weekend, which means from Sunday onwards we’ll be on NZDT . That means you'll need to start adding +13 hours to UTC when you’re checking TAFs, METARs, or any briefing published in UTC.","editor_notes":"Rewritten from a one-off notice ('Daylight savings begins this weekend... from Sunday onwards'); removed 'Not so much a safety message this week'; added the NZST (+12) conversion for completeness."},{"id":68,"slug":"separation-is-your-job-in-uncontrolled-airspace","title":"Separation Is Your Job in Uncontrolled Airspace","summary":"Separation in uncontrolled airspace is the pilot's responsibility: keep a slow, thorough scan, give accurate position reports and actively coordinate with nearby traffic.","body_markdown":"In uncontrolled airspace, **responsibility for separation from other aircraft rests entirely with the pilot**. To maintain situational awareness we use several tools – mainly lookout and radio calls.\n\n**Lookout** – make it slow and thorough. The ideal scan rate is roughly **20 degrees every 2 seconds**. Make an effort to check around the aircraft's blind spots.\n\n**Radio calls** – position reports must be accurate and on the correct frequency. Include:\n\n- who you're talking to\n- your callsign\n- your current position\n- altitude\n- intentions\n\nFor example: *\"Otaki Traffic, EKM, overhead Peka Peka Ponds, 1500 ft, tracking north along the coast.\"*\n\nBe mindful of where frequencies change – for example, from Tararua Traffic 118.3 to Manawatu Traffic 122.6 (always confirm current frequencies on your chart). There may be transiting aircraft in the area that haven't made a radio call yet.\n\nWhen you hear radio calls, think about how that traffic affects you now and in the future. **Making a position report doesn't absolve you from maintaining separation.** If you're heading to the training area and know there's traffic nearby, talk to them to arrange separation – for example, one stays landside and one stays seaward, or use vertical separation.\n\n**Further reading:**\n\n- [CAA GAP booklet: Plane talking (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-plane-talking.pdf)\n- [CAA: Work Together, Stay Apart](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-initiatives/work-together-stay-apart/)","category":"Airspace & Radio","tags":["lookout","radio","separation","uncontrolled-airspace","training-area"],"links":[{"label":"CAA GAP booklet: Plane talking (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-plane-talking.pdf"},{"label":"CAA: Work Together, Stay Apart","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-initiatives/work-together-stay-apart/"}],"published_date":"2025-10-03","sent_at":"2025-10-03T02:37:40+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 3rd October 2025","original_title":null,"original_body":"In uncontrolled airspace, the responsibility of separation from other aircraft falls entirely on the pilot . To maintain situational awareness, we utilise several tools, predominantly the look-out and radio calls.\n\nLookouts - these need to be sufficiently slow and thorough. The ideal scan rate is approximately 20 degrees every 2 seconds. An effort needs to be made to check around the aircraft's blind spots.\n\nRadio calls - when giving a position report, these need to be accurate and on the correct frequency. The contents should include who you are talking to, your callsign, your current position, altitude, and intentions. E.g.\"Otaki Traffic EKM overhead Peka Peka Ponds 1500ft tracking North along the coast\"\n\nBe mindful of where frequencies change, e.g. from Tararua Traffic 118.3 to Manawatu Traffic 122.6. Be aware there may be transiting aircraft in the area that haven't made a radio call yet.\n\nWhen we hear radio calls we need to think about how the traffic affects us now, and in future. Just making a position report doesn't absolve you from maintaining separation. If you are heading to the training area and know there is traffic nearby, communicate with them to ensure separation e.g. one stays landside and one stays seaward, or vertical separation","editor_notes":"Near-identical repost of #27; body aligned with the edited #27."},{"id":69,"slug":"no-simultaneous-parallel-operations-at-nzpp","title":"No Simultaneous Parallel Operations at NZPP","summary":"Never take off or land on the sealed runway, grass runway or FATO while another aircraft is using a parallel one; landing traffic has right of way.","body_markdown":"**Simultaneous parallel operations are not permitted at Paraparaumu.** Aircraft must not land or take off on the sealed RWY 16/34, the grass RWY 16/34 or the helicopter FATO while another aircraft is taking off or landing on a parallel runway.\n\nA parallel operation is one where two parallel runways are used at the same time – and it's strictly prohibited here. We must follow the right-of-way rules:\n\n**Aircraft landing have right of way over aircraft taking off.**\n\nWhen you decide to take off, make sure there's **sufficient spacing – at least a runway length**. If the preceding aircraft is using the grass runway, give it even more space, as it will turn across your upwind path.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Aerodrome & Circuit","tags":["parallel-operations","runway","grass-runway","fato","spacing"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2025-10-10","sent_at":"2025-10-10T03:27:47+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 10th October 2025","original_title":null,"original_body":"Parallel Operations\n\nSimultaneous parallel operations are not permitted. Aircraft are not to land or take off on paved RWY 16/34, grass RWY 16/34, or the helicopter FATO while aircraft are taking off or landing for the parallel runway. A parallel operation is one where two parallel runways are used at the same time. This is strictly prohibited at Paraparaumu. We must abide by the right of way rules:\n\nAircraft landing have right of way over aircraft taking off\n\nWhen decided to take-off, we must ensure at there is sufficient spacing - at least a runway length. If the preceding aircraft is using the grass runway, give them even more space as they will turn across your upwind path.","editor_notes":"Kept meaning of original title 'Parallel Operations'; light copy edit ('paved' changed to 'sealed')."},{"id":70,"slug":"save-your-starter-motor","title":"Save Your Starter Motor","summary":"Follow your starter's duty cycle – in ELA, crank no more than 10 seconds, cool 20 seconds between attempts, and rest 30 minutes after six tries.","body_markdown":"Understand and follow the **duty cycle** of your aircraft's starter to make sure it lasts as long as possible.\n\nThe duty cycle defines how many starting attempts the starter can handle and how long it must cool between each one. Ignoring these limits can overheat the starter and damage its internal components, leading to premature or even total failure. In some cases, just a few violations can make the starter inoperable.\n\nAlways follow the specific guidelines for your aircraft. For example, in **ELA (C152)**:\n\n- Don't crank the starter for **more than 10 seconds**.\n- Allow **20 seconds to cool** between attempts.\n- After **six tries**, let it cool for **30 minutes**.","category":"Aircraft & Engine","tags":["starter","duty-cycle","c152","engine-start"],"links":[],"published_date":"2025-10-17","sent_at":"2025-10-17T06:10:53+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 17th October 2025","original_title":null,"original_body":"Save your Starter Motor\n\nIt’s important to understand and follow the duty cycle of your aircraft’s starter to ensure it lasts as long as possible.\n\nThe duty cycle defines how many starting attempts the starter can handle and how long it must cool between each one. Ignoring these limits can cause the starter to overheat and damage internal components, leading to premature or even total failure. In some cases, just a few violations can render the starter inoperable.\n\nAlways follow the specific guidelines for your aircraft. For example, in ELA (C152) , ' do not crank the starter for more than 10 seconds , allow 20 seconds to cool between attempts, and after six tries , let it cool for 30 minutes .'","editor_notes":"Condensed repost of #9; kept original title (Title Case); list formatting."},{"id":71,"slug":"go-around-when-in-doubt","title":"Go Around When in Doubt","summary":"Gusty conditions are a reminder to go around whenever the approach isn't right – power, pitch, clean up, then radio once safely climbing.","body_markdown":"Bumpy, gusty conditions are a good prompt to refresh both the importance and the procedure of a go-around.\n\nA go-around may be necessary for many reasons. You may have misjudged something – simple pilot error – or it could be the result of someone or something else. Whatever the reason, **if you're not happy at any time during the approach, don't hesitate to go around**. If you're ever unsure, it's always safer to power up and try again.\n\n**Keep it simple** during a go-around – don't try to do multiple things at once. Remember the order:\n\n1. **Power up**\n2. **Pitch up**\n3. **Clean up**\n4. **Radio call** – once the aircraft is climbing away and everything is in order.\n\nAlways: **Aviate, Navigate, Communicate.**","category":"Aerodrome & Circuit","tags":["go-around","landing","gusty-conditions","aviate-navigate-communicate"],"links":[],"published_date":"2025-10-24","sent_at":"2025-10-24T01:04:59+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 24th October 2025","original_title":null,"original_body":"This spring has certainly come with bumpy westerlies and gusty conditions!\n\nThis weeks safety message is a reminder of both the importance and procedure of conducting a go around. There are many times a go around may be necessary. You may have misjudged something with simple pilot error, or it could be a result of someone or something else. Whatever the reason may be, if you are not happy at any time during the approach, do not hesitate to go around. If you are ever unsure, it is always the safer move to power up and try again next time\n\nKeep it simple when you are conducting a go around, do not try to do multiple things at once. Remember the order: power up, pitch up, clean up, then make the radio call once the plane is climbing away and everything is in order. Always Aviate, Navigate, Communicate.","editor_notes":"Near-identical repost of #32. Removed 'This spring has certainly come with bumpy westerlies' and 'This week's safety message'."},{"id":72,"slug":"birds-on-the-aerodrome-report-and-wait","title":"Birds on the Aerodrome: Report and Wait","summary":"Birds of any size are a hazard – tell AFIS where they are and wait patiently (shut down if needed) while the airport vehicle clears them.","body_markdown":"At times there is significant bird activity on the operational areas of the aerodrome at Paraparaumu. **Birds, even small ones, can pose a significant safety risk** to general aviation aircraft.\n\nAFIS staff are quite proactive about warning pilots of birds on the runway. If you spot birds in the operational areas, or are told about them, **contact AFIS on frequency** and let them know where they are.\n\n**Be patient and wait for the airport vehicle to complete its bird scare.** If necessary, taxi to a suitable place and shut down for a few minutes while the birds are removed.\n\n**Further reading:**\n\n- [CAA GAP booklet: Bird hazards (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/Bird_Hazards.pdf)\n- [CAA: Reporting bird incidents](https://www.aviation.govt.nz/safety/notify-us/reporting-bird-incidents/)","category":"Aerodrome & Circuit","tags":["birds","afis","bird-scaring","runway","nzpp"],"links":[{"label":"CAA GAP booklet: Bird hazards (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/Bird_Hazards.pdf"},{"label":"CAA: Reporting bird incidents","url":"https://www.aviation.govt.nz/safety/notify-us/reporting-bird-incidents/"}],"published_date":"2025-10-30","sent_at":"2025-10-30T20:34:41+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 31st October 2025","original_title":null,"original_body":"Bird Hazards on the Aerodrome\n\nIf you have flown from PP recently you will have noticed significant bird activity on the operational areas of the aerodrome.\n\nBirds, even small ones, can pose a significant safety risk for general aviation aircraft.\n\nAFIS staff are quite proactive at warning pilots of birds on the runway. If you detect or are notified of birds in the operational areas, contact  AFIS on frequency and let them know where they are.\n\nPlease be patient and wait for the airport vehicle to complete its bird scare. You can taxi the plane to a suitable place and shut down the engine for a few minutes to wait for the birds to be removed if necessary.","editor_notes":"Reworded 'If you have flown from PP recently you will have noticed significant bird activity' as timeless."},{"id":73,"slug":"cross-country-small-things-keys-and-fuel-cards","title":"Cross-Country Small Things: Keys and Fuel Cards","summary":"On cross-countries, take the keys with you when you leave the aircraft, check your fuel cards are correct and current, and use the club's cross-country checklist.","body_markdown":"When you're heading off on longer cross-country trips, double-check the small things that can easily trip you up.\n\n- When you step out of the aircraft at another aerodrome, **take the keys with you**. We've had a few near misses with pilots accidentally locking themselves out.\n- Check you have the **correct fuel cards** for the aerodromes you're visiting, and that they **haven't expired**.\n\nThe **cross-country checklist** is available at the club next to the sign-out forms. It's the easiest way to make sure you haven't forgotten something small that could become a big problem later on!","category":"Procedures & SOPs","tags":["cross-country","keys","fuel-cards","checklist","away-landings"],"links":[],"published_date":"2025-11-07","sent_at":"2025-11-07T01:55:48+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 7th November 2025","original_title":null,"original_body":"With the worst of the weather hopefully behind us, it is great to see more cross-country flying again!\n\nAs you get back into longer trips, a quick reminder to double-check the small things that can easily trip you up.\n\nWhen you step out of the aircraft at another aerodrome, we recommend you take the keys with you. We have had a few near-misses with pilots accidentally locking themselves out.\n\nAlso check that you have the correct fuel cards for the aerodromes you are visiting, and that they have not expired.\n\nThe cross-country checklist (below) is available at the club next to the sign-out forms. It is the easiest way to ensure you have not forgotten something small that could become a big problem later on!","editor_notes":"Removed 'With the worst of the weather hopefully behind us'; removed image reference ('checklist (below)')."},{"id":74,"slug":"keep-go-arounds-simple-in-gusty-conditions","title":"Keep Go-Arounds Simple in Gusty Conditions","summary":"In bumpy, gusty conditions don't hesitate to go around – do one thing at a time: power, pitch, clean up, then the radio call.","body_markdown":"Bumpy, gusty conditions are a good prompt to refresh both the importance and the procedure of a go-around.\n\nA go-around may be necessary for many reasons. You may have misjudged something – simple pilot error – or it could be the result of someone or something else. Whatever the reason, **if you're not happy at any time during the approach, don't hesitate to go around**. If you're ever unsure, it's always safer to power up and try again.\n\n**Keep it simple** during a go-around – don't try to do multiple things at once. Remember the order:\n\n1. **Power up**\n2. **Pitch up**\n3. **Clean up**\n4. **Radio call** – once the aircraft is climbing away and everything is in order.\n\nAlways: **Aviate, Navigate, Communicate.**","category":"Aerodrome & Circuit","tags":["go-around","gusty-conditions","landing","aviate-navigate-communicate"],"links":[],"published_date":"2025-11-14","sent_at":"2025-11-14T04:33:26+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 14th November 2025","original_title":null,"original_body":"This season has certainly come with bumpy northerlies and gusty conditions!\n\nThis weeks safety message is a reminder of both the importance and procedure of conducting a go around. There are many times a go around may be necessary. You may have misjudged something with simple pilot error, or it could be a result of someone or something else.\n\nWhatever the reason may be, if you are not happy at any time during the approach, do not hesitate to go around. If you are ever unsure, it is always the safer move to power up and try again next timeKeep it simple when you are conducting a go around, do not try to do multiple things at once. Remember the order: power up, pitch up, clean up, then make the radio call once the plane is climbing away and everything is in order. Always: Aviate, Navigate, Communicate.","editor_notes":"Near-identical repost of #32. Removed 'This season has certainly come with bumpy northerlies' and 'This week's safety message'; fixed run-together sentence ('next timeKeep')."},{"id":75,"slug":"sunscreen-water-and-sunshades-on-hot-days","title":"Sunscreen, Water and Sunshades on Hot Days","summary":"Make sunscreen and water part of your cross-country prep, follow IMSAFE on hot days, and put the sunshade up when you pack the aircraft away.","body_markdown":"On sunny days, be aware of the harmful UV rays that shine through the windows into the cockpit.\n\n- On longer cross-countries, **make sunscreen a checklist item** before you take off.\n- **Take water with you** on warm, sunny cross-countries – it's a must.\n- Follow the **IMSAFE** checklist, including drinking plenty of water on hot days.\n\nWhen packing the aircraft away after your flight, **put the sunshade up on the dash** so the aircraft doesn't turn into a sauna for the next pilot.","category":"Human Factors","tags":["sun","hydration","imsafe","sunshade","cross-country"],"links":[],"published_date":"2025-11-21","sent_at":"2025-11-21T03:53:52+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 21st November 2025","original_title":null,"original_body":"As we start to see more sunny days for flying we need to be aware of the harmful sun rays that shine through the windows into our cockpits. On longer cross countries please make sure that sunscreen becomes a checklist item before you take off. Taking water along with you on the sunny warm cross countries is a must as well.\n\nWhen packing the aircraft away after your flight please ensure that the sunshade is put up on the dash to avoid the aircraft turning into a sauna for the next pilots.\n\nPlease ensure that you are adhering to the IMSAFE checklist including plenty of water intake on hot days.","editor_notes":"Near-identical repost of #33. Replaced 'As we start to see more sunny days' with timeless phrasing."},{"id":76,"slug":"why-we-wear-life-vests-over-water","title":"Why We Wear Life Vests Over Water","summary":"Wear a life vest whenever flying over water, as putting one on in a cramped cockpit in an emergency is unrealistic; keep the inflation tag easy to reach.","body_markdown":"Legal or club requirements aside, wearing a life vest when flying over water is about giving ourselves **the best chance of survival** in the unlikely event of a ditching – or of ending up in the water after an overrun.\n\nGA cockpits are usually too small to keep vests within easy reach of each occupant, and too tight to unbuckle and put a vest on in an emergency. **Wearing the vest from the start** means you're ready to pull the inflation tag immediately, however you end up in the water.\n\nWhen wearing the vest in flight, **don't tuck the yellow inflation tag inside the vest** – it must always be easy to reach.\n\nIf you're not sure where the life jackets are kept at the aero club, ask an instructor.\n\n**Further reading:**\n\n- [CAA Vector: It's called a 'life' jacket for a reason](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/)\n- [CAA GAP booklet: Survival (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf)","category":"Emergencies","tags":["life-jacket","over-water","ditching","survival"],"links":[{"label":"CAA Vector: It's called a 'life' jacket for a reason","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/its-called-a-life-jacket-for-a-reason/"},{"label":"CAA GAP booklet: Survival (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/survival.pdf"}],"published_date":"2025-11-28","sent_at":"2025-11-28T03:46:52+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 28th November 2025","original_title":null,"original_body":"Legal or club requirements aside, wearing a life vest when flying over water in General Aviation is about giving ourselves the best chance of survival in the unlikely event of a ditching or ending up in the water after an overrun.\n\nGeneral Aviation cockpits are usually too small to keep vests within easy reach of each occupant. They are also tight spaces, which makes it difficult to unbuckle and put a vest on in an emergency. Wearing the vest from the start means you are ready to pull the inflation tag immediately, no matter how you end up in the water.\n\nWhen wearing the vest in flight, do not tuck the yellow inflation tag inside the vest . The tag must always be easy to access.\n\nIf you are unsure where the lifejackets are kept at the aero club, please ask an instructor.","editor_notes":"Light copy edit."},{"id":77,"slug":"what-to-expect-from-a-bfr","title":"What to Expect From a BFR","summary":"A BFR every two years is a chance to improve, not a one-shot test – practise forced landings and low flying regularly so you meet your licence standard.","body_markdown":"Once you hold a licence, you need a **Biennial Flight Review (BFR) every two years**. During a BFR, the instructor reviews your current knowledge and proficiency, giving you a chance to maintain and improve your skills. **It's not a test where you have only one opportunity to pass** – if you're not up to scratch, you'll get the chance to practise until you are.\n\nA BFR is more than a box-ticking exercise – we want to keep you and others safe! How many flights it takes depends on the competency and currency of the licence holder. When did you last practise a forced landing? Or low flying? Real situations that need these manoeuvres can happen at any time, so they need to be practised regularly.\n\nManoeuvres in the BFR need to meet the standard of the applicable licence. The CAA's Vector magazine has a good article on BFRs for further reading.\n\n**Further reading:**\n\n- [CAA Vector: All about BFRs](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/all-about-bfrs/)\n- [CAA: Flight test standards guides](https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-test-standards-guides/)","category":"Procedures & SOPs","tags":["bfr","flight-review","proficiency","forced-landing","licence"],"links":[{"label":"CAA Vector: All about BFRs","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/all-about-bfrs/"},{"label":"CAA: Flight test standards guides","url":"https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-test-standards-guides/"}],"published_date":"2025-12-05","sent_at":"2025-12-05T02:08:44+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 5th December 2025","original_title":null,"original_body":"BIENNIAL FLIGHT REVIEW (BFR)\n\nA Biennial Flight Review (BFR) is a flight review every two years, once you obtain your license. During a BFR, the instructor reviews your current level of knowledge and proficiency, giving you a chance to maintain and improve your skills. It is not a test where you have only one opportunity to pass. If you're not up to scratch, you'll get a chance to practice until you are.\n\nThe BFR is more than just a box-ticking exercise - we want to keep you and others safe! How many flights a BFR takes depends on the competency and currency of the license holder. When did you last practice a forced landing? Or low flying? Real-life situations that require these maneuvers can happen at any time - they need to be practiced regularly.\n\nManouvers in the BFR need to meet the standard of the applicable licence. There is a really good article in Vector for some further reading.","editor_notes":"Repost of the BFR section of #6. Spelling (licence, practise, manoeuvres); replaced 'really good article in Vector' with verified link."},{"id":78,"slug":"file-a-vfr-flight-plan-beyond-25-nm","title":"File a VFR Flight Plan Beyond 25 NM","summary":"Club pilots must file a VFR flight plan when flying more than 25 NM from the departure aerodrome, keep it updated, and terminate it promptly after landing.","body_markdown":"VFR flight plans and SARTIMEs are an essential part of safe club flying, especially as members head further from home base.\n\nThe **legal requirement** applies when you're seeking an alerting service or operating **more than 50 NM offshore** – but **our club expects pilots to file a VFR flight plan whenever flying more than 25 NM from the departure aerodrome**.\n\nFiling a plan gives Airways and RCCNZ the information they need to respond quickly if something goes wrong, and setting a sensible SARTIME means someone is watching for your safe arrival.\n\nClub pilots are responsible for:\n\n- filing **realistic routes and timings**\n- **updating Airways** if plans change\n- most importantly, **terminating the flight plan or SARTIME promptly after landing** to avoid unnecessary search and rescue action.\n\n**Further reading:**\n\n- [Airways IFIS – NOTAMs and flight plans](https://www.ifis.airways.co.nz/)\n- [CAA Vector: Amending SARTIME, terminating flight plans (PDF)](https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-4-amending-sartime-terminating-flight-plans.pdf)","category":"Procedures & SOPs","tags":["flight-plan","sartime","sop","rccnz","airways"],"links":[{"label":"Airways IFIS – NOTAMs and flight plans","url":"https://www.ifis.airways.co.nz/"},{"label":"CAA Vector: Amending SARTIME, terminating flight plans (PDF)","url":"https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-4-amending-sartime-terminating-flight-plans.pdf"}],"published_date":"2025-12-12","sent_at":"2025-12-12T02:48:28+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 12th December 2025","original_title":null,"original_body":"VFR Flight Plans\n\nVFR flight plans and SARTIMEs are an essential part of safe club flying, especially as more members head further from home base.\n\nWhile the legal requirement applies when seeking an alerting service or operating more than 50 NM offshore, our club expects pilots to file a VFR plan whenever flying more than 25 NM from the departure aerodrome.\n\nFiling a plan provides Airways and RCCNZ with the information they need to respond quickly if something goes wrong, and setting a sensible SARTIME ensures someone is watching your safe arrival.\n\nClub pilots are responsible for filing realistic routes and timings, updating Airways if plans change, and most importantly, terminating their VFR flight plan or SARTIME promptly after landing to avoid unnecessary SAR action.","editor_notes":"Light copy edit; list of pilot responsibilities."},{"id":79,"slug":"fod-in-the-cockpit-can-jam-the-controls","title":"FOD in the Cockpit Can Jam the Controls","summary":"A loose item in the cockpit once jammed the flight controls after take-off, forcing a MAYDAY – account for your belongings and check the interior properly.","body_markdown":"Thoroughly pre-flighting the cockpit really matters – and a real-world example shows why.\n\nA good pre-flight isn't just about finding defects. It's also about **accounting for your own belongings** and properly checking the aircraft interior.\n\nIn a 2025 incident, **a loose item in the cockpit jammed the flight controls shortly after take-off**, forcing the pilot to declare a MAYDAY and carry out a challenging landing. Read the full story in the CAA Vector article *FOD in the cockpit*.\n\n**Further reading:**\n\n- [CAA Vector: FOD in the cockpit](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/)","category":"Airmanship","tags":["fod","loose-items","preflight","cockpit","flight-controls"],"links":[{"label":"CAA Vector: FOD in the cockpit","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/"}],"published_date":"2025-12-19","sent_at":"2025-12-19T06:18:43+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer 19th December 2025","original_title":null,"original_body":"FOD in the Cockpit\n\nWe’ve shared a few safety messages this year about thoroughly preflighting the cockpit, and this is a real-world example of why it matters.\n\nAfter last week’s preflight competition, we know most of you are doing a great job, but it is not just about finding defects. It is also about accounting for your own belongings and properly checking the aircraft interior.\n\nIn a 2025 incident, a loose item in the cockpit jammed the flight controls shortly after takeoff, forcing the pilot to declare a MAYDAY and carry out a challenging landing. Click the button below to read the full Vector article.","editor_notes":"Removed 'We've shared a few safety messages this year' and 'After last week's preflight competition'; replaced 'Click the button below' with a verified link."},{"id":80,"slug":"update-your-flight-plan-when-you-divert","title":"Update Your Flight Plan When You Divert","summary":"If you divert, amend your flight plan via phone, FISCOM or ATS when practicable – otherwise RCCNZ will search your original route if your SARTIME expires.","body_markdown":"We've all been there. You've done your pre-flight, the weather looks great, and you have a destination in mind where a hot coffee is calling your name. But as any experienced pilot will tell you, the sky doesn't care about your plans.\n\nIf you divert – whether due to weather, a NOTAM or an aircraft issue – it's extremely important to **amend your IFIS flight plan with your new route** when practicable, by phone, via FISCOM or through a local ATS unit.\n\nIf your SARTIME goes overdue, **RCCNZ will begin searching along your original flight plan route** – potentially leaving you stuck in a field for much longer than necessary!\n\nRemember the three rules:\n\n1. **Aviate** – fly the aircraft first.\n2. **Navigate** – develop a diversion plan.\n3. **Communicate** – notify ATS or FISCOM of your flight plan change.\n\nA diversion isn't a failure – it's a decision. Just make sure you let RCCNZ in on the secret!\n\n**Further reading:**\n\n- [Airways IFIS – NOTAMs and flight plans](https://www.ifis.airways.co.nz/)\n- [CAA Vector: Amending SARTIME, terminating flight plans (PDF)](https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-4-amending-sartime-terminating-flight-plans.pdf)","category":"Procedures & SOPs","tags":["diversion","flight-plan","sartime","rccnz","fiscom"],"links":[{"label":"Airways IFIS – NOTAMs and flight plans","url":"https://www.ifis.airways.co.nz/"},{"label":"CAA Vector: Amending SARTIME, terminating flight plans (PDF)","url":"https://www.aviation.govt.nz/assets/publications/vector/vector-article-archive/2017/vector-article-2017-4-amending-sartime-terminating-flight-plans.pdf"}],"published_date":"2025-12-26","sent_at":"2025-12-26T09:00:57+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 26th December 2025","original_title":null,"original_body":"The Diversion\n\nWe’ve all been there. You’ve done your pre-flight, the weather looks great, and you have a destination in mind where a hot coffee is calling your name. But as any experienced pilot will tell you, the sky doesn't care about your plans.\n\nIn the event of a diversion due to weather, NOTAM or even aircraft reasons it is extremely important to when practicable ammend your IFIS flight plan with your new diversion route either via phone, FISCOM or a local ATS.\n\nIf your SARTIME went overdue, RCCNZ will begin their search on the orginal flight plan route pottenitally leaving one stuck in a field for much longer than required!\n\nRemeber the 3 rules:\n\nAviate: Fly the plane first.\n\nNavigate: Develop a Diversion plan.\n\nCommunicate: Notify ATS or FISCOM of your flight plan change.\n\nA diversion isn't a failure—it’s a decision. Just make sure you bring the RCCNZ in on the secret!","editor_notes":"Kept the spirit of the original title 'The Diversion'; fixed multiple typos (ammend, orginal, pottenitally, Remeber)."},{"id":81,"slug":"a-flight-plan-is-your-safety-net","title":"A Flight Plan Is Your Safety Net","summary":"Under club SOPs any flight beyond 25 NM needs a VFR flight plan – it makes sure someone knows where you are and can raise the alarm if needed.","body_markdown":"A VFR flight plan isn't just paperwork – it's a key safety tool that makes sure someone knows where you're going and when you're due back, and can raise the alarm if things don't go as planned.\n\nUnder Kāpiti Aero Club SOPs, **any flight beyond 25 NM requires a flight plan to be submitted**. This applies to all members and instructors.\n\nEven on good-weather days, unexpected delays, weather changes or diversions can happen – and having a flight plan in place provides an essential safety net.\n\n**Further reading:**\n\n- [Airways IFIS – NOTAMs and flight plans](https://www.ifis.airways.co.nz/)","category":"Procedures & SOPs","tags":["flight-plan","sop","cross-country","safety-net"],"links":[{"label":"Airways IFIS – NOTAMs and flight plans","url":"https://www.ifis.airways.co.nz/"}],"published_date":"2026-01-02","sent_at":"2026-01-02T05:31:36+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 2nd January 2026","original_title":null,"original_body":"VFR Flight Plans\n\nAs we head into another busy flying period, this is a reminder of the importance of filing a VFR Flight Plan. A flight plan isn’t just paperwork, it’s a key safety tool that helps ensure someone knows where you’re going, when you’re due back, and can raise the alarm if things don’t go as planned.\n\nPlease remember that under Kapiti Aeroclub SOPs, any flight beyond 25 NM requires a Flight Plan to be submitted . This applies to all members and Instructors.\n\nEven on good-weather days, unexpected delays, weather changes, or diversions can happen, and having a flight plan in place provides an essential safety net.","editor_notes":"Removed 'As we head into another busy flying period'."},{"id":82,"slug":"bird-strike-prevention-and-reporting","title":"Bird Strike Prevention and Reporting","summary":"Assess bird hazards before every flight, ask Flight Service to use the bird-scaring cannons, and report any strike or near miss on MIFIS with full details.","body_markdown":"As a coastal aerodrome, we naturally experience more bird activity than many inland fields.\n\nBefore every flight, **assess the bird hazard and actively manage it**. If you see birds before lining up, **advise Flight Service** – they can deploy the bird-scaring cannons located at each runway threshold.\n\nIt's easy to get caught up in the excitement of a flight you've been looking forward to all week, but eagerness should never override good threat and error management.\n\nEven when every precaution is taken, bird strikes or near misses can still occur. **These must be reported via MIFIS.** Reports should include:\n\n- species (if known)\n- number of birds\n- location (e.g. abeam A3)\n- whether evasive action was required\n\nIn the warmer months, new growth of grass and greenery brings increased wildlife activity, so be aware of the habits and behaviours of the local birds.\n\n**Further reading:**\n\n- [CAA GAP booklet: Bird hazards (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/Bird_Hazards.pdf)\n- [CAA: Reporting bird incidents](https://www.aviation.govt.nz/safety/notify-us/reporting-bird-incidents/)","category":"Aerodrome & Circuit","tags":["birds","birdstrike","mifis","flight-service","reporting"],"links":[{"label":"CAA GAP booklet: Bird hazards (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/Bird_Hazards.pdf"},{"label":"CAA: Reporting bird incidents","url":"https://www.aviation.govt.nz/safety/notify-us/reporting-bird-incidents/"}],"published_date":"2026-01-09","sent_at":"2026-01-09T04:17:45+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 9th January 2026","original_title":null,"original_body":"Bird Hazard Reminder\n\nAs a coastal aerodrome we naturally experience higher bird activity than many inland fields.\n\nBefore every flight, take time to assess the bird hazard and actively manage it. If birds are observed before lining up, advise Flight Service - they can deploy the bird-scaring cannons located at each runway threshold.\n\nIt’s easy to get caught up in the excitement of a flight you’ve been looking forward to all week, but eagerness should never override good threat and error management.\n\nEven when all precautions are taken, bird strikes or near-misses can still occur. These must be reported via MIFIS. Reports should include:\n\nSpecies (if known)\n\nNumber of birds\n\nLocation (e.g. abeam A3)\n\nWhether evasive action was required\n\nAs we head into the warmer months, it is important for us to remember that with the new growth of grass and greenery, comes the additional risk of increased wildlife activity. We need to be aware of the habits and behaviours of the local birds.","editor_notes":"Shortened repost of #23. Replaced 'As we head into the warmer months' with 'In the warmer months'; list formatting."},{"id":83,"slug":"carb-icing-can-happen-all-year-round","title":"Carb Icing Can Happen All Year Round","summary":"Carb icing can happen in any season from -10°C to +25°C and is most likely at 10–15°C with humidity above 40%; use carb heat below the green arc.","body_markdown":"Warmer weather can make it easy to overlook the risk of carburettor icing, but **it can occur at any time of year**. Carb icing develops when ice forms inside the carburettor, restricting airflow. This leads to an excessively rich mixture entering the cylinders, which can cause engine roughness and a reduction in power.\n\nIcing is possible in a wide range of conditions – from as cold as **-10°C to as warm as +25°C**.\n\n**Typical signs:** rough running and a noticeable drop in RPM. The correct response is to **apply carburettor heat**, which diverts warm air from around the exhaust system into the carburettor. As the ice melts, engine performance may briefly deteriorate as moisture passes through the engine.\n\n### Reducing the risk\n\n- Use **carb heat when operating outside the green arc** (e.g. below 1900 RPM in a C152).\n- **Check carb heat during the run-up.**\n- **Regularly check for icing during SCADIE checks.**\n\nCarb icing is most common between **10°C and 15°C** when relative humidity **exceeds 40 percent**.\n\n**Further reading:**\n\n- [CAA Vector: Icing](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/)\n- [CAA safety message: Check the carb icing graph](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/)","category":"Aircraft & Engine","tags":["carb-icing","carb-heat","scadie","c152","summer"],"links":[{"label":"CAA Vector: Icing","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/"},{"label":"CAA safety message: Check the carb icing graph","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/"}],"published_date":"2026-01-16","sent_at":"2026-01-16T03:48:33+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 16th January 2026","original_title":null,"original_body":"Icing - not just a winter problem...\n\nWarmer weather can make it easy to overlook the risk of carburettor icing, but it can occur at any time of year. Carb icing develops when ice forms inside the carburettor, restricting airflow. This leads to an excessively rich fuel mixture entering the cylinders, which can cause engine roughness and a reduction in power.\n\nIcing is possible in a wide range of conditions, from as cold as -10°C to as warm as +25°C.\n\nTypical indications include rough running and a noticeable drop in RPM. The correct response is to apply carburettor heat, which diverts warm air from around the exhaust system into the carburettor. As the ice melts, engine performance may briefly deteriorate as moisture passes through the engine.\n\nTo reduce the risk, pilots should remain alert to icing conditions and use preventative techniques. These include applying carb heat when operating outside the green arc, such as below 1900 RPM in a C152, checking carb heat during run-up, and regularly assessing for icing during SCADIE checks. Carb icing is most common in temperatures between 10°C and 15°C when relative humidity exceeds 40 percent.","editor_notes":"Reworded repost of #28; title based on original heading 'Icing - not just a winter problem...'; list formatting."},{"id":84,"slug":"check-events-and-hot-spots-before-summer-trips","title":"Check Events and Hot Spots Before Summer Trips","summary":"Before summer cross-countries, check AIP Supplements for air events, NOTAMs on the day and the CAA's Summer traffic busy spots page.","body_markdown":"Planning a cross-country in summer? Expect more aircraft in the sky, thanks to better weather and increased traffic over the holiday period.\n\nDon't inadvertently fly into an aviation event:\n\n- Check **AIP Supplements** for planned events.\n- Check **NOTAMs** on the day.\n\nEach summer the CAA also publishes a *Summer traffic busy spots* page on Vector Online, showing traffic hot spots and major flying events for the season – well worth a look before you head away.\n\n**Further reading:**\n\n- [CAA Vector: Summer traffic busy spots](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/summer-traffic-busy-spots/)\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [Airways IFIS – NOTAMs and flight plans](https://www.ifis.airways.co.nz/)","category":"Airspace & Radio","tags":["cross-country","summer","air-events","notams","aip-supplements"],"links":[{"label":"CAA Vector: Summer traffic busy spots","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/summer-traffic-busy-spots/"},{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"Airways IFIS – NOTAMs and flight plans","url":"https://www.ifis.airways.co.nz/"}],"published_date":"2026-01-23","sent_at":"2026-01-23T02:45:56+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 23rd January 2026","original_title":null,"original_body":"Planning on going on a Cross-Country this summer? Be prepared for there to be more aircraft in the skies due to nice weather (eventually...) and increased traffic during the holiday period.\n\nDon’t inadvertently fly into an aviation event – check AIP Supplements for planned events, and check NOTAMs on the day.\n\nAlso be sure to check out this page produced by the CAA which shows Summer traffic busy hot spots and major flying events, between mid-December 2025 and March 2026.","editor_notes":"Near-identical repost of #25. Removed '(eventually...)' aside and specific season dates (mid-December 2025 to March 2026)."},{"id":85,"slug":"keep-the-dipstick-in-your-hand-or-the-aircraft","title":"Keep the Dipstick in Your Hand or the Aircraft","summary":"When refuelling, the dipstick should only ever be in your hand or back in the aircraft – never on a wing, cowling or fuel trailer.","body_markdown":"Dipsticks are sometimes left behind at other aerodromes, or placed on top of wings, cowlings or fuel trailers – only to be forgotten or to fall off once the aircraft moves.\n\nDipsticks are essential equipment, and we need them back with the aircraft every time. When refuelling, **the dipstick should only ever be in one of two places: in your hand, or back in the aircraft**. Leaving it on a fuel trailer or aircraft surface makes it very easy to miss, especially when things get busy.\n\nThanks for keeping this in mind next time you're refuelling.\n\n**Further reading:**\n\n- [CAA Vector: Dip 'n check](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dip-n-check/)","category":"Ground Ops","tags":["dipstick","refuelling","fuel","fod","away-landings"],"links":[{"label":"CAA Vector: Dip 'n check","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dip-n-check/"}],"published_date":"2026-01-30","sent_at":"2026-01-30T00:03:23+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 30th January 2026","original_title":null,"original_body":"Aircraft Refuelling\n\nWe’ve had a few recent instances of dipsticks being left behind at other aerodromes, or placed on top of wings, cowlings, or fuel trailers - only to be forgotten or fall off once the aircraft moves.\n\nDipsticks are essential equipment and we need them back with the aircraft every time. When refuelling, the dipstick should only ever be in one of two places: in your hand, or back in the aircraft . Leaving them on fuel trailers or aircraft surfaces makes them very easy to miss, especially when things get busy.\n\nThanks for keeping this in mind next time you’re refuelling.","editor_notes":"Reworded 'We've had a few recent instances' as timeless."},{"id":86,"slug":"standard-overhead-join","title":"Standard Overhead Join","summary":"Where an aerodrome has both left- and right-hand circuits, always enter the overhead with the aerodrome on your left, then reposition clear of the overhead for a right-hand circuit.","body_markdown":"Most pilots carry out overhead joins correctly and safely. However, incorrect overhead joins do get reported – and while some involve visiting aircraft, several close calls have occurred where incorrect joining procedures created the potential for conflict. Here's a clarification of the correct technique.\n\nAt aerodromes that operate both left-hand and right-hand circuits, such as Foxpine and Omaka, the overhead join requires aircraft to approach and enter the overhead with **the aerodrome and runways kept on the left-hand side**.\n\nOnce established overhead, you have several options:\n\n- orbiting overhead (left-hand only)\n- joining the circuit\n- vacating the area if required\n\nThe standard overhead join is designed to **maximise wings-level time** in the overhead and in the circuit, allowing an effective lookout and better situational awareness.\n\n### Why it matters\n\nA conflict can arise if one aircraft enters the overhead correctly with the aerodrome on its left, while another enters overhead intending to join a right-hand circuit with the aerodrome on its right. The two aircraft may be on converging tracks with limited ability to see each other – a serious collision risk.\n\n### In summary\n\n- If an aerodrome has both left- and right-hand circuits, **always enter the overhead with the aerodrome and runways on the left**.\n- If a right-hand circuit is in use, **fly clear of the overhead before repositioning** to join the right-hand circuit.\n- Continue to descend on the non-traffic side, make the same radio calls, and fly the same overall joining pattern.\n\nIf you're unsure about the procedure, have any questions or would like a refresher, have a chat with an instructor before departing. A short revision flight is also a great way to rebuild confidence and make sure your procedures are current.\n\nDetailed guidance on the standard overhead join can be found in AIP New Zealand (AD 1.6).\n\n**Further reading:**\n\n- [CAA: Standard overhead join](https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/fixed-wing-flight-training-safety-strategy/standard-overhead-join/)\n- [CAA poster: Standard overhead join (PDF)](https://www.aviation.govt.nz/assets/publications/posters/standard-overhead-join.pdf)\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Aerodrome & Circuit","tags":["overhead-join","sohj","circuit","collision-avoidance","foxpine","omaka"],"links":[{"label":"CAA: Standard overhead join","url":"https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/fixed-wing-flight-training-safety-strategy/standard-overhead-join/"},{"label":"CAA poster: Standard overhead join (PDF)","url":"https://www.aviation.govt.nz/assets/publications/posters/standard-overhead-join.pdf"},{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2026-02-06","sent_at":"2026-02-06T01:37:21+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 6th February 2026","original_title":"Standard Overhead Join","original_body":"Most pilots carry out overhead joins correctly and safely. However, we’ve recently seen an increase in reports of aircraft joining overhead incorrectly.\n\nWhile some of these reports involve visiting aircraft, we have recorded several close-call incidents where incorrect joining procedures created a potential for conflict. For this reason, we’d like to take the opportunity to clarify the correct overhead join technique.\n\nAt aerodromes that operate both left-hand and right-hand circuits like Foxpine and Omaka, the overhead join procedure requires aircraft to approach and enter the overhead with the aerodrome and runways kept on the left-hand side .\n\nOnce established overhead, pilots have several options available:\n\nOrbiting overhead (left-hand only)\n\nJoining the circuit\n\nVacating the area if required\n\nThe standard overhead join is designed to maximise wings-level time both in the overhead and in the circuit, allowing for an effective lookout and improved situational awareness.\n\nAs shown in the example below, a conflict can arise if ( Aircraft 1 ) enters the overhead correctly with the aerodrome on the left, while another ( Aircraft 2 ) enters overhead intending to join a right-hand circuit while keeping the aerodrome on the right. In this scenario, aircraft may be on converging tracks with limited ability to see each other, creating a serious collision risk.\n\nTo summarise:\n\nIf an aerodrome has both left- and right-hand circuits, always enter the overhead with the aerodrome and runways on the left .\n\nIf a right-hand circuit is in use, fly clear of the overhead before repositioning to join the right-hand circuit, as shown in Diagram 1.\n\nContinue to descend on the non-traffic side, make the same radio calls, and fly the same overall joining pattern.\n\nIf you’re unsure about the procedure, have any questions, or would like a refresher, we strongly encourage you to have a chat with an instructor before departing. A short revision flight can also be a great way to rebuild confidence and ensure your procedures are current.\n\nFor further reference, detailed guidance on the standard overhead join can be found in the AIP HERE under AD 1.6 .","editor_notes":"Kept original title. Removed diagram references ('As shown in the example below', 'as shown in Diagram 1') and described the conflict in words; reworded 'we've recently seen an increase in reports' as timeless."},{"id":87,"slug":"keeping-wheel-spats-clean","title":"Keeping Wheel Spats Clean","summary":"Clean wheel spats make oil and fuel leaks obvious – clean dirty spats with the green-handled spray bottles in the hangar, especially on ZK-KAZ and ZK-KAL.","body_markdown":"Keeping our aircraft wheel spats clean – **especially the nose wheel spat** – is an important part of maintaining aircraft safety.\n\nA clean spat makes a fluid leak immediately obvious. Engine oil often shows up on the nose wheel spat and can be spotted during a pre-flight inspection. If the spat is already dirty or heavily stained, it's very hard to tell old grime from a fresh leak, and a developing issue can go unnoticed.\n\nIf you notice a dirty wheel spat, please clean it with one of the provided spray bottles and a rag. The spray bottles have a **green handle** and are kept next to the engine oil inside the hangar. If you haven't used them before, ask an instructor to show you how.\n\nThis is particularly important on **ZK-KAZ and ZK-KAL**, where fuel can sometimes find its way onto the spats due to over-priming – so cleaning these may occasionally become a daily task. Thanks for helping keep the fleet clean and in a condition where any issues can be identified early.","category":"Aircraft & Engine","tags":["wheel-spats","leaks","preflight","cleaning","oil"],"links":[],"published_date":"2026-02-12","sent_at":"2026-02-12T23:47:25+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 13th February 2026","original_title":"Keeping Wheel Spats Clean","original_body":"Keeping our aircraft wheel spats clean, especially the nose wheel spat , is an important part of maintaining aircraft safety.\n\nA clean spat makes it immediately obvious if there is a fluid leak. Oil from the engine will often show up on the nose wheel spat and can be detected during a preflight inspection . If the spat is already dirty or heavily stained, it becomes very difficult to tell whether a mark is old grime or a fresh leak. Any delay in noticing this can allow a developing issue to go unnoticed.\n\nIf you notice a wheel spat is dirty, please use one of the provided spray bottles and a rag to clean it. The spray bottles are located next to where the engine oil is kept inside the hangar and have a green handle , as shown in the picture. If you have not used these before, please ask an instructor to show you how.\n\nThis is particularly important on ZK-KAZ and ZK-KAL , where fuel can sometimes find its way onto the spats due to over-priming. As a result, cleaning these may occasionally become a daily task. We appreciate everyone’s help in keeping the fleet clean and in a condition where any issues can be identified early.","editor_notes":"Kept original title; removed picture reference ('as shown in the picture')."},{"id":88,"slug":"engine-run-up-etiquette-on-taxiway-charlie","title":"Engine Run-Up Etiquette on Taxiway Charlie","summary":"Point prop wash at the grass during run-ups on Taxiway Charlie, take only half the taxiway, and use the Western apron if space is tight.","body_markdown":"When the engine is running, the propeller generates **prop wash** – air pushed behind the aircraft at high speed, especially at high power.\n\nWhen doing run-ups on **Taxiway Charlie**:\n\n- Point the prop wash **towards the grass**, away from taxiways and other aircraft.\n- Position the aircraft so you only occupy **one half of the taxiway**, leaving room for another aircraft to use the other side.\n\nAnything behind you can be affected by your prop wash, which can be extremely hazardous. If there isn't enough room to set up safely on Charlie, **use the Western apron**.\n\nRemember: as a pilot, you're legally responsible for your aircraft, your passengers and any hazard your aircraft poses to anyone else.","category":"Ground Ops","tags":["run-up","prop-wash","taxiway-charlie","nzpp","apron"],"links":[],"published_date":"2026-02-20","sent_at":"2026-02-20T04:25:50+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 20th February 2026","original_title":"Engine Run-Up Reminder","original_body":"When our engine is running, our propellers are spinning and generating prop wash which is air being pushed behind the aircraft at a great rate, especially during high power operations.\n\nMake sure when doing run-up checks on taxiway charlie that you are pointing the prop wash towards the grass, away from taxiways and aircraft. Position your aircraft so you are only occupying one-half of the taxiway to allow enough room for another aircraft to use the other side.\n\nAnything behind you can be affected by your prop wash, which can be extremely hazardous. If there is not enough room for you to set up safely on Charlie, please use the Western apron. Remember as a pilot you are legally responsible for your aircraft, your passengers and any hazard your aircraft poses to anyone else.","editor_notes":"Near-identical repost of #24; original title 'Engine Run-Up Reminder' made more specific."},{"id":89,"slug":"parallel-operations-what-counts-and-what-doesnt","title":"Parallel Operations: What Counts and What Doesn't","summary":"Parallel take-offs or landings are prohibited at NZPP, but backtracking on the sealed runway while another aircraft lands on the grass isn't a parallel operation.","body_markdown":"Before entering the runway strip, make sure you've completed a **thorough lookout and clearly broadcast your intentions**. The boundaries of the runway strip are shown on the aerodrome chart by dashed lines. If you manoeuvre into this area, you are legally on the runway and there is a risk of simultaneous operations.\n\nA **parallel operation** is when two parallel runways are being used for take-off and/or landing at the same time. **This is strictly prohibited at Paraparaumu.**\n\nIt does **not** include, for example, one aircraft backtracking on the sealed runway while another aircraft lands on the grass runway. In that case, the aircraft on the sealed surface is using it as a taxiway only and isn't taking off or landing. Even so, clear communication, accurate position reports and good spacing remain essential in all cases.\n\nWhen preparing to line up, assess spacing carefully. A good rule of thumb is to **wait until the preceding aircraft is at least a full runway length away**. If the aircraft ahead is using the grass runway, allow even more space, as it will turn crosswind through your upwind path shortly after take-off.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)","category":"Aerodrome & Circuit","tags":["parallel-operations","runway-strip","backtracking","spacing","grass-runway"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"}],"published_date":"2026-02-27","sent_at":"2026-02-27T04:23:03+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 27th February 2026","original_title":"Runway & Parallel Ops","original_body":"Ensure you’ve completed a thorough lookout and have clearly broadcast your intentions before entering the runway strip. The boundaries of the runway strip are depicted on the aerodrome plate using dashed lines. If you manoeuvre into this area, you are legally on the runway and there is a risk of simultaneous operations occurring.\n\nA parallel operation is where two parallel runways are being used for take-off and/or landing at the same time. This is strictly prohibited at Paraparaumu.\n\nIt is important to note that this does not include a situation where, for example, one aircraft is backtracking on the sealed runway while another aircraft is landing on the grass runway. In that case, the aircraft on the sealed surface is using it as a taxiway only and is not engaged in a take-off or landing operation. However, clear communication, accurate position reports, and good spacing remain essential in all cases.\n\nWhen preparing to line up, assess spacing carefully. A good rule of thumb is to wait until the preceding aircraft is at least a full runway length away. If an aircraft ahead is using the grass runway, allow even more space, as they will turn crosswind through your upwind path shortly after take-off.","editor_notes":"Original title 'Runway & Parallel Ops' made more specific; light copy edit."},{"id":90,"slug":"use-the-sun-visor-to-manage-glare","title":"Use the Sun Visor to Manage Glare","summary":"Glare can be a problem even on dull days – use the sun visor, especially flying into a low sun, and put the sunshade up when you pack the aircraft away.","body_markdown":"Even when the sun isn't blazing, **glare in the cockpit can still be an issue**. Use the sun visor to keep the sun out of your eyes, especially when flying towards the sun in the morning or evening.\n\nWhen you pack the aircraft away, remember to **put the sunshade up on the dash** so the cockpit doesn't turn into a sauna for the next pilot. If the aircraft you're flying doesn't have one, let an instructor know.","category":"Human Factors","tags":["glare","sun-visor","sunshade","cockpit"],"links":[],"published_date":"2026-03-06","sent_at":"2026-03-06T03:00:31+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 6th March 2026","original_title":"Aircraft Sun Visors","original_body":"This summer might have felt a bit underwhelming, but even when the sun isn’t blazing, glare in the cockpit can still be an issue . Make sure you’re using the sun visor to keep the sun out of your eyes, especially when flying toward the sun in the morning or evening.\n\nAnd when you pack the aircraft away, please remember to put the sunshade up on the dash so the cockpit doesn’t turn into a sauna for the next pilot. If the plane you’re flying doesn’t have one, then please let an instructor know.","editor_notes":"Original title 'Aircraft Sun Visors' made more specific; removed 'This summer might have felt a bit underwhelming'."},{"id":91,"slug":"checklist-discipline-consistent-unhurried-verified","title":"Checklist Discipline: Consistent, Unhurried, Verified","summary":"Use the checklist every flight without rushing, visually verify each control, and let the engine warm until oil temperature is in the green before run-ups.","body_markdown":"Checklists keep our procedures consistent, minimise human error and make sure important steps aren't overlooked.\n\nAs pilots, it's easy to feel eager to get airborne. But moving too quickly through pre-flight tasks can result in checklist items being skipped or only partly completed.\n\nIn the colder months, it's even more important to let the engine **warm up properly before applying significant power**. **Always confirm the oil temperature is in the green range before beginning run-ups** as part of your checklist. If that means waiting five to ten minutes, that's completely acceptable and helps avoid unnecessary stress on the engine.\n\nUseful reminders when using checklists:\n\n- **Be consistent** – use the checklist on every flight without exception.\n- **Take your time** – rushing increases the chance of missing something important.\n- **Verify visually** – when selecting or adjusting a control, look directly at it and confirm it's the correct one.","category":"Procedures & SOPs","tags":["checklist","warm-up","oil-temperature","run-up"],"links":[],"published_date":"2026-03-13","sent_at":"2026-03-13T04:55:46+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 13th March 2026","original_title":"Checklist Reminder","original_body":"Checklists are there to keep our procedures consistent, minimise human error, and ensure that important steps are not overlooked.\n\nAs pilots, it is easy to feel eager to get airborne. However, moving too quickly through pre-flight tasks can result in checklist items being skipped or only partially completed.\n\nWith the colder winter months arriving soon, it becomes even more important to allow the engine to warm up properly before applying significant power. Always confirm that the oil temperature is in the green range before beginning run-ups as part of your checklist.\n\nIf this means waiting five to ten minutes, that is completely acceptable and helps avoid unnecessary stress on the engine.\n\nA few useful reminders when using checklists:\n\n• Be consistent – Use the checklist on every flight without exception. • Take your time – Rushing increases the chance of missing something important. • Verify visually – When selecting or adjusting a control, look directly at it and confirm that it is the correct one.","editor_notes":"Reworded repost of #51; original title 'Checklist Reminder' made more specific; replaced 'With the colder winter months arriving soon' with 'In the colder months'."},{"id":92,"slug":"meteorological-minimums-for-vfr-flight","title":"Meteorological Minimums for VFR Flight","summary":"Always fly within both the legal and the club's higher VFR met minimums, and before Cook Strait crossings ask whether you can see the other side and have an exit plan.","body_markdown":"When flying VFR in New Zealand, sticking to meteorological minimums is crucial for safe flight. The minimums are outlined in your flight manuals, which are a reliable reference if you're ever unsure.\n\n**Our aero club has its own meteorological minimums, set above the legal requirements**, to give all pilots an extra margin of safety. Always stick to these minimums.\n\nOn any cross-country, or when crossing Cook Strait, pay close attention to the conditions and ask yourself:\n\n- Can you see the other side?\n- How low is the cloud?\n- What's your exit plan if conditions change?\n\nIf you can't meet the minimums, reassess your plans and consider alternatives. Always fly within **both the legal and the club's meteorological minimums**, and never hesitate to check your flight manual for specific guidance.\n\n**Further reading:**\n\n- [CAA GAP booklet: VFR MET (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/vfr-met-web.pdf)\n- [Civil Aviation Rules Part 91: General Operating and Flight Rules](https://www.aviation.govt.nz/rules/rule-part/part-91/)","category":"Weather","tags":["vfr","met-minima","weather","cook-strait","club-minimums"],"links":[{"label":"CAA GAP booklet: VFR MET (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/vfr-met-web.pdf"},{"label":"Civil Aviation Rules Part 91: General Operating and Flight Rules","url":"https://www.aviation.govt.nz/rules/rule-part/part-91/"}],"published_date":"2026-03-20","sent_at":"2026-03-20T04:34:19+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 20th March 2026","original_title":"Meteorological Minimums for VFR Flight","original_body":"When flying VFR (Visual Flight Rules) in New Zealand, adhering to meteorological minimums is crucial for safe flight. These minimums are outlined in your flight manuals, and should you ever be unsure, they are a reliable reference.\n\nIt’s important to note that our aeroclub has established its own meteorological minimums, which are set above the legal requirements. These club-specific minimums are in place to ensure an extra margin of safety for all pilots. Please make sure to always adhere to these minimums during your flights.\n\nWhen on any cross country or when crossing the Cook Strait, pay close attention to conditions and ask yourself:\n\nCan you see the other side?\n\nHow low is the cloud cover?\n\nWhat is your exit plan if conditions change?\n\nIf you are unable to meet these minimums, it's essential to reassess your flight plans and consider alternate options. Always ensure that you’re flying within both the legal and our aeroclub’s meteorological minimums to maintain safety. Never hesitate to refer to your flight manual for specific guidelines.","editor_notes":"Near-identical repost of #37; kept original title; body aligned with the edited #37."},{"id":93,"slug":"check-the-aircraft-documents-before-flight","title":"Check the Aircraft Documents Before Flight","summary":"A pre-flight covers exterior, interior and documents – confirm all required documents, including a complete flight manual, are on board before 'preflight completed'.","body_markdown":"Always begin every flight with a thorough pre-flight inspection. A good pre-flight covers three areas: **exterior, interior and documents**.\n\nFor documents, make sure **all legally required aircraft documentation is on board** before flight. This includes confirming the **flight manual is on board and complete**, with no missing pages.\n\nDocuments are sometimes removed from the aircraft for various reasons, so don't assume they're there. Remember that the first item in your pre-start checks is **\"preflight completed\"** – and that includes confirming all required documents are on board.","category":"Procedures & SOPs","tags":["preflight","documents","flight-manual","pre-start"],"links":[],"published_date":"2026-03-27","sent_at":"2026-03-27T00:23:02+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 27th March 2026","original_title":"Preflight: Documents","original_body":"A reminder to always begin every flight with a thorough preflight inspection. A good preflight consists of three areas:\n\nExterior. Interior. Documents.\n\nFor documents , ensure all legally required aircraft documentation is onboard before flight. This includes confirming that you have the flight manual and it is complete, and not missing any pages.\n\nEvery now and then, documents may be removed from the aircraft for various reasons, so it’s important not to assume they are there. As part of your pre-start checks, remember that the first item is “preflight completed” - this includes confirming that all required documents are onboard.","editor_notes":"Original title 'Preflight: Documents' expanded; light copy edit."},{"id":94,"slug":"dont-land-before-the-threshold","title":"Don't Land Before the Threshold","summary":"Cross the threshold at about 50 ft AGL and touch down beyond it, ideally near the aiming point markers – resist the urge to 'duck under' on final for RWY 16.","body_markdown":"Respect the runway threshold markings. **The threshold defines the start of the landing portion of the runway, and aircraft should not touch down before it.**\n\nAim to cross the threshold at approximately **50 ft AGL**, allowing a stable approach and proper use of the available landing distance. Landing before the threshold not only reduces safety margins but can also expose the aircraft to unprepared surfaces or obstacle hazards that a displaced threshold is specifically designed to protect against.\n\nThis is especially relevant on **Runway 16 at Paraparaumu**, where there can be a tendency to 'duck under' on final. Stay disciplined on your approach profile and make sure you touch down beyond the threshold markings – ideally around the **aiming point markers**.","category":"Aerodrome & Circuit","tags":["threshold","landing","runway-16","approach","nzpp"],"links":[],"published_date":"2026-04-03","sent_at":"2026-04-03T06:34:57+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 3rd April 2026","original_title":"Landing before the Threshold","original_body":"A reminder for all pilots about the importance of respecting runway threshold markings. The threshold defines the start of the landing portion of the runway, and aircraft should not be touching down prior to this point.\n\nWe should be crossing the threshold at approximately 50 feet AGL, allowing for a stable approach and proper use of the available landing distance. Landing before the threshold not only reduces safety margins but can also expose aircraft to unprepared surfaces or obstacle hazards that the displaced threshold is specifically designed to protect against.\n\nThis is especially relevant for Runway 16 at Paraparaumu, where there can be a tendency to “duck under” on final. It’s important to remain disciplined on approach profile and ensure touchdown occurs beyond the threshold markings, ideally around the aiming point markers.","editor_notes":"Original title 'Landing before the Threshold' reworded as an instruction; light copy edit."},{"id":95,"slug":"secure-pens-paper-and-checklists-before-flight","title":"Secure Pens, Paper and Checklists Before Flight","summary":"Loose pens, paper and checklists can shift in turbulence or an emergency – check the cockpit properly and secure anything that doesn't need to be loose.","body_markdown":"Loose items such as pens, paper and checklists are sometimes left unsecured in the aircraft and missed during the pre-flight.\n\nRemember, a full pre-flight has three parts: **the exterior, the interior and the documents**. Most people are thorough with the outside checks, but the interior is just as important. Loose items in the cockpit can shift in flight and become a hazard, especially in turbulence or an emergency.\n\nOn your next pre-flight, **do a proper check of the cockpit and secure anything that doesn't need to be loose**.\n\n**Further reading:**\n\n- [CAA Vector: FOD in the cockpit](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/)","category":"Airmanship","tags":["loose-items","interior-check","preflight","cockpit","turbulence"],"links":[{"label":"CAA Vector: FOD in the cockpit","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/fod-in-the-cockpit/"}],"published_date":"2026-04-10","sent_at":"2026-04-10T08:25:20+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 10th April 2026","original_title":"Loose items in the cockpit","original_body":"Lately, we've noticed a growing number of loose items... pens, paper, checklists being left unsecured in aircraft. These have often been missed during the preflight.\n\nRemember, a full preflight consists of three parts: the exterior, the interior, and the documents. While most people are thorough with the outside checks, the interior is just as important. Loose items in the cockpit can shift during flight and become a hazard, especially during turbulence or an emergency.\n\nNext time you're doing a preflight, please make sure you do a proper check of the cockpit and secure anything that doesn’t need to be loose.","editor_notes":"Original title 'Loose items in the cockpit' made more specific; reworded 'Lately, we've noticed a growing number' as timeless."},{"id":96,"slug":"be-on-the-ground-30-minutes-before-ect","title":"Be on the Ground 30 Minutes Before ECT","summary":"When days are shorter the 1700 booking slot sits close to ECT – plan a buffer and land 30 minutes before ECT unless you're night-current.","body_markdown":"When the days get shorter, the final booking slot (ending at **1700**) is much closer to ECT – especially worth keeping in mind when planning cross-country flights.\n\nIt's good practice to build an appropriate buffer before ECT or curfew, whichever is more restrictive. Things always take longer than expected in aviation.\n\nAs a reminder, our SOPs require you to be **on the ground 30 minutes before ECT unless you are night-current**.\n\nIf you're unsure, have a chat with one of the instructors before your next cross-country flight.","category":"Procedures & SOPs","tags":["ect","cross-country","booking","sop","night-currency"],"links":[],"published_date":"2026-04-17","sent_at":"2026-04-17T03:26:58+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 17th April 2026","original_title":"ECT Reminder","original_body":"With the days getting shorter, the final booking slot ending at 1700, is now much closer to ECT. This is especially worth keeping in mind when planning cross-country flights.\n\nIt's good practice to build an appropriate buffer before ECT or curfew, whichever is more restrictive. Things always take longer than expected in aviation.\n\nAs a reminder, our SOPs require you to be on the ground 30 minutes before ECT unless you are night-current.\n\nIf you're unsure, have a chat with one of the instructors before your next cross-country flight.","editor_notes":"Repost of #47; original title 'ECT Reminder' made more specific; replaced 'With the days getting shorter' with 'When the days get shorter'."},{"id":97,"slug":"securing-aircraft-on-the-ground","title":"Securing Aircraft on the Ground","summary":"Secure parked aircraft against wind: hangar first, then fixed tie-downs, otherwise a crossover picket kit with ropes led outboard and forward.","body_markdown":"Every year aircraft are needlessly damaged by wind gusts because of inattention to forecasts, negligence or inadequate tie-downs. Before the windier months – and whenever strong winds are forecast – it pays to brush up on picketing techniques and other precautions against wind damage to parked aircraft.\n\nIdeally, secure the aircraft in a storm-proof hangar or other suitable shelter. If hangarage isn't available, the remaining option is to tie the aircraft down securely in a suitable location. Many New Zealand aerodromes have only a limited number of fixed tie-down points, and these may be reserved for local aircraft. If a fixed tie-down isn't available, find a sheltered spot to park.\n\n### Carry a picket kit\n\nThis may mean using your own pickets. It's a good idea to carry a set in case you're stuck at a remote aerodrome with no other way to secure the aircraft. A picket set should include:\n\n- six steel stakes\n- three crossover tubes\n- three ropes of appropriate length\n- a mallet or hammer\n\nall stowed in a bag. **Include the pickets in your weight and balance calculations**, and stow them securely so they don't become a problem in turbulence.\n\n### Choosing where and how to picket\n\n- Pickets can pull out under strain if the ground is soft or becomes wet.\n- Coiled pickets are difficult to get into stony ground and more likely to pull out of soft ground.\n- **Crossover pickets are the most suitable**, as they're more likely to stay put even if the ground gets wet.\n- Lead the underwing ropes to points **outboard and forward** of the underwing attachment points.\n- Hammer pickets all the way into the ground, **always in front of the wing**.\n\nFor more detail, see the CAA's Secure your aircraft GAP booklet.\n\n**Further reading:**\n\n- [CAA GAP booklet: Secure your aircraft (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/secure-your-aircraft.pdf)","category":"Ground Ops","tags":["picketing","tie-downs","wind","parking","hangarage"],"links":[{"label":"CAA GAP booklet: Secure your aircraft (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/secure-your-aircraft.pdf"}],"published_date":"2026-04-24","sent_at":"2026-04-24T00:46:58+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 24th April 2026","original_title":"Securing Aircraft on Ground","original_body":"Each year aircraft are damaged by wind gusts because of inattention to weather forecasts, negligence or inadequate tiedown measures. Now that ‘windy season’ is here, it 's a good time to brush up on recommended picketing techniques and other precautions against wind damage to parked aircraft.\n\nIdeally, we want to secure our aircraft in a storm-proof hangar or other suitable shelter. If appropriate hangarage isn’t available, the remaining option is to tie down your aircraft securely in a suitable location. Many aerodromes around New Zealand, however, only have a limited number of places available for securing aircraft to fixed tie-down points and these may be reserved for local aircraft. If a fixed tiedown point isn’t available, find a sheltered place to park your aircraft.\n\nThis may mean you’ll need to use a set of pickets. It’s a good idea to carry a set of pickets with you, in case you are stuck at a remote aerodrome with no other way to secure your aircraft. Your picket set should include six steel stakes, three crossover tubes, and three ropes of appropriate length –all stowed in a bag. You’ll also need a mallet or hammer . Remember to include the pickets in your weight and balance calculations, and ensure they’re well-secured in the aircraft before flight. Stow them carefully so they don’t become a problem during turbulence.\n\nTake care when choosing where you’ll picket your aircraft. Pickets can pull out under strain if the ground is soft, or becomes wet. The coiled type is difficult to get into stony ground and may be more likely to pull out in soft ground. The cross-over type of pickets are the most suitable, as they’re more likely to stay in the ground, even if it becomes wet. The underwing ropes should be led to points outboard and forward of the underwing attachment point. Hammer pickets all the way into the ground, always in front of the wing.","editor_notes":"Near-identical repost of #12/#65; kept original title (minor wording); replaced 'Now that windy season is here' with timeless phrasing."},{"id":98,"slug":"brief-passengers-for-circuit-operations","title":"Brief Passengers for Circuit Operations","summary":"Vacate the overhead to 2 NM if unsure, and brief passengers on quiet times, a 'stop talking' signal and how to point out traffic.","body_markdown":"Operating safely in or near the circuit requires good judgement and situational awareness at all times. If you arrive overhead and feel unsure, or need to rethink your approach, **don't hesitate to vacate the overhead**. Fly at least **2 NM** away from the aerodrome, hold clear, get yourself sorted, and return when ready.\n\nIf you have passengers on board, brief them clearly before flight:\n\n- Ask them **not to talk during critical phases** of flight.\n- Agree on a **hand signal that means \"stop talking\"**.\n- Ask them to **point out any aircraft** they see, and explain how you'll acknowledge it.","category":"Aerodrome & Circuit","tags":["passengers","circuit","sterile-cockpit","overhead","briefing"],"links":[],"published_date":"2026-05-01","sent_at":"2026-05-01T04:52:57+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 1st May 2026","original_title":"Safety in the vicinity of the Circuit","original_body":"Operating in or near the circuit safely requires good judgment, and maintaining situational awareness at all times. If you arrive overhead and feel unsure or need to rethink your approach, don’t hesitate to vacate the overhead. Fly at least 2 nm away from the airfield, hold clear, get yourself sorted, and return when ready.\n\nIf you have passengers on board, ensure you have briefed them clearly before flight. Ask them not to engage in conversation during critical phases, and agree on a hand signal that means “stop talking.” Include in the brief that if they see another aircraft, they should point it out and how you’ll acknowledge it","editor_notes":"Near-identical repost of #61; original title 'Safety in the vicinity of the Circuit' made more specific."},{"id":99,"slug":"a-dropped-dipstick-is-runway-fod","title":"A Dropped Dipstick Is Runway FOD","summary":"A dipstick left on a wing once fell onto the runway during take-off – always account for it; it belongs only in your hand or in the aircraft.","body_markdown":"Fuel dipsticks left on trailers, aircraft cowlings or wings create a real safety risk. On one occasion, a dipstick left on top of a wing **fell onto the runway during take-off**. Thankfully no aircraft was damaged, but it wasn't discovered until the following morning – lying on the centreline.\n\nAlways account for the dipstick during and after use. **It should only ever be in your hand or back in the aircraft** – never left anywhere else.\n\n**Further reading:**\n\n- [CAA Vector: Dip 'n check](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dip-n-check/)","category":"Ground Ops","tags":["dipstick","fod","refuelling","runway"],"links":[{"label":"CAA Vector: Dip 'n check","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/dip-n-check/"}],"published_date":"2026-05-08","sent_at":"2026-05-08T03:14:34+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 8th May 2026","original_title":"Fuel dipsticks left out of aircraft","original_body":"We’ve recently noticed a few cases of fuel dipsticks being left on trailers, aircraft cowlings, or wings. This creates a real safety risk. The other day, a dipstick was left on top of a wing and fell onto the runway during take-off. Thankfully no damage was caused to any aircraft, but it was only discovered the following morning on the centreline.\n\nThis is a good reminder to always account for the dipstick during and after use. It should only ever be in your hand or back in the aircraft, not left elsewhere.","editor_notes":"Original title 'Fuel dipsticks left out of aircraft' made more specific; reworded 'We've recently noticed' and 'The other day' as timeless."},{"id":100,"slug":"brake-leaks-flat-spots-and-fairings","title":"Brake Leaks, Flat Spots and Fairings","summary":"Check the undercarriage in every pre-flight: look for orange or pink brake fluid, feel the tyres for flat spots, and confirm the fairings are secure.","body_markdown":"We often focus on fuel, oil and control surfaces during a pre-flight, but the undercarriage deserves attention too – there are several key things to check.\n\n- **Brake fluid leaks:** check around the wheel hubs. The fluid is usually orange or pink and can be easy to miss, especially on dark tarmac.\n- **Tyres:** look closely at the tread and run your hand over the surface to feel for **flat spots**. These can develop from hard braking and aren't always easy to spot.\n- **Wheel fairings:** check they're secure and free from damage.\n\nAs always, let one of the instructing team know if you notice anything unusual.","category":"Aircraft & Engine","tags":["undercarriage","brakes","tyres","wheel-fairings","preflight"],"links":[],"published_date":"2026-05-15","sent_at":"2026-05-15T21:57:34+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 16th May 2026","original_title":"Preflight Undercarriage Check","original_body":"We often focus on fuel, oil, and control surfaces during a preflight, but it’s also important to pay attention to the undercarriage because there are a number of key things you should be checking.\n\nWhen you're doing your walk-around, take a moment to check around the wheel hubs for any signs of brake fluid leaks. The fluid is usually orange or pink and can be easy to miss, especially on dark tarmac.\n\nAs you’re checking the wheels, take a close look at the tyre tread and run your hand over the surface to feel for any flat spots. These can develop from hard braking and aren’t always easy to spot right away. Finally, check the wheel fairings are secure and free from any damage.\n\nAs always, make sure you let one of the instructing team know if you notice anything unusual.","editor_notes":"Near-identical repost of #54; original title 'Preflight Undercarriage Check' made distinct."},{"id":101,"slug":"avoid-weekend-ground-traffic-jams","title":"Avoid Weekend Ground Traffic Jams","summary":"Busy weekends at NZPP mean more ground traffic – brief your taxi route, vacate promptly and consider Hotel or Foxtrot then Golf instead of Alpha.","body_markdown":"NZPP can get busy – especially at weekends, when pilots from around the country and from our club take to the skies. That means more ground traffic too.\n\nThink about how you taxi, and how you can enter and vacate the runway promptly during busy circuit times. A thorough brief of your ground movements will help you use the aerodrome layout to its full potential.\n\n**Have you considered vacating via Hotel or Foxtrot and taxiing on Golf instead of Alpha on a busy day?**","category":"Aerodrome & Circuit","tags":["taxiing","ground-traffic","weekends","nzpp","runway-vacating"],"links":[],"published_date":"2026-05-22","sent_at":"2026-05-22T05:06:30+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 22nd May 2026","original_title":"Weekend Traffic Jams (Ground)","original_body":"NZPP can become a busy aerodrome especially on weekends as pilots from around the country and from our club take to the skies. This increases the volume of ground traffic at NZPP. Considerations need to take place about how we taxi around and enter/vacate the runway in a prompt fashion during those busy circuit times.\n\nA thorough brief of the ground movements will ensure you are using the aerodrome layout to its full capability. Have you ever considered vacating via hotel or foxtrot and using golf to taxi instead of Alpha on a busy day?","editor_notes":"Near-identical repost of #40; original title 'Weekend Traffic Jams (Ground)' tidied."},{"id":102,"slug":"managing-an-alternator-failure","title":"Managing an Alternator Failure","summary":"If the alternator fails and can't be reset per the POH, shed electrical load, land as soon as practicable, and use radio-failure procedures or a phone if needed.","body_markdown":"If you suspect an alternator failure, **follow the POH procedure**, including any approved reset attempt.\n\nIf the alternator can't be restored:\n\n- **Reduce electrical load** by switching off non-essential equipment.\n- **Manage power conservatively.**\n- **Plan to land as soon as practicable** while battery capacity remains.\n\nContinue operating the radio as normal where possible. If communications become unreliable or are lost, **transmit blind and follow standard radio failure procedures**.\n\nYou may also consider using a mobile phone to advise ATS or AFIS of your situation and intentions. This can reduce workload and improve situational awareness – particularly at aerodromes such as Paraparaumu, where AFIS is available.","category":"Emergencies","tags":["alternator","electrical-failure","radio-failure","afis","poh"],"links":[],"published_date":"2026-05-29","sent_at":"2026-05-29T05:16:03+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 29th May 2026","original_title":"Alternator Failure at Night","original_body":"If an alternator failure is suspected, follow the aircraft POH procedures, including any approved reset attempt. If the alternator cannot be restored, reduce electrical load by switching off non-essential equipment and manage power conservatively, planning to land as soon as practical while battery capacity remains.\n\nContinue operating the radio as normal where possible. If communications become unreliable or are lost, transmit blind and follow standard radio failure procedures. Mobile phone use may be considered to advise ATS or AFIS of your situation and intentions, which can help reduce workload and improve situational awareness, particularly at aerodromes such as Paraparaumu Airport where AFIS support is available.","editor_notes":"UNSURE/POSSIBLY TRUNCATED: original title was 'Alternator Failure at Night' but the body contains nothing night-specific – part of the message may be missing in the source. Retitled to match the body; check the original flyer."},{"id":103,"slug":"northbound-departures-from-runway-16","title":"Northbound Departures From Runway 16","summary":"Use NZPP's preferred VFR routes; when departing north off RWY 16, depart via downwind and cross the threshold at 1,000 ft or preferably higher.","body_markdown":"NZPP has **preferred VFR arrival and departure routes** to support the safe and orderly flow of traffic in and out of the aerodrome.\n\nThese procedures reduce the chance of conflicts, especially at busy times when circuit, training and transiting aircraft are all operating at once. For everyone's safety, **follow the preferred routes whenever practicable**.\n\n### Northbound departures off Runway 16\n\nDepart via the downwind leg and cross overhead the Runway 16 threshold at **no lower than 1,000 ft**. Climbing **above 1,000 ft is strongly encouraged**, as aircraft going around from Runway 16 may also be climbing through that altitude, which could result in a loss of separation.\n\nReview the NZPP VFR procedures in AIP New Zealand before your next flight.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Aerodrome & Circuit","tags":["vfr-routes","departures","runway-16","go-around","separation"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2026-06-12","sent_at":"2026-06-12T06:07:19+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 12th June 2026","original_title":"VFR Preferred Arrivals and Departures","original_body":"NZPP has preferred VFR arrival and departure routes to support the safe flow of traffic into and out of the aerodrome.\n\nThese procedures help reduce the likelihood of conflicts, particularly during busy periods when circuit, training, and transiting aircraft may all be operating at the same time.\n\nFor everyone's safety, pilots are encouraged to follow the preferred routes whenever practicable.\n\nImportant note for northbound departures from Runway 16:\n\nPilots should depart via the downwind leg and cross overhead the Runway 16 threshold at no lower than 1000 feet. However, climbing above 1000 feet is strongly encouraged, as aircraft conducting a go-around from Runway 16 may also be climbing through that altitude, potentially resulting in reduced separation.","editor_notes":"Near-identical repost of #55; original title 'VFR Preferred Arrivals and Departures' made distinct."},{"id":104,"slug":"check-the-tech-log-before-every-flight","title":"Check the Tech Log Before Every Flight","summary":"Check every item in the tech log before flight – not just the next 100-hour check – including both hours remaining and calendar due dates.","body_markdown":"Before every flight, do a **complete check of the aircraft technical log**. Check **all** maintenance items and inspections – not just the next 100-hour check.\n\nMany maintenance requirements are based on **hours flown, calendar dates, or whichever comes first**, so check both the remaining hours and the due dates for every item recorded in the log.\n\nIf you're ever unsure about an aircraft's status or how to interpret a tech log entry, speak with an instructor before flying.","category":"Procedures & SOPs","tags":["tech-log","maintenance","preflight","airworthiness"],"links":[],"published_date":"2026-06-19","sent_at":"2026-06-19T04:43:33+00:00","is_published":true,"source_email_subject":"Weekly Flyer - 19th June 2026","original_title":"Check the Tech Log Before Every Flight","original_body":"Before every flight, make sure you do a complete check of the aircraft technical log. Remember that it is important to check all maintenance items and inspections, not just the next 100-hour check.\n\nMany maintenance requirements are based on hours flown, calendar dates, or whichever comes first, so ensure you are checking both the remaining hours and the due dates for every item recorded in the log.\n\nIf you are ever unsure about the status of an aircraft or how to interpret an entry in the tech log, please speak with an instructor before flying.","editor_notes":"Kept original title; light copy edit."},{"id":105,"slug":"turn-the-aircraft-to-clear-the-runway-approach","title":"Turn the Aircraft to Clear the Runway Approach","summary":"Turning your head isn't enough – position the aircraft so you can see both ways before entering or crossing a runway, and ask AFIS if unsure of traffic.","body_markdown":"Before entering or crossing any runway, carry out a **thorough lookout in both directions**. This applies both when lining up to depart and when crossing a runway to get somewhere else on the aerodrome.\n\nA safe lookout takes more than just turning your head. **Manoeuvre the aircraft as necessary** so you can see clearly in both directions – physically turning the aircraft is often the only way to achieve this.\n\nAt NZPP, if you're unsure about traffic in the circuit, don't hesitate to **ask AFIS for an update** on aircraft positions to help your situational awareness.\n\n**Further reading:**\n\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)","category":"Aerodrome & Circuit","tags":["lookout","runway-entry","runway-crossing","afis"],"links":[{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"}],"published_date":"2026-06-26","sent_at":"2026-06-26T04:14:51+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 26th June 2026","original_title":"Lookout before entering a runway","original_body":"Before entering or crossing any runway, it’s important to carry out a thorough lookout in both directions. This applies for both lining up to depart, and also when crossing  a runway to get somewhere else on the aerodrome.\n\nA safe lookout requires more than just turning your head. You should manoeuvre the aircraft as necessary so you can position yourself to see clearly in both directions. Physically turning the plane is often the only way to achieve this.\n\nIf at NZPP and you’re unsure about traffic in the circuit, don’t hesitate to ask AFIS for an update on aircraft positions to help with your situational awareness.","editor_notes":"Near-identical repost of #63; original title 'Lookout before entering a runway' made distinct."},{"id":106,"slug":"take-time-over-checks-on-cold-mornings","title":"Take Time Over Checks on Cold Mornings","summary":"Don't rush checks to catch a weather window – complete each item properly, and on cold mornings wait for the oil temperature to reach the green before run-ups.","body_markdown":"Checklists are one of the simplest ways to reduce human error, standardise the way we operate and make sure nothing important gets overlooked.\n\nAs pilots, we're all keen to get airborne – especially when there's a break in the weather. It's easy to feel tempted to rush through the checks, but **taking an extra minute to complete each item properly is time well spent**.\n\nOn cold winter mornings, give the engine enough time to warm up before asking it to work hard. **Make sure the oil temperature is in the green before carrying out your run-ups.**","category":"Procedures & SOPs","tags":["checklist","warm-up","oil-temperature","winter","run-up"],"links":[],"published_date":"2026-07-10","sent_at":"2026-07-10T09:58:56+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 10th July 2026","original_title":"Checklist Use","original_body":"Checklists are one of the simplest ways to reduce human error, standardise the way we operate, and make sure nothing important gets overlooked.\n\nAs pilots, we're all keen to get airborne, especially when there's a break in the weather. It's easy to feel tempted to rush through the checks, but taking an extra minute to complete each item properly is time well spent.\n\nWith the colder winter mornings, it's also important to give the engine enough time to warm up before asking it to work hard. Make sure the oil temperature is in the green before carrying out your run-ups.","editor_notes":"Original title 'Checklist Use' made more specific; 'With the colder winter mornings' changed to 'On cold winter mornings'."},{"id":107,"slug":"check-oil-quality-and-quantity-every-pre-flight","title":"Check Oil Quality and Quantity Every Pre-Flight","summary":"Check oil quality and quantity every pre-flight, then close the oil cap finger-tight only so the next pilot can open it.","body_markdown":"Checking the oil quality and quantity is an essential part of every pre-flight. Afterwards, **close the oil cap finger-tight – no tighter**. Over-tightening can damage the cap and make it hard for the next pilot to open once the engine has heated up and cooled down.\n\nIf you can't get the cap undone during your pre-flight, grab an instructor to help.","category":"Aircraft & Engine","tags":["oil","oil-cap","preflight","engine"],"links":[],"published_date":"2026-07-17","sent_at":"2026-07-17T07:45:26+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 17th July 2026","original_title":"Checking your oil quantity","original_body":"An essential part of every pre-flight includes checking the oil quality and quantity of an aircraft. It is important that after we do this, we close the oil cap to just finger tight and no tighter. Over-tightening the cap can cause damage and make it difficult for the next pilot to open it after the engine has heated and cooled down.\n\nIf you are pre-flighting and are unable to get it unscrewed please grab an instructor who will assist you","editor_notes":"Near-identical repost of #19; original title 'Checking your oil quantity' made distinct."},{"id":108,"slug":"carb-icing-refresher-for-cold-damp-days","title":"Carb Icing Refresher for Cold, Damp Days","summary":"Carb icing is most common on cold, damp days but possible from -10°C to +25°C – use carb heat below the green arc and watch for it in SCADIE checks.","body_markdown":"The colder months are a good time for a carburettor icing refresher.\n\nCarb ice builds up inside the carburettor, restricting airflow and causing the engine to run rich. The result can be rough running, a drop in RPM and a loss of power.\n\nWhile carb icing is more common in winter, it can occur in temperatures from around **-10°C to +25°C**. The temperature inside the carburettor can be much colder than the outside air because of the venturi effect and fuel evaporation, so even a mild day can produce icing conditions.\n\nIf you suspect carb ice, **apply carb heat**. The engine may run rough at first as the ice melts and passes through the engine, but normal operation should return once the ice has cleared.\n\nRemember to:\n\n- use carb heat **below the green arc** (below 1900 RPM in the C152)\n- **check it during your run-up**\n- stay alert for signs of icing during your **SCADIE checks**\n\n**Cold, damp days are when we're most likely to see it.**\n\n**Further reading:**\n\n- [CAA Vector: Icing](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/)\n- [CAA safety message: Check the carb icing graph](https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/)","category":"Aircraft & Engine","tags":["carb-icing","carb-heat","winter","scadie","c152"],"links":[{"label":"CAA Vector: Icing","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/icing/"},{"label":"CAA safety message: Check the carb icing graph","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/safety-messages/check-the-carb-icing-graph/"}],"published_date":"2026-07-24","sent_at":"2026-07-24T07:30:48+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 24th July 2026","original_title":"Carb Icing","original_body":"With the colder months well and truly here, it’s a good time to be reminded of carburettor icing.\n\nCarb ice occurs when ice builds up inside the carburettor, restricting airflow and causing the engine to run rich. The result can be rough running, a drop in RPM, and a loss of power.\n\nWhile carb icing is more common in winter, it can occur in temperatures from around -10°C to +25°C . The temperature inside the carburettor can be much colder than the outside air due to the venturi effect and fuel evaporation, meaning even a mild day can still produce icing conditions.\n\nIf you suspect carb ice, apply carb heat. The engine may run rough initially as the ice melts and passes through the engine, but normal operation should return once the ice has cleared.\n\nRemember to use carb heat below the green arc ( below 1900 RPM in the C152 ), check it during your run-up, and stay alert for signs of icing during your SCADIE checks. Cold, damp days are when we are most likely to see it.","editor_notes":"Original title 'Carb Icing' made more specific; replaced 'With the colder months well and truly here' with timeless phrasing."},{"id":109,"slug":"dont-hesitate-to-go-around-forwarded-copy","title":"Don't Hesitate to Go Around (Forwarded Copy)","summary":"If you're not happy at any point on the approach, go around: power up, pitch up, clean up, then make the radio call once climbing away.","body_markdown":"Bumpy, gusty conditions are a good prompt to refresh both the importance and the procedure of a go-around.\n\nA go-around may be necessary for many reasons. You may have misjudged something – simple pilot error – or it could be the result of someone or something else. Whatever the reason, **if you're not happy at any time during the approach, don't hesitate to go around**. If you're ever unsure, it's always safer to power up and try again.\n\n**Keep it simple** during a go-around – don't try to do multiple things at once. Remember the order:\n\n1. **Power up**\n2. **Pitch up**\n3. **Clean up**\n4. **Radio call** – once the aircraft is climbing away and everything is in order.\n\nAlways: **Aviate, Navigate, Communicate.**","category":"Aerodrome & Circuit","tags":["go-around","landing","gusty-conditions","aviate-navigate-communicate"],"links":[],"published_date":"2026-07-31","sent_at":"2026-07-31T11:05:12+12:00","is_published":false,"source_email_subject":"Fwd: Weekly Flyer - 11th January 2025","original_title":null,"original_body":"This summer has certainly come with bumpy southerlies and gusty conditions!\n\nThis weeks safety message is a reminder of both the importance and procedure of conducting a go around. There are many times a go around may be necessary. You may have misjudged something with simple pilot error, or it could be a result of someone or something else. Whatever the reason may be, if you are not happy at any time during the approach, do not hesitate to go around. If you are ever unsure, it is always the safer move to power up and try again next time\n\nKeep it simple when you are conducting a go around, do not try to do multiple things at once. Remember the order: power up, pitch up, clean up, then make the radio call once the plane is climbing away and everything is in order. Always Aviate, Navigate, Communicate.","editor_notes":"DUPLICATE – unpublished: forwarded copy ('Fwd: Weekly Flyer - 11th January 2025') sent from a personal Gmail address on 31 Jul 2026; text identical to #32. Body mirrors the edited #32."},{"id":110,"slug":"stay-clear-of-an-occupied-runway-strip-forwarded-copy","title":"Stay Clear of an Occupied Runway Strip (Forwarded Copy)","summary":"Don't enter the runway strip while the runway is in use – hold abeam the holding point signs – and don't land until the strip is clear; go around if it isn't.","body_markdown":"The **runway strip** is defined as:\n\n> a defined area including the runway, and stopway (if a stopway is provided), that is intended— (1) to reduce the risk of damage to an aircraft running off the runway; and (2) to provide obstacle protection for aircraft flying over the runway strip during take-off or landing operations.\n\n**Do not enter the runway strip while the runway is occupied** by an aircraft taking off or landing. Hold outside the strip at the designated holding points (e.g. C, E, A1) until the runway is clear – that means **holding abeam the signs, not past them**.\n\nThe same applies when landing: **the runway strip must be unoccupied when you land**. Wait for the preceding aircraft to clear onto Alpha, and go around if it doesn't.\n\nThe runway strip boundary is shown by the **dashed line** on the Paraparaumu aerodrome ground chart in AIP New Zealand.\n\n**Further reading:**\n\n- [AIP New Zealand](https://www.aip.net.nz/)\n- [CAA: Runway safety](https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/)","category":"Aerodrome & Circuit","tags":["runway-strip","holding-point","nzpp","runway-incursion","landing"],"links":[{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"},{"label":"CAA: Runway safety","url":"https://www.aviation.govt.nz/airspace-and-aerodromes/aerodromes/runway-safety/"}],"published_date":"2026-07-31","sent_at":"2026-07-31T11:05:28+12:00","is_published":false,"source_email_subject":"Fwd: Weekly Flyer - 11th October 2024","original_title":null,"original_body":"The runway strip is defined as:\n\na defined area including the runway, and stop way (if a stop way is provided), that is intended— (1) to reduce the risk of damage to an aircraft running off the runway; and (2) to provide obstacle protection for aircraft flying over the runway strip during take-off or landing operations.\n\nIt is very important we do not enter the runway strip while the runway is occupied (either by aircraft taking off or landing). We should hold outside the runway strip at the designated holding pts e.g. C,E,A1 until the runway is clear. This means holding abeam the signs and not past them.\n\nThe same applies when we are coming in to land. The runway strip must be unoccupied when we land. This means waiting for aircraft to clear onto alpha and going around if this doesn't occur. Below is a picture of the Paraparaumu ground plate where you can see the strip indicated by the dashed line.","editor_notes":"DUPLICATE – unpublished: forwarded copy ('Fwd: Weekly Flyer - 11th October 2024') sent from a personal Gmail address on 31 Jul 2026; text identical to #18. Body mirrors the edited #18."},{"id":111,"slug":"flying-after-a-break","title":"Flying After a Break","summary":"After winter or any break, skills can be rusty even if you're current – consider a refresher with an instructor, plan more thoroughly and slow things down.","body_markdown":"Shorter winter days and fewer flying opportunities – or any other break from flying – can mean you haven't been in the cockpit as often as you'd like.\n\nEven if you're current on paper, skills such as **radio work, lookout, circuit procedures and aircraft handling** can feel rusty after a break.\n\nIf it's been a while since your last flight:\n\n- Consider **booking a refresher with an instructor**, or choose a simple local flight before tackling something more demanding.\n- Spend a bit more time on your **pre-flight planning**.\n- **Review the aircraft's systems.**\n- Don't be afraid to **slow things down**.","category":"Airmanship","tags":["currency","proficiency","refresher","rusty-skills","winter"],"links":[],"published_date":"2026-08-01","sent_at":"2026-08-01T02:19:31+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 1st August 2026","original_title":"Flying After a Break","original_body":"With winter weather bringing shorter days and fewer flying opportunities, many of you may not have been in the cockpit as often as they would have liked over the past few months.\n\nEven if you're current on paper, skills such as radio work, lookout, circuit procedures and aircraft handling can feel rusty after a break.\n\nIf it's been a while since your last flight, consider booking a refresher with an instructor or choosing a simple local flight before tackling something more demanding. Spend a bit more time on your pre-flight planning, review the aircraft's systems, and don't be afraid to slow things down.","editor_notes":"Kept original title; replaced 'With winter weather bringing shorter days... over the past few months' with timeless phrasing; fixed pronoun agreement ('you... they')."},{"id":112,"slug":"how-to-change-circuit-direction","title":"How to Change Circuit Direction","summary":"Joining doesn't commit you to landing – after one or two go-arounds consider another runway or diverting; change direction by extending downwind and turning 180° outwards.","body_markdown":"Joining an aerodrome doesn't mean you have to land there – it's an assessment of whether the conditions are acceptable. Even if you do attempt a landing, **going around once or even twice** because of an unstable approach is always the right decision. After that, it's time to consider a different runway or **diverting** to a more suitable aerodrome.\n\nIf you need to change runways, there's a safe, standard way to do it:\n\n1. **Extend downwind.**\n2. Make a **180° turn in the opposite direction** to the circuit you were flying.\n3. **Rejoin downwind** for the new runway.\n\nThis reverses your direction and positions you correctly for the new circuit. Only carry out this manoeuvre when you're **certain of other aircraft positions**, and always communicate clearly with circuit traffic so everyone is aware of your intentions.","category":"Aerodrome & Circuit","tags":["circuit","runway-change","go-around","diversion","radio"],"links":[],"published_date":"2026-08-08","sent_at":"2026-08-08T21:29:13+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 9th August 2026","original_title":"Change of Circuit Direction","original_body":"Joining an airfield doesn’t mean you have to land there. It’s an assessment that the conditions are acceptable. Even if you do attempt a landing, going around once or even twice due to an unstable approach is always the right decision. After that, it’s time to consider a different runway or diverting to a more suitable airfield.\n\nIf you need to change runways, there is a safe and standard way to do this: extend downwind, then make a 180° turn in the opposite direction to the circuit you were flying, and rejoin downwind for the new runway.\n\nThis procedure ensures you reverse direction and position yourself correctly for the new circuit. Only carry out this manoeuvre when you are certain of other aircraft positions, and always communicate clearly with traffic in the circuit so that everyone is aware of your intentions.","editor_notes":"Near-identical repost of #62; original title 'Change of Circuit Direction' reworded to be distinct."},{"id":113,"slug":"avoid-airspace-infringements","title":"Avoid Airspace Infringements","summary":"Prevent airspace infringements with thorough planning, a current VNC plus EFB backup, early departure and arrival briefs, and constant position checks.","body_markdown":"Airspace infringements are an ongoing problem. Make sure you've done your pre-flight planning and have a **current VNC** available – along with a **suitable backup if you're using an EFB**.\n\n**Brief your departure or arrival well in advance** to reduce the risk of breaching a clearance or entering airspace you aren't cleared to be in. If you're flying an aircraft fitted with a G1000, setting the **altitude bug to the relevant airspace limit** can also be a useful reminder as you approach a boundary.\n\nOnce airborne, keep checking your position against the chart and **stay ahead of the aircraft**.\n\n**Further reading:**\n\n- [CAA Vector: Zoned out](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/zoned-out/)\n- [AIP New Zealand](https://www.aip.net.nz/)","category":"Airspace & Radio","tags":["airspace","infringement","vnc","efb","g1000","flight-planning"],"links":[{"label":"CAA Vector: Zoned out","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/zoned-out/"},{"label":"AIP New Zealand","url":"https://www.aip.net.nz/"}],"published_date":"2026-08-14","sent_at":"2026-08-14T06:24:35+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 14th August 2026","original_title":"Airspace Awareness","original_body":"We have seen an increase in airspace infringements recently. We'd like to remind you to ensure you have done your preflight planning and have a current VNC available, along with a suitable backup if you are using an EFB.\n\nBrief your departure or arrival well in advance to reduce the risk of breaching a clearance or entering airspace you aren't cleared to be in. If you are flying an aircraft with a G1000 fitted, setting the altitude bug to the relevant airspace limit can also be a useful reminder as you approach a boundary.\n\nOnce airborne, keep checking your position against the chart and stay ahead of the aircraft.","editor_notes":"Original title 'Airspace Awareness' made more specific; reworded 'We have seen an increase in airspace infringements recently' as timeless."},{"id":114,"slug":"fuel-contamination-drain-settle-inspect","title":"Fuel Contamination: Drain, Settle, Inspect","summary":"Around 40% of engine failures involve fuel problems – drain after refuelling and every pre-flight, let fuel settle and check it's blue and clean.","body_markdown":"Around **40% of engine failures** are caused by fuel exhaustion, starvation or contamination.\n\n**What is fuel contamination?** It happens when foreign substances such as water, dirt or even bits of metal get into the fuel system. This can cause engine failure by blocking fuel lines, damaging components or interfering with combustion.\n\n### Best practice\n\n- **Always drain the fuel after refuelling.**\n- **Drain from all available points** during your pre-flight.\n- After refuelling, **allow the fuel time to settle**.\n- If the aircraft has been parked outside or recently refuelled, a fuel drain is especially important.\n- Check the fuel is the **correct colour (blue for avgas)**, with no water, dirt or other visible contamination.\n\nIf you find contamination, speak with an instructor. **If contamination is still present after three drains**, the aircraft may need to be checked by engineering.\n\n**Discard all drained fuel into one of the club's jerry cans** near the fuel trailers – not onto the ground.\n\n**Further reading:**\n\n- [CAA GAP booklet: Fuel management (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf)","category":"Aircraft & Engine","tags":["fuel","contamination","fuel-drain","avgas","refuelling"],"links":[{"label":"CAA GAP booklet: Fuel management (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/caa-gap-fuel-management-web.pdf"}],"published_date":"2026-08-22","sent_at":"2026-08-22T22:10:26+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 23rd August 2026","original_title":"Fuel Contamination","original_body":"Around 40% of engine failures are caused by fuel exhaustion, starvation, or contamination.\n\nWhat is fuel contamination? Fuel contamination occurs when foreign substances like water, dirt, or even bits of metal make their way into the fuel system. This can lead to engine failure by blocking fuel lines, damaging components, or interfering with combustion.\n\nBest Practise for managing fuel contamination:\n\nAlways drain the fuel after refuelling.\n\nDrain from all available points during your pre-flight.\n\nAfter refuelling, allow the fuel time to settle.\n\nIf the aircraft has been parked outside or recently refuelled, a fuel drain is especially important.\n\nCheck that the fuel is the correct colour (blue for Avgas), and ensure there is no water, dirt, or any visible contamination.\n\nIf you do find contamination, speak with an instructor. If contamination is still present after three drains, the aircraft may need to be checked by engineering.\n\nAll drained fuel should be discarded into one of the club’s jerry cans located near the fuel trailers, not onto the ground.","editor_notes":"Near-identical repost of #60; original title 'Fuel Contamination' made distinct."},{"id":115,"slug":"know-when-your-bfr-is-due","title":"Know When Your BFR Is Due","summary":"Your BFR falls due two years from your flight test date, not your licence issue date – check your logbook; renewing within 60 days keeps the original anniversary.","body_markdown":"A BFR is required **every two years** for the licence you hold. Importantly, the expiry date runs from **the date you passed your flight test**, not the date your licence was issued – so the issue date shown on your physical licence can differ from your BFR due date.\n\n**Your logbook is the best place to check your currency.** The front page should show your next BFR date, which will be exactly two years from the date of your flight test.\n\nYou can complete your BFR **up to 60 days before the expiry date**. If you do it within this 60-day window, your new BFR date is still calculated as two years from the original expiry date, rather than two years from the day you completed the review.\n\nCheck your logbook and make sure you know when your next BFR is due.\n\n**Further reading:**\n\n- [CAA Vector: All about BFRs](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/all-about-bfrs/)","category":"Procedures & SOPs","tags":["bfr","currency","logbook","licence"],"links":[{"label":"CAA Vector: All about BFRs","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/all-about-bfrs/"}],"published_date":"2026-08-28","sent_at":"2026-08-28T05:48:23+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 28th August 2026","original_title":"BFR Currency Reminders","original_body":"A BFR is required every two years for the licence you hold, and importantly, the expiry date is from the date you passed your flight test, not the date your licence was issued. The licence issue date shown on your physical licence can therefore be different from your BFR due date.\n\nYour logbook is the best place to check your currency. On the front page, you should find your next BFR date, which will be exactly two years from the date of your flight test.\n\nYou can complete your BFR up to 60 days before the expiry date. If you do it within this 60-day window, your new BFR date will still be calculated as two years from the original expiry date, rather than two years from the day you completed the review.\n\nPlease ensure you check your logbook and make sure you know when your next BFR is due.","editor_notes":"Original title 'BFR Currency Reminders' made more specific; light copy edit."},{"id":116,"slug":"helicopters-and-rotor-wash","title":"Helicopters and Rotor Wash","summary":"Rotor wash can cause strong turbulence, outflow and FOD – give hovering or low helicopters plenty of space and time, and delay your approach if needed.","body_markdown":"Accidents involving helicopters and fixed-wing aircraft – including one in the United States – are a reminder of the hazards helicopters can create for other aircraft, particularly during landing and take-off.\n\nWhile IMZ is a relatively small helicopter, **larger helicopters regularly operate through Paraparaumu**, including rescue and other specialist aircraft. Rotor wash can produce significant and sometimes unexpected turbulence, strong outflow and rapidly changing wind conditions near the ground. Loose debris can also be lifted by the downwash, creating a FOD hazard for nearby aircraft.\n\nFor fixed-wing pilots, the key takeaway is to **give hovering or low-level helicopters plenty of space and time**. If a helicopter has recently been operating near the runway or approach path:\n\n- consider where its rotor wash and outflow will go\n- communicate with the helicopter pilot where appropriate\n- don't be afraid to **delay your approach** if conditions warrant it\n\n**A helicopter that appears to be stationary can still be generating a significant amount of disturbed air.**\n\nThis is particularly important at aerodromes where helicopters and fixed-wing aircraft share the same operating area. Keep a good lookout, maintain appropriate separation, and give rotor wash the respect it deserves.\n\n**Further reading:**\n\n- [CAA: Wake turbulence – the invisible threat](https://www.aviation.govt.nz/safety/safety-education-and-advice/helicopter-safety/wake-turbulence/)\n- [CAA Vector: Beware the slowly taxiing helicopter](https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/beware-the-slowly-taxiing-helicopter/)\n- [CAA GAP booklet: Wake turbulence (PDF)](https://www.aviation.govt.nz/assets/publications/gaps/wake-turbulence.pdf)","category":"Aerodrome & Circuit","tags":["helicopters","rotor-wash","wake-turbulence","fod","separation"],"links":[{"label":"CAA: Wake turbulence – the invisible threat","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/helicopter-safety/wake-turbulence/"},{"label":"CAA Vector: Beware the slowly taxiing helicopter","url":"https://www.aviation.govt.nz/safety/safety-education-and-advice/education/vector-magazine/vector-online/beware-the-slowly-taxiing-helicopter/"},{"label":"CAA GAP booklet: Wake turbulence (PDF)","url":"https://www.aviation.govt.nz/assets/publications/gaps/wake-turbulence.pdf"}],"published_date":"2026-09-04","sent_at":"2026-09-04T04:25:19+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 4th September 2026","original_title":"Helicopters and Rotor Wash","original_body":"A recent helicopter and fixed-wing aircraft accident in the United States is a timely reminder of the hazards that helicopters can create for other aircraft, particularly during the landing and take-off phases.\n\nWhile IMZ is a relatively small helicopter, larger helicopters regularly operate through Paraparaumu, including rescue and other specialist aircraft. Helicopter rotor wash can produce significant and sometimes unexpected turbulence, strong outflow and rapidly changing wind conditions around the ground. Loose debris can also be lifted by the downwash, creating a FOD hazard for aircraft nearby.\n\nFor fixed-wing pilots, the key takeaway is to give hovering or low-level helicopters plenty of space and time. If a helicopter has recently been operating near the runway or approach path, consider where its rotor wash and outflow will go, communicate with the helicopter pilot where appropriate, and don't be afraid to delay your approach if conditions warrant it. A helicopter that appears to be stationary can still be generating a significant amount of disturbed air.\n\nIt's particularly important to remember this when operating at an aerodrome where helicopters and fixed-wing aircraft share the same operating area. Keep a good lookout, maintain appropriate separation, and give rotor wash the respect it deserves.\n\nYou can read more about it here","editor_notes":"Kept original title. Reworded 'A recent helicopter and fixed-wing aircraft accident in the United States is a timely reminder' as timeless; removed dead 'You can read more about it here' link (source article not identifiable) and added verified CAA wake turbulence links instead."},{"id":117,"slug":"crosswind-landings-know-your-limits","title":"Crosswind Landings: Know Your Limits","summary":"Crosswind skills fade – be honest about your limits, watch for changing winds at NZPP, use rudder and aileron correctly, and go around if it doesn't look right.","body_markdown":"In spring, crosswinds at NZPP start to pick up – a good time for everyone to think about their own crosswind limits and proficiency.\n\nCrosswind skills, like any other flying skill, deteriorate if we don't use them regularly. Being comfortable with crosswinds a few months ago doesn't necessarily mean you'll be just as comfortable now. **Be honest with yourself about your current limits** before you find yourself in conditions you're not comfortable with.\n\nIt's also important to keep an eye on how the weather changes during your flight. Conditions at NZPP can change quickly – you could take off in light winds and return 20 minutes later to something very different.\n\n**Set your own personal limits and stick to them.** If you're not feeling confident in crosswinds, chat to an instructor about booking a dual flight and get some practice in.\n\n### Crosswind landing technique\n\n1. Use **rudder** to keep the nose straight with the runway.\n2. Use **aileron** to maintain the centreline and allow the upwind main wheel to touch down first.\n3. Once all three wheels are on the ground, **keep aileron into wind** and maintain control throughout the rollout.\n\nAnd remember, there's nothing wrong with going around. **If the approach or landing doesn't look right, go around** and have another go.","category":"Airmanship","tags":["crosswind","landing","personal-limits","technique","go-around"],"links":[],"published_date":"2026-09-11","sent_at":"2026-09-11T01:41:34+00:00","is_published":true,"source_email_subject":"✈️ Weekly Flyer - 11th September 2026","original_title":"Crosswind Landings","original_body":"As you may have noticed, crosswind season is here\n\nWith spring here, we’re heading into the time of year when the crosswinds start to pick up. It’s a good time for everyone to have a think about their own crosswind limits and proficiency.\n\nCrosswind skills, like any other flying skill, deteriorate if we don’t use them regularly. Being comfortable with crosswinds a few months ago doesn’t necessarily mean you’ll be just as comfortable now. Make sure you’re honest with yourself about your current limits before you find yourself dealing with conditions you’re not comfortable with.\n\nIt’s also important to keep an eye on how the weather is changing during your flight. Conditions at NZPP can change quickly. You could take off with light winds and return 20 minutes later to something very different.\n\nSet your own personal limits and stick to them. If you’re not feeling confident in crosswinds, please chat to an instructor about booking a dual flight with an instructor and get some practice in.\n\nFor a crosswind landing, remember:\n\nUse rudder to keep the nose straight with the runway.\n\nUse aileron to maintain the centreline and allow the upwind main wheel to touch down first.\n\nOnce all three wheels are on the ground, keep aileron into wind and maintain control throughout the rollout.\n\nAnd remember, there is nothing wrong with going around. If the approach or landing doesn’t look right, go around and have another go.","editor_notes":"Original title 'Crosswind Landings' extended slightly; replaced 'As you may have noticed, crosswind season is here. With spring here...' with 'In spring...'; numbered technique list."}]$safety_import$::jsonb) as item;

select setval(
